prompt --application/shared_components/navigation/lists/working_copies_for_main_app_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(1421615343198967.4002)
,p_name=>'Working Copies (For Main App Menu)'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null as level1,',
'       a.working_copy_name || '' - '' || a.id  as label,',
'       wwv_flow_utilities.prepare_url(',
'           ''f?p=4000:'' ||',
'           case',
'             when :APP_PAGE_ID = 4500 ',
'              and exists ( select null ',
'                             from wwv_flow_steps ',
'                            where id = :FB_FLOW_PAGE_ID ',
'                              and flow_id = a.id ',
'                              and security_group_id = :WORKSPACE_ID )',
'             then ''4500''',
'             else ''1''',
'           end || '':'' || :app_session || '':switch_copy:::'' ||',
'           ''FB_FLOW_ID,F4000_P1_FLOW,RECENT_PAGES:'' ||',
'           a.id || '','' || a.id ) as target,',
'       ''NO'' as is_current_list_entry',
'  from wwv_working_copy_apps_dev a',
' where exists ',
'   (select null ',
'      from wwv_main_apps_dev ',
'     where id = :FB_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID',
'       and a.import_orig_app_id = id',
'   )',
'   and security_group_id = :WORKSPACE_ID',
'   and import_orig_app_id != id',
'order by a.id'))
,p_list_status=>'PUBLIC'
,p_version_scn=>80446108
);
end;
