wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(185072604868032254.4002)
,p_lov_name=>'FLOW_SUBSCRIBE_FROM_SHORTCUTS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ''- ''||',
'wwv_flow_lang.system_message(''NO_SHORTCUT'')||',
''' -'' d, 0 r from sys.dual union all',
'select flow_id||'' : ''||shortcut_name d, id r',
'from   wwv_flow_shortcuts',
'where  flow_id != nvl(:fb_flow_id,0) and flow_id in (',
'select f.id',
'from   wwv_main_apps_dev f',
'where  security_group_id = :flow_security_group_id and',
'       build_status not in (''RUN_ONLY'',''RUN_AND_HIDDEN'') and',
'       exists (',
'       select 1 from wwv_flow_developers',
'       where userid = :flow_user and flow_id is null and security_group_id = :flow_security_group_id)',
'       or',
'       exists (',
'       select 1 from wwv_flow_developers',
'       where userid = :flow_user and flow_id = f.id and security_group_id = :flow_security_group_id )',
')',
'order by 1'))
,p_source_type=>'LEGACY_SQL'
,p_location=>'LOCAL'
,p_version_scn=>72475153
);
end;
/
prompt --application/shared_components/user_interface/lovs/flow_subscribe_from_text_messages
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(2620983194638992.4002)
,p_lov_name=>'FLOW_SUBSCRIBE_FROM_TEXT_MESSAGES'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.flow_id ||'' ''||f.name||'' - ''||b.name||'' ( ''|| b.message_language ||'' )'' d,',
'       b.id r',
'  from wwv_flow_messages$ b,',
'       wwv_main_apps_dev f',
' where b.flow_id          != nvl(:FB_FLOW_ID,0)',
'   and b.flow_id           = f.id',
'   and f.build_status      not in (''RUN_ONLY'',''RUN_AND_HIDDEN'')',
'   and b.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and f.security_group_id = :FLOW_SECURITY_GROUP_ID',
'order by 1'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'R'
,p_display_column_name=>'D'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
,p_version_scn=>72475153
);
end;
