,p_name=>'COM.ORACLE.APEX.SPLITTER'
,p_display_name=>unistr('R\00E9partiteur')
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','COM.ORACLE.APEX.SPLITTER'),'')
,p_api_version=>1
