,p_ajax_function=>'wwv_flow_f4000_plugins.ajax_splitter'
,p_substitute_attributes=>true
,p_version_scn=>1088654318
,p_subscribe_plugin_settings=>true
,p_help_text=>unistr('<p>Un r\00E9partiteur divise de mani\00E8re dynamique l''espace disponible pour deux sous-r\00E9gions horizontalement ou verticalement. La r\00E9gion du r\00E9partiteur doit avoir exactement deux sous-r\00E9gions. N''importe quel mod\00E8le de r\00E9gion peut \00EAtre utilis\00E9, tant qu''il')
||unistr(' dispose d''un attribut d''ID, mais certains auront un meilleur aspect que d''autres. Evitez les mod\00E8les de r\00E9gion avec des marges et du remplissage. Si le mod\00E8le de r\00E9gion a un \00E9l\00E9ment qui encapsule les sous-r\00E9gions, un s\00E9lecteur CSS qui s\00E9lectionne ce')
||unistr('t \00E9l\00E9ment doit \00EAtre saisi dans la propri\00E9t\00E9 S\00E9lecteur.</p>')
,p_version_identifier=>'1.0'
);
