,p_process_name=>'set application badge'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_badge_class         varchar2(4000);',
'    l_working_copy_prefix varchar2(4000);',
'    l_working_copy_name   varchar2(4000);',
'begin',
'',
'    if wwv_flow_working_copy_dev.is_working_copy(',
'           p_application_id    => :FB_FLOW_ID,',
'           p_security_group_id => :WORKSPACE_ID ) then',
'        l_badge_class       := ''is-working-copy'';',
'        l_working_copy_name := wwv_flow_working_copy_dev.get_working_copy_name(',
'                                   p_application_id    => :FB_FLOW_ID,',
'                                   p_security_group_id => :WORKSPACE_ID );',
'    elsif wwv_flow_working_copy_dev.app_has_working_copy(',
'           p_application_id    => :FB_FLOW_ID,',
'           p_security_group_id => :WORKSPACE_ID ) then',
'       l_badge_class       := ''has-working-copy'';',
'       l_working_copy_name := wwv_flow_lang_dev.builder_message( ''APEXDEV.DIFF.MAIN'' );',
'    end if;',
'',
'    if l_badge_class is not null then',
'        l_working_copy_prefix := wwv_flow_lang_dev.builder_message( ''APEXDEV.DIFF.WORKING_COPY'' );',
'',
'        :P1_APPLICATION_BADGE := ''<span role="status"''||',
'                                 '' class="b-Badge b-Badge--sm b-Badge--circle '' || l_badge_class || ''"'' ||',
'                                 '' aria-label="'' || wwv_flow_escape.html_attribute( l_working_copy_prefix || '': '' || l_working_copy_name ) || ''"'' ||',
'                                 '' title="'' || wwv_flow_escape.html_attribute( l_working_copy_prefix || '': '' || l_working_copy_name ) || ''">'' ||',
'                                 ''<span class="b-Badge-value">'' || wwv_flow_escape.html( l_working_copy_name ) || ''</span>'' ||',
'                                 ''</span>'';',
'    else',
'        :P1_APPLICATION_BADGE := null;',
'    end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Erreur lors de l''ex\00E9cution du processus.')
,p_internal_uid=>220666606285624523.4002
);
