,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Les d\00E9finitions d''objet de prise en charge peuvent \00EAtre \00E9ventuellement export\00E9es avec votre application. Elles incluent l''ensemble des options et des scripts de configuration.</p>'),
'<ul>',
'<li>',
unistr('<strong>Oui</strong> Inclut les d\00E9finitions d''objet de prise en charge dans l''export d''application. Ne charge pas automatiquement les objets de prise en charge lorsqu''ils sont appel\00E9s \00E0 partir d''une ligne de commande.'),
'</li>',
'<li>',
unistr('<strong>Non</strong> N''inclut pas les d\00E9finitions d''objet de prise en charge dans l''export.'),
'</li>',
'<li>',
unistr('<strong>Oui et installer lors de l''import automatiquement</strong> Inclut les d\00E9finitions d''objet de prise en charge et un appel pour installer des objets de prise en charge dans l''export d''application. Cette option est valide uniquement pour les ins')
||unistr('tallations par ligne de commande. Lorsque l''application effectue l''import \00E0 partir de la ligne de commande, elle installe ou met \00E0 niveau automatiquement les objets de prise en charge.'),
'</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
