,p_process_error_message=>'Erreur lors de la suppression de l''application &F4000_P20_FLOW_ID..'
,p_process_when_button_id=>wwv_flow_imp.id(105027942711.4002)
,p_process_success_message=>unistr('Application &F4000_P20_FLOW_ID. supprim\00E9e.')
,p_internal_uid=>105038046820.4002
