 p_id=>wwv_flow_imp.id(1493543391999991810.4002)
,p_plug_name=>'Aide'
,p_region_css_classes=>'a-Dialog-textContent'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743.4002)
,p_plug_display_sequence=>10
,p_plug_source=>unistr('<big>Le concepteur de page est un environnement de d\00E9veloppement int\00E9gr\00E9 complet permettant de g\00E9rer et d''optimiser les pages dans vos applications &PRODUCT_NAME..</big>')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
