  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104689117393514433.4002)
,p_plug_name=>'Barre d''outils du concepteur de page'
,p_parent_plug_id=>wwv_flow_imp.id(1493543391999991810.4002)
,p_region_css_classes=>'a-Region--textContent'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>La barre d''outils en haut du concepteur de page fournit plusieurs fonctionnalit\00E9s :</p>'),
'<ul>',
unistr('  <li><strong>S\00E9lecteur de page :</strong> affiche la page en cours. Vous pouvez saisir un num\00E9ro de page directement ou cliquer sur la liste de valeurs instantan\00E9e pour s\00E9lectionner une page. </li>'),
unistr('  <li><strong>Messages :</strong> lorsque vous ajoutez un nouveau composant \00E0 une page, affiche les avertissements et erreurs en cours. Cliquer sur un message d\00E9place le focus dans l''\00E9diteur de propri\00E9t\00E9s sur l''attribut correspondant associ\00E9 \00E0 l''aver')
||unistr('tissement ou \00E0 l''erreur.</li>'),
unistr('    <li><strong>Verrou de page :</strong> indique si la page est d\00E9verrouill\00E9e (clair), verrouill\00E9e par vous (rouge) ou verrouill\00E9e par un autre d\00E9veloppeur (rouge avec une personne).<br/>'),
unistr('    Cliquez sur cette ic\00F4ne pour verrouiller ou d\00E9verrouiller la page, si elle n''est pas verrouill\00E9e par un autre d\00E9veloppeur.</li>'),
unistr('  <li><strong>Annuler les modifications :</strong> permet d''annuler la mise \00E0 jour pr\00E9c\00E9dente que vous avez effectu\00E9e dans le concepteur de page.</li>'),
unistr('  <li><strong>R\00E9tablir les modifications :</strong> permet de r\00E9appliquer la derni\00E8re mise \00E0 jour qui a \00E9t\00E9 annul\00E9e via Annuler les modifications.</li>'),
unistr('  <li><strong>Cr\00E9er :</strong> permet de cr\00E9er des pages, de copier des pages, de cr\00E9er des r\00E9gions, de g\00E9rer des composants partag\00E9s, de g\00E9rer des groupes de pages, d''ajouter des commentaires de d\00E9veloppeur et de cr\00E9er des probl\00E8mes de d\00E9veloppement')
||unistr(' d''\00E9quipe.</li>'),
unistr('  <li><strong>Utilitaires :</strong> permet de supprimer des pages, d''ex\00E9cuter la fonction de conseil pour effectuer une v\00E9rification, d''afficher le mise en cache, d''afficher l''historique de page, d''afficher le checksum de page, d''effectuer un export')
||unistr(', d''activer ou de d\00E9sactiver les info-bulles et l''onglet Mise en page, ou d''utiliser l''option Mise en page pour basculer entre les modes Deux panneaux et Trois panneaux.<br/></li>'),
unistr('<li><strong>Composants partag\00E9s :</strong> permet d''acc\00E9der \00E0 la page Composants partag\00E9s.</li>'),
unistr('  <li><strong>Enregistrer :</strong> permet d''enregistrer toutes les modifications que vous avez apport\00E9es \00E0 la page en cours.</li>'),
unistr('  <li><strong>Enregistrer et ex\00E9cuter la page :</strong> permet d''enregistrer toutes les modifications, puis d''ex\00E9cuter la page en cours.<br/>'),
unistr('    <em>Remarque : vous ne pouvez pas ex\00E9cuter de pages modales et non modales directement \00E0 l''aide de l''option Enregistrer et ex\00E9cuter la page. A la place, vous devez acc\00E9der \00E0 une page normale et l''ex\00E9cuter, puis naviguer dans l''application en cour')
||unistr('s jusqu''\00E0 la page modale ou non modale.</em></li>'),
'</ul><br/>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1498784482317536966.4002)
,p_plug_name=>'Panneaux principaux'
,p_parent_plug_id=>wwv_flow_imp.id(1493543391999991810.4002)
,p_region_css_classes=>'a-Region--textContent'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le concepteur de page est compos\00E9 de trois panneaux principaux :</p>'),
'<ul>',
unistr('  <li><strong>Panneau de gauche :</strong> comprend les onglets Affichage, Actions dynamiques, Traitement et Composants partag\00E9s. Chaque onglet affiche la liste des composants et des types de composant correspondants cr\00E9\00E9s sur la page en cours.<br/>'),
unistr('    Cliquez avec le bouton droit de la souris pour acc\00E9der aux menus contextuels. Vous pouvez \00E9galement d\00E9placer des composants vers le haut ou vers le bas dans l''arborescence pour modifier la position ou la s\00E9quence du composant s\00E9lectionn\00E9.</li>'),
'  <li><strong>Panneau central :</strong> comprend les onglets Mise en page, Recherche de page et Aide.<br/>',
unistr('   L''onglet <em>Mise en page</em> affiche une repr\00E9sentation visuelle de la page. Ajoutez de nouveaux composants de page en cliquant avec le bouton droit de la souris pour acc\00E9der au menu contextuel, ou en les faisant glisser \00E0 partir de l''onglet Gal')
||unistr('erie, en bas, et en les d\00E9posant dans l''onglet Mise en page.<br/>'),
unistr('   L''onglet <em>Recherche de page</em> permet d''effectuer des recherches dans toutes les m\00E9tadonn\00E9es de page, y compris les r\00E9gions, les \00E9l\00E9ments, les boutons, les actions dynamiques, les colonnes, etc.<br/>'),
unistr('   L''onglet <em>Aide</em> affiche l''aide propre \00E0 un attribut. Cliquez sur le nom de l''attribut dans l''\00E9diteur de propri\00E9t\00E9s pour afficher des informations et des exemples relatifs \00E0 cet attribut.</li>'),
unistr('  <li><strong>Panneau de droite :</strong> affiche l''\00E9diteur de propri\00E9t\00E9s. Utilisez l''\00E9diteur de propri\00E9t\00E9s pour mettre \00E0 jour les attributs des composants s\00E9lectionn\00E9s.<br/>'),
unistr('    Si vous s\00E9lectionnez plusieurs composants, l''\00E9diteur de propri\00E9t\00E9s affiche uniquement les attributs communs. La mise \00E0 jour d''un attribut commun entra\00EEne sa mise \00E0 jour pour tous les composants s\00E9lectionn\00E9s.</li>'),
'</ul>',
'<p>&nbsp;</p>',
unistr('<p>Vous pouvez ajuster la taille de chaque panneau en s\00E9lectionnant puis en d\00E9pla\00E7ant les r\00E9partiteurs horizontal et vertical. Pour d\00E9velopper ou r\00E9duire chaque panneau, cliquez sur le petit triangle intitul\00E9 <strong>R\00E9duire</strong> au centre de cha')
||unistr('que r\00E9partiteur.</p>'),
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_button(
 p_id=>wwv_flow_imp.id(81564783738352513.4002)
,p_button_sequence=>10
,p_button_plug_id=>wwv_flow_imp.id(153764270703903309.4002)
,p_button_name=>'GET_STARTED'
,p_button_action=>'REDIRECT_URL'
,p_button_template_options=>'#DEFAULT#:a-Button--strongLabel'
,p_button_template_id=>wwv_flow_imp.id(183227826797404355.4002)
,p_button_image_alt=>'Mise en route'
,p_button_position=>'NEXT'
,p_button_redirect_url=>'javascript:apex.navigation.openInNewWindow(''https://apex.oracle.com/go/get_started_page_designer'');'
,p_button_css_classes=>'a-Button--dark'
);
end;
