wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2017202614377443.4002)
,p_computation_sequence=>50
,p_computation_item=>'P48_BG_EXECS_COUNT_TEXT'
,p_computation_point=>'AFTER_HEADER'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case :P48_BG_EXECS_COUNT',
'    when 0 then wwv_flow_lang.runtime_message( ''WWV_FLOW_PROCESS_BACKGROUND.EXECUTIONS_0'', to_char(localtimestamp, ''ts''))',
'    when 1 then wwv_flow_lang.runtime_message( ''WWV_FLOW_PROCESS_BACKGROUND.EXECUTIONS_1'', to_char(localtimestamp, ''ts''))',
'    else        wwv_flow_lang.runtime_message( ''WWV_FLOW_PROCESS_BACKGROUND.EXECUTIONS_N'', :P48_BG_EXECS_COUNT, to_char(localtimestamp, ''ts''))',
'end'))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(211576409602179834.4002)
,p_computation_sequence=>10
,p_computation_item=>'P48_EMPTY_MANIFEST'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_manifest clob;',
'    l_start    pls_integer;',
'    l_stop     pls_integer;',
'    l_line     varchar2(4000);',
'    l_loop     pls_integer := 1;',
'begin',
'    l_manifest := wwv_flow_imp_parser.get_component_manifest(:P49_FILE_ID);',
'    l_start    := 1;',
'',
'    while sys.dbms_lob.instr(l_manifest,''--'',l_start) > 0 and l_loop < 1000 loop',
'    	l_loop  := l_loop + 1;',
'    	l_start := sys.dbms_lob.instr(l_manifest,''--'',l_start);',
'    	l_stop  := sys.dbms_lob.instr(l_manifest,chr(10),l_start);',
'    	l_line  := sys.dbms_lob.substr(l_manifest,l_stop-l_start,l_start);',
'',
'    	return ''N'';',
'',
'    	l_start := sys.dbms_lob.instr(l_manifest,''--'',l_stop+1);',
'    end loop;',
'',
'    return ''Y'';',
'exception ',
'    when others then ',
'        null;',
'end;'))
,p_compute_when=>'COMP'
,p_compute_when_type=>'REQUEST_EQUALS_CONDITION'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2017096400377441.4002)
,p_computation_sequence=>20
,p_computation_item=>'P48_MAX_SCHEDULER_JOBS'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select max_scheduler_jobs',
'  from wwv_flows',
' where security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and id                = :P49_NEW_FLOW_ID'))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(1801497026575304.4002)
,p_computation_sequence=>30
,p_computation_item=>'P48_BG_EXECS_COUNT'
,p_computation_point=>'BEFORE_HEADER'
