 p_id=>wwv_flow_imp.id(3348608179229757717.4002)
,p_plug_name=>'Source de liste de valeurs (LOV)'
,p_region_css_classes=>'lov-source-region'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_component_template_options=>'#DEFAULT#'
