,p_plug_name=>'Aide'
,p_region_template_options=>'a-Region--noTopBorder:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Le concepteur de page fournit plusieurs options de cr\00E9ation de composants de page.'),
unistr('Pour cr\00E9er des r\00E9gions, des \00E9l\00E9ments et des boutons, vous pouvez glisser-d\00E9placer des composants dans l''onglet Mise en page dans le panneau central ou utiliser les menus contextuels dans l''onglet Affichage du panneau de gauche.'),
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'TEXT',
  'show_line_breaks', 'N')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687824864514420.4002)
,p_plug_name=>unistr('Cr\00E9ation de r\00E9gions, d''\00E9l\00E9ments et de boutons \00E0 l''aide d''un glisser-d\00E9placer')
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4002)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Pour glisser-d\00E9placer des composants, proc\00E9dez comme suit :</p>'),
'<ol>',
unistr('  <li>S\00E9lectionnez l''onglet Mise en page dans le panneau central.</li>'),
unistr('  <li>Dans la galerie au bas du panneau, s\00E9lectionnez la r\00E9gion, l''\00E9l\00E9ment ou le bouton.</li>'),
unistr('  <li>Cliquez sur le composant \00E0 cr\00E9er en maintenant le bouton de la souris enfonc\00E9, puis faites-le glisser dans l''onglet Mise en page.</li>'),
unistr('  <li>D\00E9placez le composant \00E0 l''emplacement souhait\00E9 sur la page et rel\00E2chez le bouton de la souris.</li>'),
unistr('  <li>Entrez les d\00E9tails appropri\00E9s dans l''\00E9diteur de propri\00E9t\00E9s.</li>'),
unistr('  <li>Cliquez sur <strong>Enregistrer</strong> ou <strong>Enregistrer et ex\00E9cuter la page</strong>.</li>'),
'</ol>      ',
unistr('<p><em>Remarque : les composants peuvent uniquement \00EAtre d\00E9plac\00E9s dans des zones de d\00E9placement appropri\00E9es, indiqu\00E9es en jaune, d\00E9termin\00E9es par le type de composant.'),
unistr('  Une fois que vous avez pass\00E9 le pointeur de la souris sur une zone de d\00E9placement existante, l''affichage jaune est modifi\00E9 et une case noire appara\00EEt dans la zone de d\00E9placement pertinente.<br/>'),
unistr('  Si vous voulez placer le nouveau composant en regard d''un composant existant, faites glisser le nouveau composant vers la droite au niveau du composant existant, puis patientez jusqu''\00E0 ce qu''une nouvelle zone de d\00E9placement apparaisse.</em></p>'),
unistr('<p>L''onglet Mise en page inclut des menus contextuels. En s\00E9lectionnant un composant et en cliquant avec le bouton droit de la souris, vous pouvez supprimer le composant, le d\00E9placer ou le copier dans d''autres r\00E9gions ou de nouvelles r\00E9gions sur la p')
||'age.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687995506514421.4002)
,p_plug_name=>unistr('Cr\00E9ation de branchements, de calculs et de processus avant l''affichage')
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4002)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Pour cr\00E9er des branchements, des calculs et des processus \00E0 ex\00E9cuter avant l''affichage de la page, proc\00E9dez comme suit :</p>'),
'<ol>',
unistr('  <li>S\00E9lectionnez l''onglet Affichage dans le panneau de gauche.</li>'),
unistr('  <li>D\00E9veloppez le noeud <strong>Avant l''affichage</strong> en haut de l''arborescence Affichage.</li>'),
unistr('  <li>Cliquez avec le bouton droit de la souris sur Avant en-t\00EAte, Apr\00E8s en-t\00EAte ou Avant r\00E9gions pour afficher le menu contextuel de ce point de traitement.</li>'),
unistr('  <li>S\00E9lectionnez <strong>Cr\00E9er un branchement</strong>, <strong>Cr\00E9er un calcul</strong> ou <strong>Cr\00E9er un processus</strong>.</li>'),
unistr('  <li>Entrez les d\00E9tails appropri\00E9s dans l''\00E9diteur de propri\00E9t\00E9s.</li>'),
unistr('  <li>Cliquez sur <strong>Enregistrer</strong> ou <strong>Enregistrer et ex\00E9cuter la page</strong>.</li>'),
'</ol>',
unistr('<p><em>Remarque : si vous avez modifi\00E9 l''affichage par d\00E9faut pour regrouper les composants en fonction de leur type, vous devez acc\00E9der \00E0 l''onglet Traitement pour g\00E9rer les composants avant l''affichage.</em></p>'),
unistr('<p>Vous pouvez \00E9galement utiliser les menus contextuels pour dupliquer, supprimer et copier un composant dans d''autres pages.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104688010835514422.4002)
,p_plug_name=>unistr('Cr\00E9ation de branchements, de validations, de calculs et de processus de soumission de page')
