    '          from wwv_flow_plugin_files',
    '         where :P118_SCOPE       = ''PLUGIN''',
    '           and plugin_id         = :P118_PLUGIN_ID',
    '           and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
    '           and id                = :P118_ID',
    '',
    '         union all',
    '',
    '        select id, security_group_id, file_content, file_name, mime_type',
    '          from wwv_theme_files',
    '         where :P118_SCOPE          = ''THEME''',
    '           and current_app_theme_id = :P118_THEME_ID',
    '           and id                = :P118_ID',
    '       );')))).to_clob
);
