,p_validation_name=>'No duplicate names - Subscribe'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_found_name varchar2(4000);',
'begin',
'    for i in 1..wwv_flow.g_f01.count',
'    loop',
'        continue when wwv_flow.g_f03(i) != ''SUBSCRIBE'';',
'        ',
'        for c1 in ( select curr.lov_name',
'                      from wwv_flow_lists_of_values$ curr,',
'                           wwv_flow_lists_of_values$ mast',
'                     where curr.flow_id           = :FB_FLOW_ID',
'                       and curr.security_group_id = :WORKSPACE_ID',
'                       and mast.security_group_id = :WORKSPACE_ID',
'                       and mast.id                = wwv_flow.g_f01(i)',
'                       and mast.lov_name          = curr.lov_name ) ',
'        loop',
'            if l_found_name is null then ',
'                l_found_name := c1.lov_name;',
'            else ',
'                l_found_name := l_found_name||'', ''||c1.lov_name;',
'            end if;              ',
'        end loop;',
'    end loop;',
'    ',
'    if l_found_name is not null then ',
'        return wwv_flow_lang.system_message( ''F4000_LOV_NAME_EXISTS_SUBSCRIPTION'', l_found_name );',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(202846810302732194.4002)
