wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(32116100316620836.4002)
,p_name=>'Modifications de composant'
,p_region_name=>'comp_grp_components_cr'
,p_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_display_sequence=>440
,p_region_template_options=>'#DEFAULT#:a-Region--slimPadding:a-Region--noBorder'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.to_app_id,',
'       s.component_type,',
'       ( select c.name',
'           from wwv_flow_appl_export_comps c',
'          where c.workspace_id   = :WORKSPACE_ID',
'            and c.application_id = case when s.from_component_id is not null then',
'                                       s.from_app_id',
'                                   else',
'                                       s.to_app_id',
'                                   end',
'            and c.type_name      = s.component_type',
'            and c.id             = coalesce( s.from_component_id, s.to_component_id ) ) component,',
'       s.matching_status,',
'       case ',
'           when s.matching_status in ( ''FOUND'', ''NOT_FOUND'', ''UP_TO_DATE'' )',
'             or  ( s.matching_status = ''NEEDS_REFRESH'' and s.row_action is null ) then',
'               wwv_flow_lang.message(''COMP_GRP.MATCHING_STATUS.''||matching_status)',
'           when s.matching_status = ''NEEDS_REFRESH'' and s.row_action = ''ASSIGN'' then',
'               wwv_flow_lang.message(''COMP_GRP.REFRESH_ASSIGN'')',
'           when s.matching_status is null and s.row_action = ''UNASSIGN'' then',
'               wwv_flow_lang.message(''COMP_GRP.ROW_ACTION.UNASSIGN'')',
'       end matching_status_display,',
'       case s.matching_status',
'           when ''FOUND'' then ''danger''',
'           when ''NEEDS_REFRESH'' then ''warning''',
'           when ''NOT_FOUND'' then ''success''',
'           when ''UP_TO_DATE'' then ''info''',
'       end badge_state',
'  from wwv_flow_component_group_dev.preview_publish (',
'           p_master_id          => :F4000_P149_ID,',
'           p_master_app_id      => :FB_FLOW_ID ) s',
' order by',
'       case s.matching_status',
'           when ''FOUND'' then 1',
'           when ''NEEDS_REFRESH'' then 2',
'           when ''NOT_FOUND'' then 3',
'           when ''UP_TO_DATE'' then 4',
'           else 5',
'       end,',
'       s.to_app_id,',
'       s.component_type'))
,p_display_when_condition=>'F4000_P149_TEMPLATE_TYPE'
,p_display_when_cond2=>'COMPONENT_GROUP'
,p_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4002)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'Aucune modification de composant dans ce groupe de composants.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'N'
);
