,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P4320_COPY_FROM_FLOW_ID, :P498_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :F4000_P4320_COPY_FROM_FLOW_ID, :P498_COPY_FROM_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :F4000_P4320_COPY_FROM_FLOW_ID, :P498_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select ppt.id,',
'       case',
'           when ppt.security_group_id in ( 11, 12 ) then m.theme_repository',
'           else to_char( ppt.flow_id )',
'       end flow_id,',
'       ppt.page_plug_template_name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'', ppt.page_plug_template_name) to_name,',
'       ''N'' Sub',
'  from wwv_flow_page_plug_templates ppt,',
'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
' where ( ppt.flow_id, ppt.theme_id, ppt.security_group_id ) in',
'       (',
'          ( :F4000_P4320_COPY_FROM_FLOW_ID, :P498_COPY_FROM_THEME, :WORKSPACE_ID ),',
'          ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )'))
