'  </li>',
unistr('  <li>R\00E9f\00E9rence de fichier standard qui charge le fichier r\00E9duit main.min.css from /mycss/minified pour les vues de page normales et le fichier main.css from /mycss/ en mode d\00E9bogage.'),
'      <pre>/mycss/#MIN_DIRECTORY#main#MIN#.css</pre>',
'  </li>',
unistr('  <li>Requ\00EAte de support conditionnelle'),
