'  </li>',
unistr('  <li>R\00E9f\00E9rence de fichier utilisant une cha\00EEne de requ\00EAte dans l''URL qui r\00E9f\00E9rence la version de l''application, afin d''indiquer au navigateur de toujours charger le nouveau fichier et d''ignorer les fichiers pr\00E9c\00E9demment mis en m\00E9moire cache lors de ')
||unistr('la mise \00E0 niveau de l''application (et de l''incr\00E9mentation de la version).'),
'      <pre>/mycss/main.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
