wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(186970910581820894.4002)
,p_name=>'F4000_P188_CACHING'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(186970606141820893.4002)
,p_use_cache_before_default=>'NO'
,p_item_default=>'BY_USER_BY_SESSION'
,p_prompt=>unistr('Valider un mod\00E8le d''autorisation :')
,p_source=>'CACHING'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_named_lov=>'AUTH_SCHEME_CACHING'
,p_lov=>'.'||wwv_flow_imp.id(84860700520374929)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Les mod\00E8les d''autorisation sont \00E9valu\00E9s lors de la premi\00E8re utilisation dans une session.'),
unistr('L''attribut <em>Valider un mod\00E8le d''autorisation</em> v\00E9rifie si les utilisations futures entra\00EEnent des r\00E9\00E9valuations et lorsqu''un r\00E9sultat m\00E9moris\00E9 peut \00EAtre utilis\00E9 \00E0 la place.'),
unistr('La liste ci-dessous d\00E9crit les options disponibles :'),
'</p>',
'<ul>',
unistr('<li><strong>Une fois par session :</strong> l''\00E9valuation a lieu une fois, le r\00E9sultat m\00E9moris\00E9 est toujours utilis\00E9 par la suite.</li>'),
unistr('<li><strong>Une fois par vue de page :</strong> l''\00E9valuation a lieu une fois pour chaque demande trait\00E9e. Utilisez le r\00E9sultat m\00E9moris\00E9 si le mod\00E8le d''autorisation est r\00E9f\00E9renc\00E9 dans plusieurs composants sur la page.</li>'),
unistr('<li><strong>Une fois par composant :</strong> l''\00E9valuation a lieu une fois, pour chaque composant r\00E9f\00E9ren\00E7ant le mod\00E8le d''autorisation, mais le r\00E9sultat est enregistr\00E9 dans la session. Les autres demandes d''affichage ou de traitement du mod\00E8le utilis')
||unistr('ent le r\00E9sultat m\00E9moris\00E9.</li>'),
unistr('<li><strong>Toujours (pas de mise en cache) :</strong> le mod\00E8le d''autorisation sera toujours \00E9valu\00E9.</li>'),
'</ul>',
'<p>',
unistr('La valeur par d\00E9faut <em>Une fois par session</em> est la plus efficace.'),
unistr('Vous devez choisir une autre valeur si la v\00E9rification des autorisations est fonction d''un \00E9tat qui change au cours de la session ou d''autres facteurs qui ne sont pas coh\00E9rents dans l''ensemble d''une session.'),
unistr('Les options <em>Une fois par composant</em> et <em>Toujours (pas de mise en cache)</em> fournissent des informations suppl\00E9mentaires sur le composant s\00E9curis\00E9 par le mod\00E8le d''autorisation.'),
unistr('Dans les modules d''extension d''autorisation, vous pouvez utiliser les attributs <em>component.type</em>, <em>component.id</em> et <em>component.name</em> du param\00E8tre <em>t_authorization</em>.'),
unistr('Pour les types de mod\00E8le <em>Requ\00EAte SQL Existe</em> et <em>Fonction PL/SQL</em> int\00E9gr\00E9s, les variables attach\00E9es \00E9quivalentes <em>:APP_COMPONENT_TYPE</em>, <em>:APP_COMPONENT_ID</em> et <em>:APP_COMPONENT_NAME</em> sont disponibles.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1',
  'page_action_on_selection', 'NONE')).to_clob
);
