wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(186976606472820937.4002)
,p_name=>'F4000_P188_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(186976325397820915.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Type de mod\00E8le')
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHORIZATION TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHORIZATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHORIZATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHORIZATION TYPE''',
'       )',
' order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- S\00E9lectionner un type de mod\00E8le d''autorisation -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez le mode d''application de ce mod\00E8le d''autorisation. Les types int\00E9gr\00E9s admis sont les suivants :</p>'),
'<ul>',
unistr('<li><strong>Requ\00EAte SQL Existe :</strong> si la requ\00EAte renvoie au moins une ligne, le mod\00E8le d''autorisation r\00E9ussit ; si elle ne renvoie aucune ligne, le mod\00E8le \00E9choue</li>'),
unistr('<li><strong>Requ\00EAte SQL N''existe pas :</strong> si la requ\00EAte ne renvoie aucune ligne, le mod\00E8le d''autorisation r\00E9ussit ; si elle renvoie au moins une ligne, le mod\00E8le \00E9choue</li>'),
unistr('<li><strong>Fonction PL/SQL renvoyant une valeur bool\00E9enne :</strong> corps de fonction PL/SQL renvoyant la valeur TRUE, auquel cas le mod\00E8le d''autorisation r\00E9ussit, ou FALSE, auquel cas le mod\00E8le \00E9choue.</li>'),
unistr('<li><strong>L''\00E9l\00E9ment dans Expression 1 est NULL :</strong> la valeur de l''\00E9l\00E9ment nomm\00E9 dans Expression 1 est NULL.</li>'),
unistr('<li><strong>L''\00E9l\00E9ment dans Expression 1 est NOT NULL :</strong> la valeur de l''\00E9l\00E9ment nomm\00E9 dans Expression 1 est NOT NULL.</li>'),
unistr('<li><strong>La valeur de la pr\00E9f\00E9rence dans Expression 1 = Expression 2 :</strong> la valeur de la pr\00E9f\00E9rence nomm\00E9e dans Expression 1 est \00E9gale \00E0 Expression 2.</li>'),
unistr('<li><strong>La valeur de la pr\00E9f\00E9rence dans Expression != Expression 2 :</strong> la valeur de la pr\00E9f\00E9rence nomm\00E9e dans Expression 1 n''est pas \00E9gale \00E0 Expression 2.</li>'),
unistr('<li><strong>La valeur de l''\00E9l\00E9ment dans Expression 1 = Expression 2 :</strong> la valeur de l''\00E9l\00E9ment nomm\00E9 dans Expression 1 est \00E9gale \00E0 Expression 2.</li>'),
unistr('<li><strong>La valeur de l''\00E9l\00E9ment dans Expression 1 != Expression 2 :</strong> la valeur de l''\00E9l\00E9ment nomm\00E9 dans Expression 1 n''est pas \00E9gale \00E0 Expression 2.</li>'),
unistr('<li><strong>Est dans un r\00F4le ou un groupe :</strong> v\00E9rifie les noms des r\00F4les/groupes (s\00E9par\00E9s par des virgules) fournis par rapport aux r\00F4les/groupes de l''utilisateur pour lesquels la source est configur\00E9e avec l''attribut de s\00E9curit\00E9 d''application')
||unistr(' <strong>Source pour mod\00E8les de r\00F4le ou de groupe</strong>.'),
unistr('<p>Si la source est d\00E9finie sur <em>Affectations de r\00F4le utilisateur de contr\00F4le d''acc\00E8s</em>, le processus d''autorisation tiendra uniquement compte des r\00F4les d''ACL octroy\00E9s de l''utilisateur.</p>'),
unistr('<p>Sinon, il v\00E9rifiera si les groupes sont activ\00E9s en tant que groupes dynamiques pour la session (reportez-vous \00E0 APEX_AUTHORIZATION.ENABLE_DYNAMIC_GROUPS). Si l''application utilise un mod\00E8le d''authentification configur\00E9 avec Real Application Securi')
||unistr('ty (RAS), cette v\00E9rification inclura les r\00F4les de session RAS. Si l''authentification \00E0 l''aide des comptes Oracle APEX est utilis\00E9e, cette v\00E9rification inclut \00E9galement les groupes d''espaces de travail qui sont octroy\00E9s \00E0 l''utilisateur. Si l''authentif')
||unistr('ication de base de donn\00E9es est utilis\00E9e, cette v\00E9rification inclut \00E9galement les r\00F4les de base de donn\00E9es qui sont octroy\00E9s \00E0 l''utilisateur.</p>'),
unistr('<p>Le mod\00E8le d''autorisation r\00E9ussit si l''un des r\00F4les/groupes d\00E9sign\00E9s est octroy\00E9 \00E0 l''utilisateur.</p>'),
'</li>',
unistr('<li><strong>N''est pas dans le groupe :</strong> le groupe n''est pas activ\00E9 ou n''est pas octroy\00E9 \00E0 l''utilisateur. Pour plus de d\00E9tails, reportez-vous \00E0 <strong>Est dans le groupe</strong>.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
