wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1407141969590715.4002)
,p_name=>'P197_AUTO_DISMISS_SUCCESS_MSG'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(72766345492681456.4002)
,p_item_source_plug_id=>wwv_flow_imp.id(28154408216362812.4002)
,p_item_default=>'N'
,p_prompt=>unistr('Fermer automatiquement les messages de succ\00E8s')
,p_source=>'AUTO_DISMISS_SUCCESS_MSG'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Lorsque la valeur est <strong>Activ\00E9</strong>, tous les messages de succ\00E8s de l''application sont ferm\00E9s automatiquement apr\00E8s 5 secondes. Si un utilisateur interagit avec un message avant qu''il ne soit ferm\00E9, le d\00E9lai est r\00E9initialis\00E9 sur 5 second')
||'es.</p>',
unistr('<p>Lorsque la valeur est <strong>D\00E9sactiv\00E9</strong>, les messages de succ\00E8s restent visibles jusqu''\00E0 ce que l''utilisateur de l''application les ferme manuellement.</p>'),
unistr('<p>Vous devez prendre en compte l''impact potentiel de la fermeture automatique sur l''accessibilit\00E9. Certains utilisateurs risquent de ne pas voir ou lire le message de succ\00E8s avant sa fermeture et donc de manquer les informations qu''il contient. Si v')
||unistr('ous activez la fermeture automatique, envisagez de fournir aux utilisateurs des param\00E8tres leur permettant de l''accepter ou de la refuser, \00E0 l''aide de l''API JavaScript apex.message <code>setDismissPreferences</code>.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
