,p_display_when_type=>'EXISTS'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>La r\00E9g\00E9n\00E9ration d''un th\00E8me entra\00EEne la mise \00E0 jour de la d\00E9finition de th\00E8me et de mod\00E8le du th\00E8me en cours avec la d\00E9finition du th\00E8me import\00E9. Les deux th\00E8mes doivent \00EAtre compatibles et utiliser des identificateurs de mod\00E8le et de th\00E8me corresp')
||'ondants.</p>',
unistr('<p>Lorsque vous cr\00E9ez un th\00E8me, le th\00E8me import\00E9 est install\00E9 avec le th\00E8me en cours, vous permettant de passer de l''ancien th\00E8me au nouveau et de mettre en correspondance les mod\00E8les manuellement.</p>')))
