,p_cSize=>90
,p_cMaxlength=>32767
,p_cHeight=>4
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">D\00E9finit le mod\00E8le de colonne. Vous pouvez utiliser ici les cha\00EEnes de substitution suivantes :'),
'<ul class="noIndent">',
unistr('<li>#COLUMN_VALUE# - Sera remplac\00E9e par la valeur d''une colonne</li>'),
unistr('<li>#ALIGNMENT# - Indiqu\00E9e par l''utilisateur, d\00E9termine l''alignement d''une colonne</li>'),
unistr('<li>#COLNUM# - Num\00E9ro de colonne en cours</li>'),
unistr('<li>#COLUMN_HEADER# - En-t\00EAte de colonne</li>'),
'<li>#COLCOUNT# - Nombre de colonnes</li>',
unistr('<li>#ROWNUM# - Num\00E9ro de ligne en cours</li>'),
unistr('<li>#ACCESSIBLE_HEADERS# - Ajoute les en-t\00EAtes de ligne et de colonne de la cellule</li>'),
'</ul>',
'</div>',
'<div class="htmldbInfoBodyP">Exemple classique :</div>',
'<pre>&lt;td #ALIGNMENT#&gt;#COLUMN_VALUE#&lt;/td&gt;</pre>',
'',
unistr('<div class="instructiontext">Vous pouvez d\00E9finir jusqu''\00E0 quatre mod\00E8les de colonne, chacun d''eux pouvant \00EAtre conditionnel. Par exemple, vous pouvez avoir des couleurs de fond diff\00E9rentes pour les lignes paires et impaires, ou mettre en \00E9vidence les ')
||unistr('lignes qui r\00E9pondent \00E0 une condition d\00E9finie en PL/SQL.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
