,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Utilis\00E9 uniquement lorsque la condition de colonne est d\00E9finie sur Utilisation \00E0 partir d''une expression PL/SQL. Vous permet de formater les colonnes en fonction des donn\00E9es de cette ligne.</div>'),
unistr('<div class="htmldbInfoBodyP">Par exemple, si vous voulez qu''une valeur soit affich\00E9e en gras lorsque le salaire est sup\00E9rieur \00E0 2 000, vous pouvez utiliser la condition de mod\00E8le de ligne suivante :</div>'),
'<pre>',
':SAL &gt; 2000',
'</pre>',
unistr('<div class="htmldbInfoBodyP">Les noms de colonne doivent \00EAtre r\00E9f\00E9renc\00E9s \00E0 l''aide de la syntaxe de variable attach\00E9e ; en d''autres termes, utilisez :SAL plut\00F4t que #SAL#. Vous pouvez \00E9galement utiliser ici la cha\00EEne de substitution #ROWNUM#.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'NONE')).to_clob
);
