,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez les URL de feuille de style CSS pour les ic\00F4nes personnalis\00E9es \00E0 charger sur chaque page. Chaque URL doit \00EAtre \00E9crite sur une nouvelle ligne. Si vous indiquez une version r\00E9duite du fichier, vous pouvez utiliser la cha\00EEne de substitution')
||unistr(' <code>#MIN#</code> afin d''inclure <code>.min</code> ou <code>#MIN_DIRECTORY#</code> afin d''inclure <code>minified/</code> dans l''URL de fichier pour une vue de page normale et une cha\00EEne vide si la page est visualis\00E9e en mode d\00E9bogage. Vous avez \00E9ga')
||unistr('lement acc\00E8s \00E0 la cha\00EEne de substitution <code>#APP_VERSION#</code> si vous voulez inclure la version de l''application dans l''URL de fichier.</p>'),
'',
unistr('<p>Les URL de fichier saisies ici remplacent la cha\00EEne de substitution <code>#THEME_CSS#</code> dans le mod\00E8le de page.</p>'),
'',
unistr('<p>Remarque : vous n''avez pas besoin d''ajouter les balises <code>link</code> de d\00E9but ou de fin, mais simplement l''URL de fichier.</p>'),
'',
'<p>',
'Exemples :',
'<ul>',
unistr('  <li>R\00E9f\00E9rence de fichier standard qui charge le fichier \00E0 partir du r\00E9pertoire de th\00E8mes :'),
'      <pre>#THEME_IMAGES#icons.css</pre>',
'  </li>',
unistr('  <li>R\00E9f\00E9rence de fichier standard qui charge le fichier r\00E9duit icons.min.css \00E0 partir de /mycss/minified/ pour les vues de page normales et le fichier icons.css \00E0 partir de /mycss/ en mode d\00E9bogage.'),
'      <pre>/mycss/#MIN_DIRECTORY#icons#MIN#.css</pre>',
'  </li>',
unistr('  <li>Requ\00EAte de support conditionnelle :'),
'      <pre>[media="only screen and (max-device-width: 480px)"]/mycss/smartphone_icons.css</pre>',
'  </li>',
unistr('  <li>R\00E9f\00E9rence de fichier utilisant une cha\00EEne de requ\00EAte dans l''URL qui r\00E9f\00E9rence la version de l''application, afin d''indiquer au navigateur de toujours charger le nouveau fichier et d''ignorer tous les fichiers pr\00E9c\00E9demment mis en m\00E9moire cache lor')
||unistr('s de la mise \00E0 niveau de l''application (et de l''incr\00E9mentation de la version) :'),
'      <pre>/mycss/icons.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
