wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1875072844167005.4002)
,p_name=>'P509_AUTH_CONFIG_PROCEDURE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(107178726415706930.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Proc\00E9dure de configuration')
,p_source=>'AUTH_CONFIG_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>32
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le nom d''une proc\00E9dure qui configure l''authentification \00E0 l''ex\00E9cution.'),
unistr('Le code ci-dessous est destin\00E9 \00E0 une application qui impl\00E9mente l''architecture colocative et prend'),
unistr('en charge diff\00E9rentes m\00E9thodes de <em>connexion via un r\00E9seau social</em> pour les locataires.'),
unistr('Il utilise le nom de domaine de l''URL pour extraire les donn\00E9es de configuration (exemples d''URL : '),
'https://cust-01.example.com, https://cust-02.example.com, etc.) :',
'</p><pre><code>',
'procedure my_auth_config (',
'    p_conf in out nocopy apex_authentication.t_configuration )',
'is',
'    l_host varchar2(32767) := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'begin',
'    for i in ( select discovery_url,',
'                      auth_scheme_name,',
'                      credential,',
'                      tenant_id',
'                 from customer_tenants',
'                where hostname = l_host )',
'    loop',
'        p_conf.authentication_name := i.auth_scheme_name;',
'        p_conf.substitutions := apex_t_varchar2 (',
'                                    ''DISCOVERY_URL''       , i.discovery_url,',
'                                    ''CREDENTIAL_STATIC_ID'', i.credential );',
'        p_conf.tenant_id := i.tenant_id;',
'    end loop;',
'end my_auth_config;',
'</code></pre><p>',
unistr('La proc\00E9dure peut modifier 3 attributs du param\00E8tre IN/OUT <code>p_conf</code>,'),
'qui sont tous facultatifs :',
'<ul>',
'    <li><code>authentication_name</code> :',
unistr('    Affectez le nom d''un mod\00E8le d''authentification dans votre application'),
unistr('    qui sera utilis\00E9 \00E0 la place du mod\00E8le par d\00E9faut.'),
unistr('    L''option <em>Basculer dans la session</em> doit \00EAtre activ\00E9e pour ce mod\00E8le.'),
'    </li><li><code>substitutions</code> :',
'    Affectez des paires nom/valeur avec <code>apex_t_varchar2</code>.',
'    &PRODUCT_NAME. substitue chaque valeur <code>#NAME#</code> dans les attributs du ',
unistr('    mod\00E8le d''authentification par la valeur associ\00E9e.'),
unistr('    Le mod\00E8le int\00E9gr\00E9 de <em>connexion via un r\00E9seau social</em> emploie <code>CREDENTIAL_STATIC_ID</code>'),
unistr('    pour utiliser la banque d''informations d''identification correspondante au lieu de celle configur\00E9e '),
unistr('    dans le mod\00E8le.'),
'    </li><li><code>tenant_id</code> :',
unistr('    D\00E9finissez cet ID de locataire dans la session (reportez-vous \00E0 <code>apex_session.set_tenant_id</code>).'),
'    </li>',
'</ul>',
'</p><p>',
unistr('Dans les applications contenant une proc\00E9dure de configuration d''authentification,'),
unistr('vous ne pouvez pas modifier le mod\00E8le d''authentification par le biais de l''URL (exemple : <code>f?p=100:1:1234:APEX_AUTHENTICATION=myauth</code>).'),
'</p><p>',
unistr('La proc\00E9dure de configuration d''authentification est ex\00E9cut\00E9e au moins une fois par session, lors de la premi\00E8re demande.    '),
unistr('Cependant, &PRODUCT_NAME. peut \00E9galement l''appeler \00E0 d''autres occasions.'),
unistr('Dans de tels cas, les m\00EAmes valeurs doivent \00EAtre d\00E9finies \00E0 chaque appel.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
