wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107203001185706981.4002)
,p_name=>'P509_PAGE_PROTECTION_ENABLED'
,p_item_sequence=>200
,p_item_plug_id=>wwv_flow_imp.id(107273213161009008.4002)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Protection de statut de session'
,p_source=>'PAGE_PROTECTION_ENABLED_Y_N'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Lorsque vous s\00E9lectionnez <strong>Activ\00E9</strong>, cette fonctionnalit\00E9 utilise les attributs de page Protection d''acc\00E8s de page et les attributs d''\00E9l\00E9ment Protection de statut de session conjointement avec les checksums ')
||unistr('situ\00E9s dans les URL f?p=. L''activation de cette fonctionnalit\00E9 pr\00E9vient la fraude d''URL et les acc\00E8s non autoris\00E9s, ainsi que la modification du statut de session.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Lorsque vous s\00E9lectionnez <strong>D\00E9sactiv\00E9</strong>, le moteur &PRODUCT_NAME. ne prend pas en compte les attributs de page Protection d''acc\00E8s de page ou les attributs d''\00E9l\00E9ment Protection de statut de session au cours de')
||unistr(' l''ex\00E9cution de votre application et n''inclut pas de checksums dans la section f?p= des URL.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Si la valeur de cet attribut est <strong>Activ\00E9</strong> et que vous la remplacez par <strong>D\00E9sactiv\00E9</strong>, la fonctionnalit\00E9 de protection de statut de session est d\00E9sactiv\00E9e, mais tous les attributs de page Protec')
||unistr('tion d''acc\00E8s de page et tous les attributs d''\00E9l\00E9ment Protection de statut de session ne sont pas modifi\00E9s.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Si la valeur de cet attribut est <strong>D\00E9sactiv\00E9</strong> et que vous la remplacez par <strong>Activ\00E9</strong>, la fonctionnalit\00E9 de protection de statut de session est activ\00E9e, mais tous les attributs de page Protectio')
||unistr('n d''acc\00E8s de page et tous les attributs d''\00E9l\00E9ment Protection de statut de session ne sont pas modifi\00E9s, pour \00EAtre observ\00E9s au cours de l''ex\00E9cution de l''application.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Il existe toutefois une exception \00E0 la r\00E8gle g\00E9n\00E9rale voulant que les attributs d''\00E9l\00E9ment Protection de statut de session ne produise d''effet que lorsque la fonctionnalit\00E9 Protection de statut de session a la valeur <stro')
||unistr('ng>Activ\00E9</strong>. Si l''attribut d''un \00E9l\00E9ment a la valeur <strong>Prot\00E9g\00E9</strong>, ce statut est toujours en vigueur. En d''autres termes, les \00E9l\00E9ments prot\00E9g\00E9s ne peuvent pas \00EAtre d\00E9finis \00E0 partir de l''URL, quelle que soit la valeur affect\00E9e \00E0 la f')
||unistr('onctionnalit\00E9 Protection de statut de session (Activ\00E9 ou D\00E9sactiv\00E9).</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
