,p_display_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP"><strong>Autoriser les URL cr\00E9\00E9es apr\00E8s</strong> indique la date et l''heure apr\00E8s lesquelles les liens avec signet ne permettent plus d''acc\00E9der aux pages de cette application, si le lien avec signet contient un checksum et')
||unistr(' que la fonctionnalit\00E9 Protection de statut de session de l''application est activ\00E9e.'),
'<p>',
unistr('Les signets cr\00E9\00E9s avant cette date/heure ne peuvent pas \00EAtre utilis\00E9s pour acc\00E9der \00E0 cette application si le lien avec signet contient un checksum et que la fonctionnalit\00E9 Protection de statut de session de l''application est activ\00E9e.'),
'<p>',
unistr('Les signets qui ne contiennent pas de checksums ou les signets qui contiennent des checksums superflus ne sont pas affect\00E9s par cet attribut. Leur utilisabilit\00E9 est d\00E9termin\00E9e par d''autres crit\00E8res.'),
'<p>',
unistr('Un attribut d''application masqu\00E9 (un salt de checksum) est utilis\00E9 lors du calcul et de la v\00E9rification ult\00E9rieure des checksums inclus dans les URL <code>f?p=</code> g\00E9n\00E9r\00E9es au cours de l''affichage de la page. Les checksums sont inclus lorsque la f')
||unistr('onctionnalit\00E9 Protection de statut de session de l''application est activ\00E9e. Vous pouvez r\00E9initialiser cet attribut de salt de checksum \00E0 tout moment \00E0 l''aide du bouton <strong>Invalider les signets</strong>. Une telle r\00E9initialisation entra\00EEnera l''\00E9c')
||unistr('hec de toute URL avec signet contenant des checksums g\00E9n\00E9r\00E9s ant\00E9rieurement lorsque ceux-ci seront utilis\00E9s par la suite pour acc\00E9der \00E0 l''application.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'VALUE',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
