wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(384789975408553245.4002)
,p_name=>'P509_REJOIN_EXISTING_SESSIONS'
,p_is_required=>true
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(6354406057147715.4002)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Rejoindre des sessions'
,p_source=>'REJOIN_EXISTING_SESSIONS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'REJOIN_EXISTING_SESSIONS'
,p_lov=>'.'||wwv_flow_imp.id(492680965578161495)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Utilisez cet attribut pour contr\00F4ler si &PRODUCT_NAME. doit prendre en charge les URL d''application qui ne contiennent pas d''ID de session..'),
'S''il est possible de rejoindre des sessions, &PRODUCT_NAME. tente d''utiliser le cookie de session pour rejoindre une session existante,',
'lorsqu''une URL ne contient pas d''ID de session.',
'</p>',
'<p>',
unistr('Un param\00E8tre de niveau instance plus restrictif remplace la valeur de niveau page.'),
'</p>',
'<p>',
'    <strong>Remarque :</strong>',
unistr('L''activation de l''option Rejoindre des sessions expose votre application \00E0 de possibles failles de s\00E9curit\00E9, car cela peut permettre \00E0 des individus malveillants de prendre le contr\00F4le des sessions d''utilisateur final existantes. Pour plus d''informat')
||'ions, reportez-vous aux sections Rejoin Sessions du chapitre "Managing Application Security" dans le manuel App Builder User''s Guide.',
'</p>',
'',
'<p>',
'Les options disponibles sont les suivantes :    ',
'</p>',
'<ul>',
unistr('    <li><strong>Valeur par d\00E9faut de l''application</strong> - '),
unistr('     Le param\00E8tre de niveau application s''applique.'),
'    </li>',
unistr('    <li><strong>D\00E9sactiv\00E9</strong> - '),
unistr('    Si l''URL ne contient pas d''ID de session, &PRODUCT_NAME. cr\00E9e une session.'),
'    </li>',
unistr('    <li><strong>Activ\00E9 pour les sessions publiques</strong> - '),
unistr('    Si l''URL acc\00E8de \00E0 une page publique et ne contient pas d''ID de session,'),
unistr('    &PRODUCT_NAME. tente d''utiliser le cookie de session existant \00E9tabli pour cette application.'),
unistr('    Pour les applications contenant des pages publiques et authentifi\00E9es, un ID de session est d\00E9fini une fois l''utilisateur final authentifi\00E9.'),
unistr('    &PRODUCT_NAME. rejoint la session \00E0 l''aide du cookie uniquement si celle-ci n''est pas encore authentifi\00E9e.'),
'    </li>',
unistr('    <li><strong>Activ\00E9 pour toutes les sessions</strong> - '),
unistr('    Si l''URL ne contient pas d''ID de session, &PRODUCT_NAME. tente d''utiliser le cookie de session existant \00E9tabli pour cette application,'),
'    si les conditions suivantes sont remplies :',
'    <ul>',
'        <li>',
unistr('        La protection de statut de session est activ\00E9e pour l''application et l''URL inclut un checksum valide.'),
'        Pour les signets publics,',
unistr('        le niveau de protection d''\00E9l\00E9ment le plus restrictif doit \00EAtre <em>Non restreint</em> ou <em>Checksum requis - niveau application</em>.'),
'        </li>',
'        <li>',
unistr('        Ou l''URL ne contient pas de charge utile (paires de valeurs de donn\00E9es, effacement du cache ou param\00E8tre de demande).'),
'        </li>',
'    </ul>',
unistr('    Ce param\00E8tre n\00E9cessite \00E9galement que l''attribut Imbriquer dans les cadres soit d\00E9fini sur Autoriser \00E0 partir de la m\00EAme origine ou sur Refuser pour l''application.'),
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
