,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Utilisez cet attribut pour contr\00F4ler si le navigateur est autoris\00E9 \00E0 afficher les pages de votre application dans un cadre :'),
'<ul>',
unistr('<li><strong>Refuser :</strong> la page ne peut pas \00EAtre affich\00E9e dans un cadre, quel que soit le site \00E0 l''origine de la tentative.</li>'),
unistr('<li><strong>Autoriser \00E0 partir de la m\00EAme origine :</strong> la page peut uniquement \00EAtre affich\00E9e dans un cadre de la m\00EAme origine que la page elle-m\00EAme.</li>'),
unistr('<li><strong>Autoriser :</strong> la page peut \00EAtre affich\00E9e dans n''importe quel cadre.</li>'),
'</ul>',
'</p>',
'<p>',
unistr('L''affichage des pages dans des cadres peut \00EAtre utilis\00E9 de fa\00E7on abusive avec des attaques de type "d\00E9tournement de clics",'),
unistr('lorsqu''un individu malveillant utilise plusieurs couches pour amener des utilisateurs \00E0 cliquer sur un bouton ou un lien sur une autre page lorsqu''ils essaient de cliquer sur la couche sup\00E9rieure.'),
unistr('Par cons\00E9quent, l''individu malveillant d\00E9tourne les clics (et/ou les touches) pr\00E9vus pour leur page et les dirige vers une autre page.'),
'</p>',
'<p>',
unistr('Les pages de bo\00EEte de dialogue sont souvent affich\00E9es dans un iFrame,'),
'ce qui normalement ne fonctionne pas avec la valeur d''attribut Refuser.',
unistr('L''attribut <em>Autoriser l''imbrication dans un cadre</em> du mod\00E8le d''une page de bo\00EEte de dialogue d\00E9finit si Autoriser \00E0 partir de la m\00EAme origine doit \00EAtre utilis\00E9 \00E0 la place de Refuser'),
unistr('pour les pages utilisant ce type de mod\00E8le.'),
unistr('Pour vous prot\00E9ger contre les d\00E9tournements de clics,'),
unistr('&PRODUCT_NAME. utilise un checksum propre \00E0 la page dans les URL de page de bo\00EEte de dialogue.'),
'</p>',
'<p>',
unistr('Remarque : cette fonctionnalit\00E9 exige des navigateurs modernes qui prennent en charge la variable de r\00E9ponse d''en-t\00EAte HTTP "X-Frame-Options".'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
