'                 from wwv_flow_temp_files ',
'                where name = :p519_file_browse )',
'    loop',
'        :p519_screenshot_url := ''pwa/''||c1.filename;',
'',
'        wwv_flow_imp_shared.create_app_static_file(',
'            p_flow_id      => :fb_flow_id,',
'            p_file_name    => :p519_screenshot_url,',
'            p_mime_type    => c1.mime_type,',
'            p_file_charset => ''utf-8'',',
'            p_file_content => c1.blob_content );',
'    end loop;',
'end;'))
