'   and p.flow_id           =  :FB_FLOW_ID',
'   and p.security_group_id =  :WORKSPACE_ID',
'   and :P707_TEMPLATE_TYPE =  ''LIST''',
') x',
'where',
'(',
':P707_FIND is null or ',
'instr(upper(region_name),upper(:P707_FIND)) > 0 or',
'instr(upper(list_name),upper(:P707_FIND)) > 0 or',
