 p_id=>875.4002
,p_name=>unistr('Tester une r\00E9f\00E9rence Web REST')
,p_alias=>'TEST-REST-WEB-REFERENCE'
,p_step_title=>unistr('Tester une r\00E9f\00E9rence Web REST')
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(213347710073256556)
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function p875_test_rest(){',
'',
'    var get = new htmldb_Get(null,$v(''pFlowId''),''APPLICATION_PROCESS=P875_TEST_REST'',0);',
'',
