,p_process_name=>'Update AD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_rc_type    varchar2(2);',
'   l_rc_id      number;',
'begin',
'   for i in 1..wwv_flow.g_f01.count loop',
'',
'      l_rc_type   := substr(wwv_flow.g_f01(i),1,2);',
'      l_rc_id     := substr(wwv_flow.g_f01(i),4);',
'',
'      if l_rc_type = ''CR'' then',
'         wwv_flow_hint.insert_ad_from_cr(',
'            p_application_id  => :FB_FLOW_ID,',
'            p_rc_id           => l_rc_id,',
'            p_attr_to_include => :P907_INCLUDE_IN_UPDATE );',
'      elsif l_rc_type = ''IR'' then',
'         wwv_flow_hint.insert_ad_from_ir(',
'            p_application_id  => :FB_FLOW_ID,',
'            p_rc_id           => l_rc_id,',
'            p_attr_to_include => :P907_INCLUDE_IN_UPDATE );',
'      end if;',
'',
'   end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Echec de la mise \00E0 jour du dictionnaire d''attributs.')
,p_process_when_button_id=>wwv_flow_imp.id(253950306918283249.4002)
,p_process_success_message=>unistr('Dictionnaire d''attributs mis \00E0 jour.')
,p_internal_uid=>260805523043847181.4002
);
end;
