,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(115636830645483045.4002)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Bind Variables- Save Interactive Grid Data'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :APEX$ROW_STATUS = ''U'' then',
'        wwv_flow_collection.update_member(',
'            p_collection_name => ''SET_BIND_VALUES'',',
'            p_seq             => :SEQ_ID,',
'            p_c001            => :BIND_VARIABLE,',
'            p_c002            => :BIND_VALUE );',
'    end if;',
'end;'))
,p_attribute_05=>'Y'
,p_attribute_06=>'N'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1719956629642123.4002
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1720093948642124.4002)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
,p_attribute_02=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1720093948642124.4002
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1718949765642113.4002)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch bind variables'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_bind_values   wwv_flow_global.vc_map;',
'    l_binds         wwv_flow_report_query.t_binds;',
'    l_bind_name     varchar2( 255 );',
'begin',
'',
'    for bind_variable in (',
'        select c001 as name,',
'               c002 as value',
'          from wwv_flow_collections ',
'         where collection_name = ''SET_BIND_VALUES'' )',
'    loop',
'        l_bind_values( bind_variable.name ) := bind_variable.value;',
'    end loop;',
'',
'    l_binds := ',
'        wwv_flow_report_query.get_report_query_binds(',
'            p_shared_query_id   => :P1112_SHARED_QUERY_ID,',
'            p_flow_id           => :FB_FLOW_ID );',
'',
'    wwv_flow_collection.create_or_truncate_collection(',
'        p_collection_name => ''SET_BIND_VALUES'');',
'    ',
'    l_bind_name := l_binds.first;',
'    ',
'    while l_bind_name is not null loop ',
'        ',
'        wwv_flow_collection.add_member(',
'             p_collection_name => ''SET_BIND_VALUES'',',
'             p_c001            => l_bind_name,',
'             p_c002            => case ',
'                                  when l_bind_values.exists( l_bind_name )',
'                                  then l_bind_values( l_bind_name )',
'                                  end);',
'        ',
'        l_bind_name := l_binds.next( l_bind_name );',
'    ',
'    end loop;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1718949765642113.4002
);
end;
