,p_region_css_classes=>'a-Alert--inlineDialog a-Alert--noTitle'
,p_region_template_options=>'#DEFAULT#:a-Alert--warning:a-Alert--wizard'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4002)
,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Cette fonctionnalit\00E9 existe d\00E9j\00E0 dans votre application. Pour r\00E9installer la fonctionnalit\00E9, vous devez d''abord enlever les pages existantes, les composants partag\00E9s et l''option de construction <strong>&P1317_BUILD_OPTION.</strong>. Pour enlever l')
||unistr('es composants, proc\00E9dez comme suit :'),
'<ol>',
unistr('  <li>Acc\00E9dez \00E0 Composants partag\00E9s.</li>'),
unistr('  <li>Acc\00E9dez \00E0 Logique d''application, Options de construction.</li>'),
'  <li>Cliquez sur <strong>&P1317_BUILD_OPTION.</strong>.</li>',
'  <li>Cliquez sur <strong>Enlever des composants</strong>.<br>',
unistr('    &nbsp;&nbsp;Cliquez sur la case \00E0 cocher <em>Oui : enlever les composants</em>.<br>'),
'    &nbsp;&nbsp;Cliquez sur <strong>Enlever les composants</strong>.</li>',
unistr('  <li>Dans Cr\00E9er/Modifier une option de construction, cliquez sur <strong>Supprimer</strong>.<br>'),
'    &nbsp;&nbsp;Cliquez sur <strong>Supprimer l''option de construction</strong>.</li>',
'</ol>',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
