,p_computation_sequence=>30
,p_computation_item=>'P1317_BUILD_OPTION'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_return varchar2(4000) := wwv_flow_lang.system_message(''FEATURE'')||'': '';',
'begin',
'  if :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_acl then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.ACCESS_CONTROL'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_feedback then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.FEEDBACK'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_activity_report then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.ACTIVITY_REPORTING'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_email_report then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.EMAIL_REPORT'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_job_report then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.JOB_REPORT'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_about_page then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.ABOUT_PAGE'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_configuration then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.CONFIGURATION_OPTIONS'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_theme_style then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.THEME_STYLE_SELECTION'');',
'  elsif :P2500_PAGE_TYPE = wwv_flow_app_feature_v3.c_push_notifications then',
'    l_return := l_return || wwv_flow_lang.system_message(''FEATURE.PUSH_NOTIFICATIONS'');',
'  end if;',
'',
'  return l_return;',
'end;',
''))
);
