,p_plug_name=>'A propos de'
,p_region_template_options=>'#DEFAULT#:a-Region--sideRegion:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="border-bottom-width: 0;"'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Cr\00E9ez un service <strong>SQL compatible REST</strong> pour ex\00E9cuter le code SQL ou PL/SQL d\00E9fini dans les composants &PRODUCT_NAME. sur une base de donn\00E9es Oracle distante</p>'),
'',
unistr('<p><strong>Configuration requise :</strong> la base de donn\00E9es distante doit inclure Oracle REST Data Services (ORDS) version 20.3 ou sup\00E9rieure en frontal, et la fonctionnalit\00E9 <em>SQL compatible REST</em> doit \00EAtre activ\00E9e. L''ensemble du code SQL e')
||unistr('t PL/SQL est envoy\00E9 \00E0 l''instance ORDS, qui l''ex\00E9cute sur la base de donn\00E9es distante.</p>'),
'',
unistr('<p>Les r\00E9f\00E9rences SQL compatibles REST sont stock\00E9es au niveau de l''espace de travail et sont donc visibles dans toutes les applications</p>'),
'',
unistr('<p>Lorsque vous exportez une application, les r\00E9f\00E9rences SQL compatibles REST utilis\00E9es sont ajout\00E9es au fichier d''export. Si vous exportez une application et l''importez dans un autre espace de travail, &PRODUCT_NAME. v\00E9rifie si l''espace de travail c')
||unistr('ible contient d\00E9j\00E0 des r\00E9f\00E9rences SQL compatibles REST avec le m\00EAme <strong>ID statique</strong>. S''il existe d\00E9j\00E0 une r\00E9f\00E9rence SQL compatible REST, l''application l''utilise. Dans le cas contraire, la r\00E9f\00E9rence est cr\00E9\00E9e dans l''espace de travail cibl')
||'e.</p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
