unistr('Le code ci-dessous est destin\00E9 \00E0 une application qui impl\00E9mente une architecture colocative'),
unistr('et prend en charge diff\00E9rentes variations de l''<em>URL endpoint</em> pour les locataires.'),
unistr('Le nom de domaine est modifi\00E9 dans l''URL en fonction du client (exemples d''URL : '),
'https://cust-01.example.com, https://cust-02.example.com) :',
'</p><pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
'end;',
'</code></pre><p>',
unistr('La proc\00E9dure peut modifier 2 attributs du param\00E8tre in/out <code>p_config</code>,'),
'tous deux facultatifs :',
'<ul>',
'    <li><code>base_url</code> :',
'    Modifie l''<em>URL endpoint</em>.',
'    </li>',
'    <li><code>substitutions</code> :',
unistr('    Affecte des paires nom/valeur \00E0 l''aide de <code>apex_t_varchar2</code>.'),
'    &PRODUCT_NAME. substitue chaque <code>#NAME#</code> dans l''<em>URL de base</em> ou l''<em>URL endpoint</em>.',
'    </li>',
'</ul>',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
