wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2545228608236501.4002)
,p_name=>'P1621_USE_DB_CREDENTIAL'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4002)
,p_prompt=>unistr('Utiliser les informations d''identification de base de donn\00E9es')
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>'wwv_flow_db_version.c_has_utl_http_credential'
,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Activez cette option pour utiliser les cl\00E9s secr\00E8tes stock\00E9es dans les informations d''identification de base de donn\00E9es.'),
unistr('    Les informations d''identification disponibles peuvent \00EAtre obtenues \00E0 partir de la vue de dictionnaire'),
'    <strong>ALL_CREDENTIALS</strong>. Utilisez le package <strong>DBMS_CREDENTIAL</strong> ',
unistr('    pour tenir \00E0 jour les informations d''identification de base de donn\00E9es.</p>'),
'<p>',
unistr('    <em>L''utilisation d''informations d''identification de base de donn\00E9es modifie le comportement des demandes HTTP effectu\00E9es et le fonctionnement des informations d''identification Web :</em></p>'),
'<ul>',
'    <li>',
unistr('        Si des informations d''identification de base de donn\00E9es sont utilis\00E9es, toutes les demandes HTTP '),
unistr('        sont effectu\00E9es dans le contexte du sch\00E9ma d''analyse de l''application, et non dans celui du'),
unistr('        moteur APEX. Autrement dit, des <em>listes de contr\00F4le d''acc\00E8s r\00E9seau PL/SQL</em> doivent \00EAtre accord\00E9es'),
unistr('        au sch\00E9ma d''analyse de l''application. Pour plus d''informations, reportez-vous \00E0 la documentation sur'),
'        <strong>DBMS_NETWORK_ACL_ADMIN</strong>.</li>',
'    <li>',
unistr('        Les informations d''identification de base de donn\00E9es sont enti\00E8rement g\00E9r\00E9es par la base de donn\00E9es, &PRODUCT_NAME.'),
unistr('        n''a pas acc\00E8s aux cl\00E9s secr\00E8tes stock\00E9es. Etant donn\00E9 que &PRODUCT_NAME. ne peut donc pas imposer '),
unistr('        l''attribut <strong>Valide pour les URL</strong>, ce dernier est d\00E9sactiv\00E9 lorsque des'),
unistr('        informations d''identification de base de donn\00E9es sont utilis\00E9es.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
