wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3367384134004646.4002)
,p_name=>'P1621_VALID_FOR_URLS'
,p_item_sequence=>230
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Valide pour les URL'
,p_source=>'VALID_FOR_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>64
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>&PRODUCT_NAME. v\00E9rifie si l''URL pour laquelle les informations d''identification sont utilis\00E9es au moment de l''ex\00E9cution correspond \00E0 l''une des URL de cette liste. Si l''URL ne correspond pas, &PRODUCT_NAME. g\00E9n\00E8re une erreur.</p>'),
unistr('<p>Placez chaque URL sur une nouvelle ligne. Le point d''extr\00E9mit\00E9 d''URL utilis\00E9 doit commencer par l''une des URL indiqu\00E9es ici.</p>'),
'<p>Exemple :</p>',
'<pre>',
'https://www.example.com/restapis/my-protected-api',
'https://www.example.com/allowed-urls',
'</pre>',
unistr('<p>Si les informations d''identification sont utilis\00E9es pour appeler un service REST situ\00E9 \00E0 l''adresse <strong>https://www.example.com/restapis/my-protected-api/restendpoint</strong> ou <strong>https://www.example.com/allowed-urls/page1</strong>, elle')
||unistr('s peuvent \00EAtre employ\00E9es et l''appel r\00E9ussit.</p>'),
unistr('<p>Si les informations d''identification sont utilis\00E9es pour appeler un service REST situ\00E9 \00E0 l''adresse <strong>https://localhost/myapis/test</strong> ou <strong>https://dev.example.com/myapis/test</strong>, elles <em>ne peuvent pas</em> \00EAtre utilis\00E9es')
||unistr(' et &PRODUCT_NAME. g\00E9n\00E8re une erreur.</p>'),
'<p>Exemple :</p>',
'<pre>',
'ldap://ldap.mycompany.com',
'ldaps://ldap.mycompany.com:389',
'</pre>',
unistr('<p>ldap:// et ldaps:// correspondent au "protocole" permettant d''indiquer les URL autoris\00E9es pour un serveur LDAP.</p>'),
unistr('<p>Si vous modifiez cette valeur, vous devrez saisir de nouveau la cl\00E9 secr\00E8te du client.</p>')))
,p_inline_help_text=>unistr('Pour modifier cette valeur, vous devez de nouveau saisir la cl\00E9 secr\00E8te du client.')
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
