,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_schema varchar2(128);',
'begin',
'    l_schema := wwv_flow_credential.find_schema_for_db_credential( ',
'                    p_db_credential_name        => :P1621_INSTANCE_DB_CRED_NAME,',
'                    p_db_credential_is_instance => true );',
'    return true;',
'exception',
'    when others then',
'        return false;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Les informations d''identification de base de donn\00E9es "&P1621_INSTANCE_DB_CRED_NAME." n''existent pas ou ne sont pas accessibles pour le moteur APEX.')
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    wwv_flow_db_version.c_has_utl_http_credential',
'and :REQUEST in ( ''Create'',''Update'')',
'and :P1621_USE_DB_CREDENTIAL                   = ''Y''',
'and :P1621_INSTANCE_DB_CRED_NAME        is not null',
'and nvl(:P1621_DB_CREDENTIAL_TYPE, ''SCHEMA'' )  = ''INSTANCE'''))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(1759810826531746.4002)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
