wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(15698603515328105.4002)
,p_plug_name=>unistr('D\00E9finitions de chargement des donn\00E9es')
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4002)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select ',
'  l.id,',
'  l.name,',
'  l.target_type,',
'  case l.target_type',
'  when ''TABLE'' then',
'      l.table_name',
'  when ''COLLECTION'' then',
'      l.collection_name',
'  end target_name,',
'  ''icon-sc-data-loading'' icon_class,',
'       ''f?p=4000:1820:''||:app_session||',
'           ''::NO:1820:P1820_ID:''||l.id edit_link,',
'  --',
'       case when l.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_load_tables sub',
'          where sub.reference_id      = l.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when l.reference_id is not null then',
'           case',
'               when master.version_scn = l.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != l.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       --',
'  coalesce( l.last_updated_on, l.created_on ) last_updated,',
'  coalesce( l.last_updated_by, l.created_by ) last_updated_by',
'  from wwv_flow_load_tables l,',
'       wwv_flow_load_tables master,',
'       wwv_flow_data_profiles p,',
'       messages',
' where p.id = l.data_profile_id',
'   and l.flow_id                = :FB_FLOW_ID',
'   and l.security_group_id      = :WORKSPACE_ID',
'   and l.reference_id           = master.id (+)',
'   and l.security_group_id      = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
