,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Cette option permet aux d\00E9veloppeurs de sp\00E9cifier une colonne pouvant \00EAtre utilis\00E9e pour v\00E9rifier les donn\00E9es en fonction de la version figurant dans la table sous-jacente. Elle est particuli\00E8rement utile lorsque vous effectuez des t\00E9l\00E9chargements')
||unistr(' dans une table r\00E9guli\00E8rement mise \00E0 jour.</p>'),
unistr('<p>Lors d''une mise \00E0 jour, la colonne utilis\00E9e pour v\00E9rifier l''acc\00E8s simultan\00E9 est interrog\00E9e et compar\00E9e \00E0 la valeur de la base de donn\00E9es pour cette colonne, avant la validation de l''enregistrement. Si la colonne est modifi\00E9e entre l''interrogation ')
||unistr('de l''enregistrement et le t\00E9l\00E9chargement des donn\00E9es, l''enregistrement est signal\00E9 et non valid\00E9. Si aucune colonne n''est indiqu\00E9e, le t\00E9l\00E9chargement de donn\00E9es met syst\00E9matiquement \00E0 jour tous les enregistrements, \00E9crasant \00E9ventuellement les modific')
||unistr('ations effectu\00E9es par les autres utilisateurs.</p>')))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
