,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Une <strong>d\00E9finition de chargement de donn\00E9es</strong> permet aux d\00E9veloppeurs d''ajouter la fonctionnalit\00E9 <em>Chargement des donn\00E9es</em> '),
unistr('    \00E0 une application Oracle APEX.'),
'</p>',
'<p>',
unistr('    Une d\00E9finition de chargement de donn\00E9es comporte des informations sur l''emplacement de stockage des donn\00E9es t\00E9l\00E9charg\00E9es '),
unistr('    ainsi que des d\00E9tails sur la m\00E9thode de chargement, par exemple s''il faut '),
unistr('    <em>ajouter</em> des donn\00E9es ou <em>remplacer</em> les donn\00E9es existantes. '),
unistr('    Elle peut \00EAtre r\00E9f\00E9renc\00E9e dans les processus de page <strong>Chargement des donn\00E9es</strong> '),
'    ainsi qu''avec le package PL/SQL <code>APEX_DATA_LOADING</code>.',
'</p>',
'<p>',
unistr('    Le <strong>profil de donn\00E9es</strong> contient des informations sur la structure '),
unistr('    des donn\00E9es t\00E9l\00E9charg\00E9es et sur les colonnes suppl\00E9mentaires'),
unistr('     reposant sur une expression SQL, une requ\00EAte SQL, des recherches ou des r\00E8gles de transformation.'),
'</p>',
'<p>',
unistr('    Une fois la d\00E9finition de chargement de donn\00E9es cr\00E9\00E9e, l''assistant vous permet '),
unistr('    d''ajouter une page Chargement des donn\00E9es \00E0 votre application. La page cr\00E9\00E9e peut \00EAtre personnalis\00E9e par la suite afin de r\00E9pondre '),
'    aux besoins de votre application.',
'</p>'))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_ai_enabled=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
