,p_name=>'P1850_NAME'
,p_is_required=>true
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(612109101966174795.4002)
,p_use_cache_before_default=>'NO'
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_return varchar2(4000);',
'    l_cnt    number;',
'begin',
'    l_return := :FB_FLOW_ID||''_BUCKET'';',
'',
'    select count(*) into l_cnt',
'      from wwv_remote_servers',
'     where name = l_return',
'       and security_group_id = :FLOW_SECURITY_GROUP_ID;',
'',
'    if l_cnt > 0 then',
'        wwv_flow_exec_web_src_utils.add_or_increase_seq_suffix(l_return);',
'    end if;',
' ',
'return l_return;',
'end;',
'    '))
