,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>'rtrim(substr(:P1850_BUCKET_URL,instr(:P1850_BUCKET_URL,''/b/'')+3),''/'')'
);
