,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>unistr('Cette option entra\00EEnera la migration des fichiers d''application statiques existants de la base de donn\00E9es vers Object Storage. Si vous choisissez de ne pas migrer les fichiers pour le moment, vous pouvez utiliser l''option Synchroniser sous T\00E2ches dan')
||unistr('s la page Composants partag\00E9s - Fichiers d''application statiques.')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
