wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3292574859489450.4002)
,p_name=>'P1921_WEB_SOURCE_TYPE'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(3292099913489445.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Type de source de donn\00E9es REST')
,p_source=>'WEB_SOURCE_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_MODULE_TYPES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''WEB_SOURCE.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''WEB SOURCE TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''WEB SOURCE TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('D\00E9termine le type de source de donn\00E9es REST.'),
'<ul>',
unistr('<li><strong>HTTP simple</strong> d\00E9signe des flux de donn\00E9es HTTP simples. &PRODUCT_NAME. suppose que toutes les donn\00E9es sont renvoy\00E9es avec la premi\00E8re demande et que le serveur ne prend pas en charge le tri et le filtrage c\00F4t\00E9 serveur ni d''autres f')
||unistr('onctionnalit\00E9s avanc\00E9es de service REST. Tous les param\00E8tres et les d\00E9tails d''appel doivent \00EAtre configur\00E9s manuellement.</li>'),
unistr('<li><strong>Oracle REST Data Services</strong> (ORDS) d\00E9signe les services RESTful fournis par ORDS. Ces services REST suivent la <em>norme REST Oracle</em>, ce qui signifie que les op\00E9rations GET, POST, PUT ou DELETE sont normalis\00E9es. Le tri et le f')
||unistr('iltrage c\00F4t\00E9 serveur sont pris en charge. &PRODUCT_NAME. peut tirer parti de ces fonctionnalit\00E9s en d\00E9l\00E9guant des clauses ORDER BY et des filtres d''\00E9tat au service REST.</li>'),
unistr('<li><strong>Requ\00EAte SQL compatible REST</strong> d\00E9signe une source REST reposant sur une requ\00EAte SQL ex\00E9cut\00E9e sur une r\00E9f\00E9rence SQL compatible REST. &PRODUCT_NAME. prend en charge le filtrage et la pagination, mais pas le langage DML sur ces points ')
||unistr('d''extr\00E9mit\00E9.</li>'),
unistr('<li><strong>Service REST Oracle Cloud Applications (SaaS)</strong> d\00E9signe les services RESTful fournis par Oracle Cloud Applications (SaaS). Utilisez ce type de service Web pour int\00E9grer les services REST d''Oracle SaaS \00E0 votre application &PRODUCT_N')
||'AME.. &PRODUCT_NAME. prend en charge la pagination pour ces services.</li>',
unistr('<li><strong>Service REST Oracle Cloud Infrastructure (OCI)</strong> d\00E9signe les services Web RESTful fournis par Oracle Cloud Infrastructure. Utilisez ce type de service Web pour int\00E9grer les services REST d''OCI (par exemple, acc\00E8s \00E0 la banque d''obje')
||unistr('ts) \00E0 votre application &PRODUCT_NAME.. &PRODUCT_NAME. prend en charge la pagination pour ces services.</li>'),
unistr('<li><strong>Service REST OData</strong> d\00E9signe un service REST impl\00E9mentant le protocole Open Data (OData), qui est une norme OASIS approuv\00E9e ISO/CEI d\00E9finissant un ensemble de meilleures pratiques pour la construction et l''utilisation d''API RESTful')
||unistr('. <em>&PRODUCT_NAME. ne prend actuellement en charge que les API d''<em>extraction</em> (lecture de donn\00E9es). Les op\00E9rations DML pour OData ne sont pas encore prises en charge.</em></li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
