wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3467008942842405.4002)
,p_name=>'P1921_URL_PATH_PREFIX'
,p_is_required=>true
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(3292099913489445.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Pr\00E9fixe de chemin d''URL')
,p_source=>'URL_PATH_PREFIX'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>65
,p_cMaxlength=>500
,p_read_only_when=>'P1921_WEB_SOURCE_TYPE'
,p_read_only_when2=>'NATIVE_REST_ENABLED_SQL_QUERY'
,p_read_only_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Le pr\00E9fixe de chemin d''URL est propre \00E0 la source de donn\00E9es REST. Les points d''extr\00E9mit\00E9 d''URL de toutes les op\00E9rations au sein de la source de donn\00E9es REST partagent le m\00EAme pr\00E9fixe de chemin d''URL. Quand la source de donn\00E9es REST est appel\00E9e, ')
||'&PRODUCT_NAME. construit l''URL comme suit :',
'</p>',
'<ol>',
'    <li><strong>URL de base</strong> de l''objet <strong>Serveur distant</strong></li> ',
unistr('    <li><strong>Pr\00E9fixe de chemin d''URL</strong> de la <strong>source de donn\00E9es REST</strong></li>'),
unistr('    <li><strong>Mod\00E8le d''URL</strong> d\00E9fini dans l''<strong>op\00E9ration</strong> des sources de donn\00E9es REST</li>'),
'</ol>',
'<div>',
'    <p>Exemple :</p>',
'    <p>',
unistr('        Sources de donn\00E9es REST :'),
'        <ol>',
'            <li><code>http://api.example.com:8080/root/<strong>service1/</strong>method1</code></li>',
'            <li><code>http://api.example.com:8080/root/<strong>service2/</strong>method1</code></li>',
'            <li><code>http://api.example.com:8080/root/<strong>service2/</strong>method4</code></li>',
'        </ol> ',
'    </p>',
'    <p>',
unistr('        Les parties d''URL <strong>service1/</strong> ou <strong>service2/</strong> sont communes \00E0 une source de donn\00E9es REST. Elles seront donc utilis\00E9es en tant que <strong>pr\00E9fixe de chemin d''URL</strong>.'),
'    </p>',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3467120952842406.4002)
,p_name=>'P1921_REMOTE_SERVER_ID'
,p_is_required=>true
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(3292099913489445.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Serveur distant'
,p_post_element_text=>'<a id="P1921_EDIT_REMOTE_SERVER_BUTTON" class="a-Button a-Button--noLabel a-Button--small a-Button--withIcon" href="#" onClick="apex.page.submit(''APPLY_CHANGES_EDIT_REMOTE_SERVER'');" tabindex="0" ><span class="a-Icon icon-edit" aria-hidden="true"></s'
||'pan><span class="u-VisuallyHidden">Modifier un serveur distant</span></a>'
,p_source=>'REMOTE_SERVER_ID'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select name, id ',
'  from wwv_remote_servers',
' where server_type = case when :P1921_WEB_SOURCE_TYPE = ''NATIVE_REST_ENABLED_SQL_QUERY'' then ''REMOTE_SQL'' else ''WEB_SERVICE'' end',
'   and security_group_id = :FLOW_SECURITY_GROUP_ID'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- S\00E9lectionner -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Choisissez un objet <strong>Serveur distant</strong> pour cette source de donn\00E9es REST. &PRODUCT_NAME. fractionne le point d''extr\00E9mit\00E9 d''URL en une premi\00E8re partie (serveur distant) et en une seconde partie (propre au service). Un objet <strong>S')
||'erveur distant</strong> peut contenir plusieurs ',
unistr('    points d''extr\00E9mit\00E9 de service. Il est recommand\00E9 d''affecter le m\00EAme objet de serveur distant aux sources de donn\00E9es REST quand elles partagent les'),
unistr('    m\00EAmes serveur, port et pr\00E9fixes de chemin d''URL.'),
'</p>',
'<div>',
'    <p>Exemple :</p>',
'    <p>',
unistr('        Sources de donn\00E9es REST :'),
'        <ol>',
'            <li><code><strong>http://api.example.com:8080/root/</strong>service1/method1</code></li>',
'            <li><code><strong>http://api.example.com:8080/root/</strong>service2/method1</code></li>',
'            <li><code><strong>http://api.example.com:8080/root/</strong>service2/method4</code></li>',
'        </ol> ',
'    </p>',
'    <p>',
unistr('        La partie <strong>http://api.example.com:8080/root/</strong> de l''URL est commune aux trois sources de donn\00E9es REST.'),
unistr('        Elle peut donc \00EAtre utilis\00E9e en tant qu''objet Serveur distant et recevoir un nom. Si, par la suite, les trois sources de donn\00E9es REST doivent \00EAtre d\00E9plac\00E9es vers un autre serveur, il suffit de modifier l''objet Serveur distant.'),
'    </p>',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
