wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(242268510007871834.4002)
,p_plug_name=>unistr('Op\00E9rations')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr(' Une <strong>op\00E9ration</strong> de source REST contient les vraies informations sur le gestionnaire de services Web externes. Pour les services REST, une op\00E9ration est formul\00E9e \00E0 partir de la combinaison d''un mod\00E8le d''URL et d''un verbe HTTP (GET, POS')
||unistr('T). Une source de donn\00E9es REST peut contenir plusieurs op\00E9rations.'),
' </p>',
unistr(' <p>Les op\00E9rations peuvent \00EAtre mises en correspondance avec des <strong>op\00E9rations de base de donn\00E9es</strong>, ce qui permet aux composants &PRODUCT_NAME. de s\00E9lectionner la bonne op\00E9ration. Les \00E9tats, \00E9tats interactifs ou calendriers CSS s\00E9lection')
||unistr('neront l''op\00E9ration mise en correspondance avec l''op\00E9ration de base de donn\00E9es <em>Extraire des lignes</em>.</p>'),
'<p>',
unistr('Les param\00E8tres d\00E9finis au niveau du module sont partag\00E9s entre toutes les op\00E9rations au sein de cette source de donn\00E9es REST. Les param\00E8tres au niveau de l''op\00E9ration s''appliquent uniquement \00E0 cette op\00E9ration.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249280093175575814.4002)
,p_plug_name=>unistr('Source REST JSON ORDS h\00E9rit\00E9 : taille de page fixe inconnue')
,p_region_template_options=>'#DEFAULT#:a-Alert--danger:a-Alert--horizontal'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4002)
,p_plug_display_sequence=>20
,p_plug_source=>unistr('<p>Cette source REST ORDS utilise la <em>syntaxe JSON h\00E9rit\00E9e</em> ; les donn\00E9es sont renvoy\00E9es en s''adaptant \00E0 la page, dont la taille fixe est d\00E9termin\00E9e par le serveur. Pour que les composants &PRODUCT_NAME. s''affichent correctement, &PRODUCT_NAME')
||unistr('. doit conna\00EEtre la <em>taille de page</em>. Acc\00E9dez \00E0 la section <strong>Avanc\00E9</strong> et d\00E9finissez la taille de page appropri\00E9e. Contactez l''administrateur du service REST pour obtenir ces informations.')
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from ',
'wwv_flow_web_src_modules',
'where security_group_id = :FLOW_SECURITY_GROUP_ID and id = :P1922_WEB_SRC_MODULE_ID and web_source_type=''NATIVE_ORDS'' and attribute_01 = ''Y'' and :P1922_ORDS_FIXED_PAGE_SIZE is null and :P1922_ID is not null'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249280151163575815.4002)
,p_plug_name=>unistr('Source REST JSON ORDS h\00E9rit\00E9 : petite taille de page fixe')
,p_region_template_options=>'#DEFAULT#:a-Alert--warning:a-Alert--horizontal'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4002)
,p_plug_display_sequence=>30
,p_plug_source=>unistr('<p>Cette source de donn\00E9es REST ORDS utilise la <em>syntaxe JSON h\00E9rit\00E9e</em> ; les donn\00E9es sont renvoy\00E9es en s''adaptant \00E0 la page, dont la taille fixe est de &P1922_ORDS_FIXED_PAGE_SIZE. et est d\00E9termin\00E9e par le serveur. Pour les \00E9tats avec une tail')
||unistr('le de page plus grande, plusieurs demandes HTTP devront \00EAtre adress\00E9es au service REST afin d''afficher la page. Vous pouvez contacter l''administrateur de service REST pour fournir une taille de page plus grande.')
