,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Indiquez si les composants &PRODUCT_NAME. peuvent extraire toutes les lignes, ex\00E9cutant ainsi plusieurs demandes HTTP, \00E0 partir de cette op\00E9ration de source REST. '),
'</p>',
'<p>',
unistr('   Ce choix vaut pour les sources REST qui renvoient leurs donn\00E9es en les adaptant \00E0 la page, \00E0 l''instar d''Oracle REST Data Services. Par exemple, un graphique ou la vue Grouper par des \00E9tats interactifs doit pouvoir acc\00E9der \00E0 toutes les lignes pour ')
||unistr('calculer des r\00E9sultats corrects. Lorsque le service REST renvoie ses donn\00E9es en les adaptant \00E0 la page, plusieurs demandes HTTP doivent \00EAtre adress\00E9es au service REST. '),
'</p>',
'<p>',
unistr('    Si la source REST ne renvoie que quelques pages, qui sont extraites en quelques secondes, cette solution convient dans la plupart des cas. Pour ces services, d\00E9finissez cet attribut sur <strong>Activ\00E9</strong>. A l''inverse, lorsque le service RES')
||unistr('T renvoie des milliers de lignes sur des centaines de pages, extraire toutes les lignes prendrait trop de temps. Pour de tels services, d\00E9finissez l''attribut sur <strong>D\00E9sactiv\00E9</strong>.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
