wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3632686934550912649.4002)
,p_name=>'P1922_REST_OPERATION'
,p_is_required=>true
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(3500552115076908.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('M\00E9thode HTTP')
,p_source=>'OPERATION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_HTTP_METHODS'
,p_lov=>'.'||wwv_flow_imp.id(225847729464891335)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- S\00E9lectionner -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Op\00E9ration ou <em>m\00E9thode</em> HTTP (GET, POST, PUT, DELETE) \00E0 ex\00E9cuter sur le service Web REST. La combinaison de mod\00E8le d''URL et d''op\00E9ration HTTP identifie l''op\00E9ration au sein d''une source de donn\00E9es REST. Une source de donn\00E9es REST peut conteni')
||unistr('r le m\00EAme mod\00E8le d''URL pour diff\00E9rentes op\00E9rations HTTP et diff\00E9rents mod\00E8les d''URL pour la m\00EAme op\00E9ration HTTP.'),
'</p>',
'<p>',
unistr('    Voici une br\00E8ve explication des m\00E9thodes HTTP et de leur utilisation dans les services REST. Il ne s''agit que de conventions. En principe, les services REST les respectent, mais les impl\00E9mentations r\00E9elles peuvent \00EAtre diff\00E9rentes. Consultez touj')
||unistr('ours la documentation du service REST auquel vous pr\00E9voyez d''acc\00E9der pour conna\00EEtre les m\00E9thodes pouvant \00EAtre appel\00E9es et leur fonctionnement.'),
'</p>',
'<ul>',
'    <li>',
unistr('        <strong>GET</strong> sert \00E0 extraire des donn\00E9es du service REST. La m\00E9thode GET est cens\00E9e \00EAtre idempotente ; le fait de l''appeler ne change rien c\00F4t\00E9 serveur. Pour cette raison, les demandes GET peuvent g\00E9n\00E9ralement \00EAtre mises en cache ou a')
||unistr('ppel\00E9es plusieurs fois. Par ailleurs, en temps normal, elles ne comportent <em>pas</em> de corps de demande.'),
'    </li>',
'    <li>',
unistr('        <strong>POST</strong> sert d''ordinaire \00E0 cr\00E9er une ressource sur le serveur. Toutefois, en pratique, les demandes POST peuvent'),
unistr('        \00EAtre utilis\00E9es pour toutes sortes de choses. Elles n\00E9cessitent g\00E9n\00E9ralement l''envoi d''un corps de demande.'),
'    </li>',
'    <li>',
unistr('        <strong>PUT</strong> sert d''ordinaire \00E0 <em>remplacer</em> une nouvelle ressource sur le serveur. Un corps de demande est g\00E9n\00E9ralement requis. Vous devez transmettre <em>tous</em> les attributs au serveur. Les attributs manquants seront proba')
||unistr('blement \00E9crits sous la forme de valeurs NULL ou vides.'),
'    </li>',
'    <li>',
unistr('        <strong>DELETE</strong> sert d''ordinaire \00E0 enlever une ressource sur le serveur. Aucun corps de demande n''est g\00E9n\00E9ralement requis.'),
'    </li>',
'    <li>',
unistr('        <strong>PATCH</strong> sert d''ordinaire \00E0 <em>modifier</em> une nouvelle ressource sur le serveur. Les services REST ne fournissent pas tous des points d''extr\00E9mit\00E9 PATCH. Un corps de demande, contenant des informations sur les attributs \00E0 mod')
||unistr('ifier et sur les valeurs \00E0 d\00E9finir, est requis. PATCH permet ainsi d''effectuer des mises \00E0 jour partielles sur une ressource de serveur. Il n''existe pas de fa\00E7on standard de pr\00E9senter le corps de demande d''un point d''extr\00E9mit\00E9 PATCH. Consultez la doc')
||'umentation du service REST avant de l''appeler. ',
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
