wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1716859903469901.4002)
,p_name=>'P1923_PROFILE_COLUMN'
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(2228992349790506.4002)
,p_prompt=>unistr('Colonne de profil de donn\00E9es')
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.name d,',
'       c.name r',
'  from wwv_flow_data_profile_cols c,',
'       wwv_flow_data_profiles     p,',
'       wwv_flow_web_src_modules   w',
' where c.data_profile_id   = p.id',
'   and c.flow_id           = p.flow_id',
'   and c.security_group_id = p.security_group_id',
'   and w.data_profile_id   = p.id',
'   and w.flow_id           = p.flow_id',
'   and w.security_group_id = p.security_group_id',
'    --',
'   and w.id                = :P1923_WEB_SRC_MODULE_ID',
'   and p.flow_id           = :FB_FLOW_ID',
'   and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
' order by c.sequence'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- S\00E9lectionner -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2228496871790501.4002)
,p_name=>'P1923_DATA_TYPE'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(2228816282790505.4002)
,p_use_cache_before_default=>'NO'
,p_item_default=>'VARCHAR2'
,p_prompt=>unistr('Type de donn\00E9es')
,p_source=>'DATA_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_PARAM_DATA_TYPES'
,p_lov=>'.'||wwv_flow_imp.id(2225637019805602)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Choisissez le type de donn\00E9es de la valeur du param\00E8tre. Lorsqu''une valeur autre que de type VARCHAR2 '),
unistr('    est envoy\00E9e \00E0 l''API REST, elle est convertie en cha\00EEne \00E0 l''aide du '),
'    <strong>masque de format de sortie</strong>.',
'</p>',
'<p>Options disponibles :</p>',
'<dl>',
unistr('    <dt>Cha\00EEne</dt>'),
unistr('    <dd>Les valeurs de cha\00EEne contiennent des donn\00E9es alphanum\00E9riques.</dt>'),
unistr('    <dt>Num\00E9rique</dt>'),
unistr('    <dd>Les valeurs num\00E9riques sont des valeurs d\00E9cimales ou enti\00E8res.</dd>'),
'    <dt>Date</dt>',
'    <dd>Les valeurs de date contiennent la date et l''heure mais pas les fractions de seconde ni les informations sur le fuseau horaire.</dd>',
'    <dt>Horodatage</dt>',
'    <dd>Les valeurs d''horodatage contiennent la date et l''heure (avec les fractions de seconde) mais pas les informations sur le fuseau horaire.</dd>',
'    <dt>Horodatage avec fuseau horaire</dt>',
'    <dd>Les valeurs d''horodatage avec fuseau horaire contiennent la date et l''heure (avec les fractions de seconde) ainsi que les informations sur le fuseau horaire.</dd>',
unistr('    <dt>Bool\00E9en</dt>'),
unistr('    <dd>Les valeurs bool\00E9ennes correspondent \00E0 <strong>True</strong> ou \00E0 <strong>False</strong>.</dd>'),
'    <dt>Binaire</dt>',
unistr('    <dd>Le contenu binaire comporte des donn\00E9es autres que de type Texte (images, octets de donn\00E9es brutes) et est repr\00E9sent\00E9 sous forme de cha\00EEne au format <em>Base64</em>.</dd>'),
'</dl>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
