wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226131367554626803.4002)
,p_name=>'P1925_ROW_SELECTOR'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(225858059630926546.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('S\00E9lecteur de ligne')
,p_source=>'ROW_SELECTOR'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Pour un profil de donn\00E9es renvoyant une table, saisissez l''expression permettant de s\00E9lectionner la collection de lignes dans la source de donn\00E9es. La collection de lignes consiste g\00E9n\00E9ralement en un tableau JSON ou une <em>collection</em> XML (e')
||unistr('n XML, une s\00E9quence de balises portant le m\00EAme nom). Les <em>collections</em> XML imbriqu\00E9es ou les tableaux imbriqu\00E9s ne sont pas pris en charge.'),
'</p>',
'<p>',
unistr('    Si le s\00E9lecteur de ligne '),
unistr('    fait r\00E9f\00E9rence \00E0 un objet JSON unique ou \00E0 une balise XML qui n''est pas une collection, l''attribut de profil de donn\00E9es <strong>Contient une seule ligne</strong> doit \00EAtre d\00E9fini sur <strong>Oui</strong>. Laissez l''attribut vide ou entrez <strong')
||'>"."</strong> si l''objet ou le tableau JSON est au niveau racine. ',
'</p>',
'<h2>',
'    Exemple 1 :',
'</h2>',
'<pre>',
'{ "items": [',
'    { "ename": "SMITH", "sal": 200 },',
'    { "ename": "SCOTT", "sal": 100 } ] }',
'</pre>',
'<p>',
unistr('    L''attribut JSON contient un tableau dans l''attribut <strong>items</strong>. Par cons\00E9quent, choisissez-le en tant que s\00E9lecteur de ligne. Chaque \00E9l\00E9ment du tableau sera consid\00E9r\00E9 comme une ligne et chaque attribut comme une colonne.'),
'</p>',
'<h2>',
'    Exemple 2 :',
'</h2>',
'<pre>',
'{ "header": { "generated": "2018-10-19", "version": "1.0" },',
'  "body": { "items": [',
'          { "ename": "SMITH", "sal": 200 },',
'          { "ename": "SCOTT", "sal": 100 } ] } }',
'</pre>',
'<p>',
unistr('    L''attribut JSON contient un tableau dans l''attribut <strong>body.items</strong>. Par cons\00E9quent, choisissez-le en tant que s\00E9lecteur de ligne. Chaque \00E9l\00E9ment du tableau sera consid\00E9r\00E9 comme une ligne et chaque attribut comme une colonne.'),
'</p>',
' <h2>',
'    Exemple 3 :',
'</h2>',
'<pre>',
'&lt;xml-document&gt;',
'  &lt;row&gt;',
'    &lt;ename&gt;SMITH&lt;/ename&gt;&lt;sal&gt;200&lt;/sal&gt;',
'  &lt;/row&gt;',
'  &lt;row&gt;',
'    &lt;ename&gt;SCOTT&lt;/ename&gt;&lt;sal&gt;100&lt;/sal&gt;',
'  &lt;/row&gt;',
'&lt;xml-document&gt;',
'</pre>   ',
'    <p>',
unistr('    L''attribut de balise XML <strong>/xml-document/row</strong> contient une <em>collection</em>. Par cons\00E9quent, choisissez-le en tant que s\00E9lecteur de ligne. Chaque objet de <strong>ligne</strong> sera consid\00E9r\00E9 comme une ligne et chaque balise enf')
||'ant de &lt;row&gt; comme une colonne.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
