wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(4702017184940016.4002)
,p_name=>'P1926_TRANSFORM_TYPE'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(4701992042940015.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Transformation de valeur'
,p_source=>'TRANSFORM_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'DATA.LOAD.TRANSFORM_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(4818478622110870)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Aucun'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    S\00E9lectionnez une r\00E8gle de transformation simple pour modifier la valeur t\00E9l\00E9charg\00E9e. Par exemple, si les donn\00E9es source contiennent des donn\00E9es de colonne en majuscules et en minuscules, les options <strong>En minuscules</strong> ou <strong>En ma')
||'juscules</strong> permettent de les convertir vers la casse voulue.',
'    </p>',
'<ul>',
unistr('    <li><strong>Troncature \00E0 gauche</strong>, <strong>Troncature \00E0 droite</strong> et <strong>D\00E9coupage</strong><br> : tronque les caract\00E8res indiqu\00E9s dans l''<strong>expression 1</strong> du c\00F4t\00E9 gauche et/ou du c\00F4t\00E9 droit de la valeur de donn\00E9es t\00E9l')
||unistr('\00E9charg\00E9e.</li>'),
'    <li><strong>Remplacer :</strong><br> simple remplacement des occurrences de l''<strong>expression&nbsp;1</strong> par l''<strong>expression&nbsp;2</strong>.</li>',
'    <li><strong>En majuscules :</strong><br> convertit la valeur en majuscules.</li>',
'    <li><strong>En minuscules :</strong><br> convertit la valeur en minuscules.</li>',
unistr('    <li><strong>NULL si :</strong><br> si la valeur t\00E9l\00E9charg\00E9e est identique \00E0 la cha\00EEne indiqu\00E9e dans l''<strong>expression&nbsp;1</strong>, la valeur est t\00E9l\00E9charg\00E9e en tant que valeur NULL.</li>'),
unistr('    <li><strong>Remplacement d''expression r\00E9guli\00E8re :</strong><br> applique l''expression r\00E9guli\00E8re indiqu\00E9e dans l''<strong>expression&nbsp;1</strong> et remplace toutes les correspondances par l''<strong>expression&nbsp;2</strong>.</li>'),
unistr('    <li><strong>NULL si expression r\00E9guli\00E8re :</strong><br> s''il existe des correspondances pour l''expression r\00E9guli\00E8re indiqu\00E9e dans l''<strong>expression&nbsp;1</strong>, la valeur de colonne est t\00E9l\00E9charg\00E9e en tant que valeur NULL.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
