,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Pour les profils de donn\00E9es <strong>CSV</strong> et <strong>XLSX</strong>, indiquez si la valeur de colonne est r\00E9f\00E9renc\00E9e par la s\00E9quence des colonnes (num\00E9rique), par le nom de colonne ou par une expression r\00E9guli\00E8re. Les options <strong>Nom</s')
||unistr('trong> et <strong>Expression r\00E9guli\00E8re</strong> requi\00E8rent que les donn\00E9es CSV ou XLSX contiennent des noms de colonne dans la premi\00E8re ligne. '),
unistr('    L''option <strong>Expression r\00E9guli\00E8re</strong> est pratique si les noms de colonne dans les donn\00E9es t\00E9l\00E9charg\00E9es sont susceptibles de changer.'),
'</p>',
'<p>',
unistr('L''option <strong>S\00E9quence</strong> offre de meilleures performances car &PRODUCT_NAME. n''a pas besoin de d\00E9terminer le nom et la position des colonnes pour charger les donn\00E9es. Toutefois, n''utilisez cette option que si les donn\00E9es t\00E9l\00E9charg\00E9es pr\00E9sen')
||unistr('tent toujours les m\00EAmes colonnes organis\00E9es selon la m\00EAme s\00E9quence. '),
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
