wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(225901911120244544.4002)
,p_name=>'P1926_SELECTOR'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(225901106053244536.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('S\00E9lecteur')
,p_source=>'SELECTOR'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>75
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>L''expression de <strong>s\00E9lecteur</strong> est utilis\00E9e pour extraire la valeur de colonne des donn\00E9es source.'),
'<ul>',
unistr('    <li><p>Pour les formats <strong>XML</strong> et <strong>JSON</strong>, ce s\00E9lecteur est <em>relatif</em> au <strong>s\00E9lecteur de ligne</strong> configur\00E9 au niveau du profil de donn\00E9es. Pour XML, utilisez la syntaxe XPath. Pour les formats JSON, ')
||unistr('utilisez les expressions de chemin JSON.</p><p>Remarque : lorsque vous utilisez le package <strong>APEX_EXEC</strong> pour acc\00E9der aux donn\00E9es dans les colonnes de <em>tableau</em> \00E0 l''aide de PL/SQL, <em>seuls les s\00E9lecteurs simples</em>, c''est-\00E0-di')
||unistr('re sans expression de filtre ni index de tableau, sont autoris\00E9s.</p></li>'),
unistr('    <li>Pour <strong>CSV</strong> ou <strong>XLSX</strong>, utilisez le nom de colonne, la s\00E9quence ou une expression r\00E9guli\00E8re en fonction de l''attribut <strong>Type de s\00E9lecteur</strong>. Les noms de colonne et les expressions r\00E9guli\00E8res sont mis e')
||'n correspondance <em>sans respecter la casse</em> pour les fichiers CSV et XLSX.</li> ',
'</ul>',
'<p>',
'<br><strong>Exemple JSON :</strong>',
'</p>',
'<pre>',
'{ "items": [',
'    { "ename": "SMITH", "sal": 200 },',
'    { "ename": "SCOTT", "sal": 100 } ] }',
'</pre>',
'<p>',
unistr('    <strong>items</strong> est utilis\00E9 en tant qu''attribut <strong>S\00E9lecteur de ligne</strong>. Par cons\00E9quent, choisissez <strong>ename</strong> en tant que s\00E9lecteur pour la colonne ENAME et <strong>sal</strong> en tant que s\00E9lecteur pour la colonn')
||unistr('e SAL. Le s\00E9lecteur ne doit pas r\00E9f\00E9rencer de tableau JSON.'),
'</p>',
'<p>',
'<br><strong>Exemple CSV :</strong></p>',
'<pre>',
'EMPNO   ENAME   SAL ',
'------- ------- --------',
'   7839 KING        5000',
'   7844 FORD        2850',
'      : :              :',
'</pre>',
'<p>',
unistr('    Si <strong>Nom</strong> est utilis\00E9 en tant que type de s\00E9lecteur, utilisez les noms de colonne de la premi\00E8re ligne des donn\00E9es CSV ou XLSX : <strong>EMPNO</strong>, <strong>ENAME</strong> ou <strong>SAL</strong>. Si le type de s\00E9lecteur est <st')
||unistr('rong>S\00E9quence</strong>, utilisez <strong>1</strong>, <strong>2</strong> ou <strong>3</strong> pour r\00E9f\00E9rencer la colonne \00E0 l''aide de son num\00E9ro de s\00E9quence. La m\00EAme s\00E9mantique s''applique aux profils de donn\00E9es XLSX.'),
'</p>',
'<p>',
unistr('L''option <strong>S\00E9quence</strong> offre de meilleures performances car &PRODUCT_NAME. n''a pas besoin de d\00E9terminer le nom et la position des colonnes pour charger les donn\00E9es. Toutefois, n''utilisez cette option que si les donn\00E9es t\00E9l\00E9charg\00E9es pr\00E9sen')
||unistr('tent toujours les m\00EAmes colonnes organis\00E9es selon la m\00EAme s\00E9quence. '),
'</p> '))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
