 p_id=>wwv_flow_imp.id(2242559901021531.4002)
,p_validation_name=>'No Cycles in Nested Row Columns'
,p_validation_sequence=>180
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with profile_cols as (',
'         select id,',
'                parent_column_id,',
'                data_type',
'           from wwv_flow_data_profile_cols',
'          where security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and data_profile_id   = :P1926_DATA_PROFILE_ID    ',
'            and id               != :P1926_DATA_PROFILE_COLUMN_ID',
'          union all ',
'         select to_number(:P1926_DATA_PROFILE_COLUMN_ID) as id,',
'                to_number(:P1926_PARENT_COLUMN)          as parent_column_id,',
'                :P1926_DATA_TYPE                         as data_type',
'           from sys.dual',
')',
'select 1 ',
'  from (',
'         select id, ',
'                connect_by_iscycle is_cycle',
'           from profile_cols',
'          start with data_type      = ''ARRAY''',
'        connect by nocycle prior id = parent_column_id )',
' where is_cycle = 1'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('Les colonnes avec des lignes imbriqu\00E9es ne doivent pas comporter de r\00E9f\00E9rences cycliques.')
