,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Les informations de serveur de source de donn\00E9es REST sont stock\00E9es en tant qu''objet <strong>Serveur distant</strong>. Les serveurs distants peuvent \00EAtre partag\00E9s entre plusieurs sources de donn\00E9es REST. La modification des propri\00E9t\00E9s de serveur d')
||unistr('istant a une incidence sur toutes les sources de donn\00E9es REST qui r\00E9f\00E9rencent cet objet (par exemple, vous pouvez faire passer un objet Serveur distant d''un syst\00E8me de test \00E0 un syst\00E8me de production).</p>'),
'',
unistr('<p>Les serveurs distants sont stock\00E9s au niveau de l''espace de travail et sont donc visibles dans toutes les applications. Lorsque vous exportez une application, les serveurs distants utilis\00E9s sont ajout\00E9s au fichier d''export. Lorsque vous importez l')
||unistr('''application dans un autre espace de travail, &PRODUCT_NAME. v\00E9rifie si l''espace de travail cible contient d\00E9j\00E0 des serveurs distants avec le m\00EAme <strong>ID statique</strong>. S''il existe d\00E9j\00E0 un serveur distant, l''application l''utilise. Dans le cas')
||unistr(' contraire, les serveurs distants du fichier d''import sont cr\00E9\00E9s dans l''espace de travail cible.</p>')))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249349483233883038.4002)
,p_plug_name=>'Serveurs distants'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4002)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with data as (',
'    select s.id,',
'           s.name,',
'           s.server_type,',
'           s.base_url,',
'           s.static_id,',
'           nvl2( s.configuration_procedure, ''Y'', ''N'' ) dynamic,',
'           count(m.id)  module_references,',
'           count(ma.id) auth_references,',
'           count(f.id)  app_references',
'      from wwv_remote_servers s',
'           left outer join wwv_flow_web_src_modules m ',
'                      on (     s.security_group_id = m.security_group_id',
'                           and s.id                = m.remote_server_id )',
'           left outer join wwv_flow_web_src_modules ma ',
'                      on (     s.security_group_id = ma.security_group_id',
'                           and s.id                = ma.auth_remote_server_id )',
'           left outer join wwv_flows f ',
'                      on (     s.security_group_id = f.security_group_id',
'                           and (    s.id = f.print_remote_server_id ',
'                                 or s.id = f.file_remote_server_id ) )',
'        --',
'     where s.server_type       in ( ''WEB_SERVICE'', ''AUTHENTICATION'', ''PRINT_SERVER'', ''CLOUD_OBJECT_STORE'' )',
'       and s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'       and not exists ( select 1 ',
'                          from wwv_flow_language_map ',
'                         where translation_flow_id in ( m.flow_id, ma.flow_id, f.id ) )',
'     group by s.id, s.name, s.server_type, s.base_url, s.static_id, s.credential_id, s.configuration_procedure',
') ',
'select ',
'    id,',
'    name,',
'    server_type,',
'    base_url,',
'    static_id,',
'    dynamic,',
'    module_references + auth_references + app_references as references',
'from data',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
