wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2000804282223106.4002)
,p_name=>'P1932_CONFIGURATION_PROCEDURE'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(225856843527926534.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Proc\00E9dure de configuration')
,p_source=>'CONFIGURATION_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le nom d''une proc\00E9dure qui configure l''URL endpoint lors de l''ex\00E9cution.'),
unistr('Il peut s''agir d''une proc\00E9dure stock\00E9e ou d''une proc\00E9dure d\00E9finie dans l''\00E9l\00E9ment <em>Code PL/SQL</em>.'),
unistr('Le code ci-dessous est destin\00E9 \00E0 une application qui impl\00E9mente une architecture colocative'),
unistr('et prend en charge diff\00E9rentes variations de l''<em>URL endpoint</em> pour les locataires.'),
unistr('Le nom de domaine est modifi\00E9 dans l''URL en fonction du client (exemples d''URL : '),
'https://cust-01.example.com, https://cust-02.example.com) :',
'</p><pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
