wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(537042329937394616.4002)
,p_validation_name=>'Cannot delete used Remote Server'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id',
'  from wwv_remote_servers s ',
' where exists( select 1 ',
'                 from wwv_flow_web_src_modules m ',
'                where m.security_group_id = s.security_group_id',
'                  and (    m.remote_server_id      = s.id ',
'                        or m.auth_remote_server_id = s.id ) )',
'   and s.server_type       in ( ''WEB_SERVICE'', ''AUTHENTICATION'' )',
'   and s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and s.id                 = :P1932_ID',
'union all',
'select s.id',
'  from wwv_remote_servers s ',
' where s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and s.id                 = :P1932_ID',
'   and (    exists ( select 1',
'                       from wwv_flows f',
'                      where f.file_remote_server_id = s.id',
'                        and f.security_group_id     = s.security_group_id )',
'         or exists ( select 1',
'                       from wwv_flows f',
'                      where f.print_remote_server_id = s.id',
'                        and f.security_group_id      = s.security_group_id ) )'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('Le serveur distant est en cours d''utilisation et ne peut pas \00EAtre supprim\00E9.')
,p_when_button_pressed=>wwv_flow_imp.id(225856518442926531.4002)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
