wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226574766423012964.4002)
,p_name=>'P1943_AUTH_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(229756918559737172.4002)
,p_prompt=>'Type d''authentification'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- S\00E9lectionner -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Indiquez le type d''authentification ici. Actuellement, Oracle APEX prend en charge les types d''authentification suivants :',
'</p>',
'<ul>',
unistr('    <li><strong>Authentification de base :</strong> envoie le nom utilisateur et le mot de passe encod\00E9s au format Base64 en tant qu''en-t\00EAte de demande d''<strong>autorisation</strong>.'),
'    </li>',
unistr('    <li><strong>Informations d''identification de client OAuth2 :</strong> Oracle APEX remplace l''ID et la cl\00E9 secr\00E8te client par un <strong>token d''acc\00E8s</strong> utilisant une URL de serveur de token. Le token d''acc\00E8s est ensuite employ\00E9 pour effect')
||unistr('uer la demande r\00E9elle. S''il a expir\00E9, APEX en demande un nouveau de mani\00E8re transparente.</li>'),
unistr('    <li><strong>Authentification native OCI :</strong> Oracle APEX signe les demandes adress\00E9es \00E0 l''API REST <em>Oracle Cloud Infrastructure (OCI)</em>, comme indiqu\00E9 dans la <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas')
||unistr('/Content/API/Concepts/signingrequests.htm">documentation OCI</a>. Ce type est uniquement disponible dans Oracle Database 18c et versions sup\00E9rieures.</li>'),
unistr('    <li><strong>En-t\00EAte HTTP :</strong> les informations d''identification sont ajout\00E9es \00E0 la demande REST en tant qu''en-t\00EAte HTTP. Le nom des informations d''identification est utilis\00E9 en tant que nom de l''en-t\00EAte HTTP, et la cl\00E9 secr\00E8te des informati')
||unistr('ons d''identification est utilis\00E9e en tant que valeur de l''en-t\00EAte HTTP. Oracle APEX n''ajoute ces cl\00E9s secr\00E8tes ni au journal de d\00E9bogage ni \00E0 un autre journal.</li>'),
unistr('    <li><strong>Cha\00EEne de requ\00EAte d''URL :</strong> les informations d''identification sont ajout\00E9es \00E0 l''URL de la demande REST en tant que param\00E8tre <em>Cha\00EEne de requ\00EAte</em> (par exemple : <strong>?name=value</strong>). Cette option peut \00EAtre utile ')
||unistr('avec les cl\00E9s d''API. Oracle APEX n''ajoute ces cl\00E9s secr\00E8tes ni au journal de d\00E9bogage ni \00E0 un autre journal. Toutefois, le proxy ou d''autres serveurs interm\00E9diaires peuvent consigner ces informations d''identification dans leurs fichiers journaux.</li')
||'>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
