wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3802161062901510.4002)
,p_plug_name=>'Synchronisation REST'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>40
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('La <strong>synchronisation REST</strong> permet de maintenir automatiquement la synchronisation entre le contenu d''une table locale et les donn\00E9es d''un service REST. Elle peut \00EAtre d\00E9clench\00E9e manuellement ou \00E0 intervalles r\00E9guliers \00E0 l''aide d''un trav')
||'ail de programmateur.',
'</p>',
'<p>',
unistr('APEX peut cr\00E9er la table locale en fonction des colonnes visibles du <strong>profil de donn\00E9es</strong> de la source de donn\00E9es REST. Dans la mesure o\00F9 la table est un <em>objet visible</em> du sch\00E9ma de base de donn\00E9es, les d\00E9veloppeurs <em>peuvent<')
||unistr('/em> y ajouter des index, en modifier les propri\00E9t\00E9s physiques ou m\00EAme y ajouter des colonnes. '),
'</p>',
'<p>',
unistr('Si la table n''est <em>pas</em> synchronis\00E9e avec le profil de donn\00E9es, la synchronisation REST continue \00E0 fonctionner pour les colonnes pr\00E9sentes <em>\00E0 la fois</em> dans la table et dans le profil de donn\00E9es (les autres \00E9tant ignor\00E9es). Toutefois, AP')
||unistr('EX g\00E9n\00E8re des instructions SQL DDL pour resynchroniser les colonnes de table avec le profil de donn\00E9es : celles-ci peuvent \00EAtre ajout\00E9es \00E0 l''application en tant qu''objets de prise en charge.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
