'APEX_APPL_ACL_USER_ROLES<br>',
'APEX_APPL_ACL_ROLES',
'</code>',
'</p>',
unistr('<p>Utilisez l''API suivante pour g\00E9rer les param\00E8tres de contr\00F4le d''acc\00E8s :<br>'),
'<code>APEX_ACL</code>',
'</p>',
'<a href="&SYSTEM_HELP_URL." target="_blank">En savoir plus...</a>'))
,p_plug_display_condition_type=>'EXPRESSION'
