wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(12202060586853618.4002)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Report & Form Pages'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_pk_columns          wwv_flow_t_varchar2;',
'    l_all_columns         wwv_flow_t_varchar2;',
'    l_rpt_impl            wwv_flow_form_region_dev.t_report_implementation;',
'    l_rpt_region_template number;',
'begin',
'    wwv_flow_string.push( l_pk_columns, :P2502_PK_COLUMN_1 );',
'    if :P2502_PK_COLUMN_2 is not null then',
'        wwv_flow_string.push( l_pk_columns, :P2502_PK_COLUMN_2 );',
'    end if;',
'    if :P2502_PK_COLUMN_3 is not null then',
'        wwv_flow_string.push( l_pk_columns, :P2502_PK_COLUMN_3 );',
'    end if;',
'',
'    l_all_columns := wwv_flow_string.split( :P2501_ALL_COLUMNS, '':'' );',
'',
'    if :P2500_PAGE_TYPE = ''INTERACTIVE'' then',
'        l_rpt_impl            := wwv_flow_form_region_dev.c_report_impl_interactive;',
'    elsif :P2500_PAGE_TYPE = ''CLASSIC'' then',
'        l_rpt_impl := wwv_flow_form_region_dev.c_report_impl_classic;',
'    elsif :P2500_PAGE_TYPE = ''GRID'' then',
'        l_rpt_impl := wwv_flow_form_region_dev.c_report_impl_ig;',
'    end if;',
'',
'    -- derive region template',
'    if :P2500_PAGE_TYPE = ''INTERACTIVE'' then',
'        l_rpt_region_template := wwv_flow_theme_dev.get_region_template_id (',
'                                     p_application_id => :FB_FLOW_ID,',
'                                     p_theme_id       => :FB_THEME_ID,',
'                                     p_page_type      => ''INTERACTIVE'' );',
'    else',
'        l_rpt_region_template := wwv_flow_theme_dev.get_region_template_id (',
'                                             p_application_id => :FB_FLOW_ID,',
'                                             p_theme_id       => :FB_THEME_ID,',
'                                             p_page_type      => ''REPORT'' );',
'    end if;',
'',
'    wwv_flow_form_region_dev.create_form_and_report_pages(',
'        p_flow_id                    => :FB_FLOW_ID,',
'        p_form_page_id               => :P2501_FORM_PAGE_ID,',
'        p_report_page_id             => :P2501_PAGE_ID,',
'        p_form_page_name             => :P2501_FORM_PAGE_NAME,',
'        p_report_page_name           => :P2501_PAGE_NAME,',
'        --',
'        p_report_implementation      => l_rpt_impl,',
'        -- when report page mode is normal, users can select form page mode',
'        -- when report page mode is not normal, then we use report page mode for form page as-well',
'        p_form_page_mode             => case when :P2501_PAGE_MODE = wwv_flow_page.c_page_mode_normal then',
'                                            :P2501_FORM_PAGE_MODE',
'                                        else',
'                                            :P2501_PAGE_MODE',
'                                        end,',
'        p_report_page_mode           => :P2501_PAGE_MODE,',
'        --',
'        p_nav_list_id                => :P2500_NAVLIST_ID,',
'        p_nav_list_parent_item_id    => :P2501_NAVLIST_PARENT_ID,',
'        p_nav_list_child_item_name   => case when :P2501_NAVLIST_OPTIONS = ''NEW'' then :P2501_PAGE_NAME end,',
'        p_nav_list_item_icon         => :P2501_PAGE_ICON,',
'        --',
'        p_breadcrumb_id              => :P2501_BREADCRUMB_ID,',
'        p_breadcrumb_entry_name      => :P2501_PAGE_NAME,',
'        p_parent_breadcrumb_entry_id => :P2501_BREADCRUMB_PARENT_ID,',
'        --',
'        p_location                   => :P2501_LOCATION,',
'        p_query_type                 => :P2501_QUERY_TYPE,',
'        p_table_owner                => :P2501_TAB_OWNER,',
'        p_table_name                 => :P2501_TAB_NAME,',
'        p_sql_plsql_source           => :P2501_SQL_SOURCE,',
'        p_remote_server_id           => :P2501_REMOTE_SERVER_ID,',
'        p_web_source_module_id       => :P2501_WEB_SRC_MODULE_ID,',
'        p_document_source_id         => :P2501_DOCUMENT_SOURCE_ID,',
'        p_array_column_id            => :P2501_ARRAY_COLUMN_ID,        ',
'        --',
'        p_primary_key_columns        => l_pk_columns,',
'        p_form_columns               => l_all_columns,',
'        p_report_columns             => l_all_columns,',
'        --',
'        p_rpt_region_template        => l_rpt_region_template,',
'        p_rpt_template               => case when l_rpt_impl = wwv_flow_form_region_dev.c_report_impl_classic',
'                                             then wwv_flow_theme_dev.get_report_template_id(',
'                                                 p_application_id => :FB_FLOW_ID,',
'                                                 p_theme_id       => :FB_THEME_ID ) end,',
'        p_rpt_region_name            => :P2501_PAGE_NAME,',
'        p_form_region_template       => wwv_flow_theme_dev.get_region_template_id (',
'                                            p_application_id => :FB_FLOW_ID,',
'                                            p_theme_id       => :FB_THEME_ID,',
'                                            p_page_type      => ''FORM''),',
'        p_form_region_name           => :P2501_FORM_PAGE_NAME,',
'        p_use_ui_default             => ''Y'' );',
'',
'    :FB_FLOW_PAGE_ID     := :P2501_PAGE_ID;',
'    :F4000_RUN_EDIT_PAGE := :P2501_PAGE_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Impossible de cr\00E9er des pages d''\00E9tat et de panneau. #SQLERRM#')
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(40211825181300977.4002)
,p_process_when=>':P2500_PAGE_TYPE in (''INTERACTIVE'',''GRID'',''CLASSIC'') and :P2501_INCLUDE_FORM = ''Y'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_process_success_message=>unistr('La page d''\00E9tat &P2501_PAGE_ID. et la page de panneau &P2501_FORM_PAGE_ID. sont cr\00E9\00E9es.')
,p_internal_uid=>12202060586853618.4002
);
