,p_name=>'Etat de facet pour la table locale'
,p_region_name=>'table-fsReport'
,p_parent_plug_id=>wwv_flow_imp.id(572537019842755431.4002)
,p_template=>wwv_flow_imp.id(208928010704475743.4002)
,p_display_sequence=>30
,p_region_css_classes=>'margin-sm'
,p_region_sub_css_classes=>'facet-report'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--staticRowColors:a-Report--stretch'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with top5 as (',
'  select column_value column_name',
'  from table( wwv_flow_faceted_search_dev.get_top5_facet_columns(',
'              p_table_owner => :P2501_TAB_OWNER,',
'              p_table_name  => :P2501_TAB_NAME ) ) )',
'select wwv_flow_item.hidden( 1, c.column_name )||',
'       case when c.filterable_score >= 20 and',
'            regexp_replace( c.data_type, ''\(\d+\)'', '''' ) not member of wwv_flow_faceted_search_dev.get_date_col_types and -- 19.2 ignore dates',
'            ( coalesce( c.num_distinct, 0) <= 2000 or c.filter_display_as = ''RANGE'' ) -- if not range, ignore columns with too many distinct values',
'       then',
'          htmldb_item.checkbox2(',
'              p_idx            => 2,',
'              p_value          => c.column_name,',
'              p_attributes     => ''class="u-vh apex-ui-selector-input"'',',
'              p_checked_values => t.column_name,',
'              p_item_id        => ''cb_''||wwv_flow_escape.html_attribute(c.column_name)) || ''<label class="apex-ui-selector" for="cb_''||wwv_flow_escape.html_attribute(c.column_name)||''" aria-labelledby="cb_label_''||wwv_flow_escape.html_attribute(c.col'
||'umn_name)||''"></label>''',
'       end facets,',
'       case when c.filterable_score >= 20 and',
'            c.data_type not member of wwv_flow_faceted_search_dev.get_date_col_types and -- 19.2 ignore dates',
'            ( coalesce( c.num_distinct, 0) <= 2000 or c.filter_display_as = ''RANGE'' ) -- if not range, ignore columns with too many distinct values',
'       then',
'          ''<label for="cb_''||wwv_flow_escape.html_attribute(c.column_name)||''" id="cb_label_''||wwv_flow_escape.html_attribute(c.column_name)||''">''||wwv_flow_escape.html(c.column_name)||'' (''||wwv_flow_escape.html(lower(c.data_type))||'')</label>''',
'       else',
'          wwv_flow_escape.html(c.column_name)||'' (''||wwv_flow_escape.html(lower(c.data_type))||'')''',
'       end column_name,',
'       case when c.filterable_score >= 20 and',
'            regexp_replace( c.data_type, ''\(\d+\)'', '''' ) not member of wwv_flow_faceted_search_dev.get_date_col_types and -- 19.2 ignore dates',
'            ( coalesce( c.num_distinct, 0) <= 2000 or c.filter_display_as = ''RANGE'' ) -- if not range, ignore columns with too many distinct values',
'       then',
'           wwv_flow_item.text_from_lov (',
'               p_value => c.filter_display_as,',
'               p_lov   => ''WIZ_FACET_TYPE'' )',
'       end facet_type,',
'       c.filterable_score  facet_score,',
'       case when c.is_fk_yn = ''Y'' then',
'           ''Y''',
'       else',
'           c.filter_global_searchable_yn',
'       end include_in_search,',
'       c.num_distinct,',
'       c.num_nulls,',
'       c.avg_col_len',
'  from wwv_dictionary_cache_col c,',
'       top5 t',
' where c.column_name       = t.column_name (+)',
'   and c.security_group_id = :WORKSPACE_ID',
'   and c.owner_name        = :P2501_TAB_OWNER',
'   and c.table_name        = :P2501_TAB_NAME',
'   and :P2501_TAB_NAME     is not null',
' order by c.column_id'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2501_TAB_OWNER,P2501_TAB_NAME'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4002)
