wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5501131701609211.4002)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Chart'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_series_type  varchar2(10);    ',
'begin',
'      -- Series Type',
'    l_series_type := case :P2514_JET_CHART_TYPE',
'                         when ''range'' then ''barRange''',
'                         when ''stock'' then ''stock''',
'                         when ''combo'' then ''bar''',
'                         when ''polar'' then ''bar''',
'                         when ''radar'' then ''line''',
'                         when ''GANTT'' then ''gantt''',
'                         else :P2514_JET_CHART_TYPE',
'                     end;',
'  ',
'    wwv_flow_wizard_api.create_jet_chart (',
'      p_flow_id                  => :FB_FLOW_ID,',
'      p_page_id                  => :P2501_PAGE_ID,',
'      p_page_name                => :P2501_PAGE_NAME,',
'      p_page_mode                => :P2501_PAGE_MODE,',
'      p_region_template          => wwv_flow_theme_dev.get_region_template_id (',
'                                        p_application_id => :FB_FLOW_ID,',
'                                        p_theme_id       => :FB_THEME_ID,',
'                                        p_page_type      => ''CHART''),',
'      p_region_name              => :P2501_PAGE_NAME,',
'      --',
'      p_nav_list_id              => :P2500_NAVLIST_ID,',
'      p_nav_list_parent_item_id  => :P2501_NAVLIST_PARENT_ID,',
'      p_nav_list_child_item_name => case when :P2501_NAVLIST_OPTIONS = ''NEW'' then :P2501_PAGE_NAME end,',
'      p_nav_list_item_icon       => :P2501_PAGE_ICON,      ',
'      --',
'      p_breadcrumb_id            => :P2501_BREADCRUMB_ID,',
'      p_breadcrumb_name          => :P2501_PAGE_NAME,',
'      p_parent_bc_id             => :P2501_BREADCRUMB_PARENT_ID,',
'      --',
'      p_sql                      => :P2501_SQL_SOURCE,',
'      p_location                 => :P2501_LOCATION,',
'      p_query_type               => :P2501_QUERY_TYPE,',
'      p_remote_server_id         => :P2501_REMOTE_SERVER_ID,',
'      p_web_src_module_id        => :P2501_WEB_SRC_MODULE_ID,',
'      p_document_source_id       => :P2501_DOCUMENT_SOURCE_ID,',
'      p_array_column_id          => :P2501_ARRAY_COLUMN_ID,       ',
'      p_table_owner              => :P2501_TAB_OWNER,',
'      p_table_name               => :P2501_TAB_NAME,',
'      p_chart_type               => case :P2514_JET_CHART_TYPE when ''GANTT'' then ''gantt'' else :P2514_JET_CHART_TYPE end,',
'      p_series_type              => l_series_type,',
'      p_max_row_count            => :P2505_MAX_ROWS,  ',
'      --',
'      p_items_value_column_name    => :P2505_VALUE_COL,',
'      p_items_low_column_name      => :P2505_LOW_COL,',
'      p_items_high_column_name     => :P2505_HIGH_COL,',
'      p_items_open_column_name     => :P2505_OPEN_COL,',
'      p_items_close_column_name    => :P2505_CLOSE_COL,   ',
'      p_items_x_column_name        => :P2505_X_COL,',
'      p_items_y_column_name        => :P2505_Y_COL,',
'      p_items_z_column_name        => :P2505_Z_COL,',
'      p_items_target_value         => :P2505_TARGET_COL,',
'      p_items_max_value            => :P2505_MAX_VAL_COL,',
'      p_group_short_desc_column_name     => :P2505_LABEL_COL,',
'      p_items_label_column_name    => :P2505_LABEL_COL,',
'      p_aggregate_function         => :P2505_AGGREGATE_FUNCTION,',
'      -- ',
'      p_orientation                => :P2505_ORIENTATION,',
'      --p_stack                      => (case when :P2505_STACK_CHART = ''Y'' then ''on'' else ''off'' end),',
'      --p_spark_chart                => :P2505_SPARK_CHART,',
'      p_show_tooltip               => ''Y'',',
'      p_show_legend                => case when :P2514_JET_CHART_TYPE in (''pie'',''donut'') then ''auto'' else ''none'' end,  -- Pre 18.2 - 19.1 was remove; for consistency with Create App wiz, display for Pie & Donut',
'      --',
'      p_gantt_start_date_column    => :P2505_START_DATE_COL,',
'      p_gantt_end_date_column      => :P2505_END_DATE_COL,  ',
'      p_gantt_task_id              => :P2505_TASK_ID,  ',
'      p_gantt_task_name            => :P2505_TASK_NAME,',
'      p_gantt_task_start_date      => :P2505_TASK_START_DATE,',
'      p_gantt_task_end_date        => :P2505_TASK_END_DATE,',
'      --',
'      p_gauge_orientation          => :P2505_GAUGE_ORIENTATION );',
'      ',
'    :FB_FLOW_PAGE_ID       := :P2501_PAGE_ID;',
'    :F4000_RUN_EDIT_PAGE   := :P2501_PAGE_ID;    ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Impossible de cr\00E9er la page &P2500_PAGE_TYPE_DISPLAY.. #SQLERRM#')
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(4801074006449876.4002)
,p_internal_uid=>5501131701609211.4002
);
