 p_id=>wwv_flow_imp.id(3064115804256542.4002)
,p_plug_name=>'Aide'
,p_region_template_options=>'#DEFAULT#:js-dialog-size480x320'
,p_plug_template=>wwv_flow_imp.id(557449278618308550.4002)
,p_plug_display_sequence=>30
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Type de couche de g\00E9om\00E9trie spatiale \00E0 afficher sur la carte :'),
'</p>',
'<ul>',
unistr('    <li><strong>Points :</strong> les points (par exemple, sites de clients et de fournisseurs) sont affich\00E9s en tant que marqueurs. La forme et la couleur du marqueur sont configurables.</li>'),
unistr('    <li><strong>Lignes :</strong> les lignes repr\00E9sentent des \00E9l\00E9ments tels que des routes ou des chemins. Le style et la couleur du trait sont configurables.</li>'),
unistr('    <li><strong>Polygones :</strong> les polygones repr\00E9sentent des zones, comme des parcelles, des provinces/d\00E9partements ou des pays. Le style et la couleur du trait et du remplissage sont configurables.</li>'),
unistr('    <li><strong>Carte d''activit\00E9 :</strong> les cartes d''activit\00E9 servent \00E0 visualiser la densit\00E9 des \00E9l\00E9ments de type point. Plus le nombre de points regroup\00E9s est important, plus la couleur est intense. Elles sont g\00E9n\00E9ralement utilis\00E9es pour visual')
||unistr('iser la r\00E9partition spatiale de la population ou d''incidents.</li>'),
unistr('    <li><strong>Polygones extrud\00E9s :</strong> les polygones extrud\00E9s sont semblables aux polygones mais affich\00E9s sous la forme d''objets extrud\00E9s tridimensionnels. La hauteur de l''objet en 3D permet de visualiser une valeur de colonne.</li>'),
'</ul>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
