,p_attribute_02=>'N'
,p_process_error_message=>unistr('Erreur lors de la cr\00E9ation de la page d''assistant.')
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(16900857304321530.4002)
,p_process_success_message=>unistr('Page d''assistant cr\00E9\00E9e.')
,p_internal_uid=>22900517250380766.4002
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19904252956194932.4002)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_page_number number;',
'    l_collection_name varchar2(20) := ''CREATE_WIZARD'';',
'begin',
'    -- this collection is cleared during the brnach process to this page',
'    -- wwv_flow_collection.create_or_truncate_collection( l_collection_name );',
'    -- by default add 3 wizard steps',
'    if wwv_flow_collection.collection_member_count( p_collection_name => ''CREATE_WIZARD'') = 0 then',
'        for i in 1..3',
'        loop',
'            l_page_number := wwv_flow_utilities.minimum_free_page(:FB_FLOW_ID,1);',
'            wwv_flow_collection.add_member(',
'                p_collection_name => l_collection_name,',
'                p_c001            => i,',
'                p_c002            => l_page_number,',
'                p_c003            => wwv_flow_lang_dev.builder_message(''WIZARD.DEFAULT_PAGE_NAME'',i),',
'                p_c004            => 0 );',
'        end loop;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>19904252956194932.4002
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19904408518194934.4002)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_region_id=>wwv_flow_imp.id(18005186450209933.4002)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Update Collection'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_collection_name varchar2(20) := ''CREATE_WIZARD'';',
'begin',
'    case :APEX$ROW_STATUS',
'    when ''C'' then',
'        wwv_flow_collection.add_member(',
'            p_collection_name => l_collection_name,',
'            p_c001            => :STEP_NUMBER,',
'            p_c002            => :PAGE_ID,',
'            p_c003            => :PAGE_NAME,',
'            p_c004            => 0 );',
'    when ''U'' then',
'        wwv_flow_collection.update_member(',
'            p_collection_name => l_collection_name,',
'            p_seq             => :ID,',
'            p_c001            => :STEP_NUMBER,',
'            p_c002            => :PAGE_ID,',
'            p_c003            => :PAGE_NAME,',
'            p_c004            => 0 );',
'    when ''D'' then',
'        wwv_flow_collection.delete_member(',
'            p_collection_name => l_collection_name,',
'            p_seq => :ID );',
'    end case;',
'end;'))
,p_attribute_05=>'N'
,p_attribute_06=>'N'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>19904408518194934.4002
);
end;
/
