,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Plug-in Page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_attributes_clob clob;',
'    l_plugin_app_id   number := wwv_flow_plugin_dev.get_plugin_application_id( :P2510_REGION_TYPE, :FB_FLOW_ID );',
'    l_sgid            number := wwv_flow_plugin_dev.get_plugin_sgid( :WORKSPACE_ID, l_plugin_app_id );                                       ',
'begin',
'    l_attributes_clob := wwv_flow_plugin_dev.get_json_attributes_from_items(',
'                             p_application_id    => l_plugin_app_id,',
'                             p_plugin_name       => substr(:P2510_REGION_TYPE, 8),',
'                             p_plugin_type       => wwv_flow_plugin.c_plugin_type_region_type,',
'                             p_attribute_scope   => wwv_flow_plugin.c_attribute_scope_component,',
'                             p_security_group_id => l_sgid,',
'                             p_page_item_prefix  => ''P2510_'' );',
'            ',
'    wwv_flow_wizard_api.create_region_plugin_page (',
'        p_flow_id                  => :FB_FLOW_ID,',
'        --',
'        p_page_id                  => :P2501_PAGE_ID,',
'        p_page_name                => :P2501_PAGE_NAME,',
'        p_page_mode                => :P2501_PAGE_MODE,',
'        --',
'        p_nav_list_id              => :P2500_NAVLIST_ID,',
'        p_nav_list_parent_item_id  => :P2501_NAVLIST_PARENT_ID,',
'        p_nav_list_child_item_name => case when :P2501_NAVLIST_OPTIONS = ''NEW'' then :P2501_PAGE_NAME end,',
'        p_nav_list_item_icon       => :P2501_PAGE_ICON,',
'        --',
'        p_breadcrumb_id            => :P2501_BREADCRUMB_ID,',
'        p_breadcrumb_name          => :P2501_PAGE_NAME,',
'        p_parent_breadcrumb_id     => :P2501_BREADCRUMB_PARENT_ID,',
'        --',
'        p_region_name              => :P2501_PAGE_NAME,',
'        p_region_type              => :P2510_REGION_TYPE,',
'        --',
'        p_source_type              => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_QUERY_TYPE end,',
'        p_location                 => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_LOCATION end,',
'        p_remote_server_id         => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_REMOTE_SERVER_ID end,',
'        p_table_owner              => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_TAB_OWNER end,',
'        p_table_name               => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_TAB_NAME end,',
'        p_region_source            => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_SQL_SOURCE end,',
'        p_column_names             => null,',
'        p_web_src_module_id        => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_WEB_SRC_MODULE_ID end,',
'        p_document_source_id       => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_DOCUMENT_SOURCE_ID end,',
'        p_array_column_id          => case when :P2501_SHOW_DATA_SOURCE = ''Y'' then :P2501_ARRAY_COLUMN_ID end,',
'        --',
'        p_attributes               => l_attributes_clob );',
'',
'  :FB_FLOW_PAGE_ID       := :P2501_PAGE_ID;',
'  :F4000_RUN_EDIT_PAGE   := :P2501_PAGE_ID;',
'end;'))
