,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Saisissez un pr\00E9fixe que les utilisateurs finals doivent utiliser dans les requ\00EAtes de recherche. Un terme de recherche avec un pr\00E9fixe ne sera utilis\00E9 que pour '),
unistr('    les configurations de recherche portant le m\00EAme pr\00E9fixe. Si un pr\00E9fixe est utilis\00E9 dans une requ\00EAte de recherche mais n''est d\00E9fini dans '),
unistr('    <em>aucune</em> configuration de recherche, le pr\00E9fixe sera ignor\00E9 et l''int\00E9gralit\00E9 du terme sera utilis\00E9e pour la recherche.'),
'</p>',
'<p>Exemples</p>',
unistr('<p> Deux configurations de recherche existent : <strong>Employees</strong> avec le pr\00E9fixe <strong>emp</strong> '),
unistr('    et <strong>Jobs</strong> avec le pr\00E9fixe <strong>job</strong>.'),
'</p>',
'<dl>',
'    <dt>emp:king president</dt>',
unistr('    <dd>Le mot-cl\00E9 <strong>king</strong> sera cherch\00E9 uniquement dans la configuration de recherche <strong>Employees</strong>, '),
unistr('        <strong>president</strong> sera recherch\00E9 dans les deux.</dd>'),
'    <dt>emp:king job:president</dt>',
unistr('    <dd>Le mot-cl\00E9 <strong>king</strong> sera recherch\00E9 uniquement dans la configuration de recherche <strong>Employees</strong>, '),
unistr('        <strong>president</strong> sera uniquement recherch\00E9 dans <strong>Jobs</strong>.</dd>'),
'    <dt>emp:king depts:"new york"</dt>',
unistr('    <dd>Le mot-cl\00E9 <strong>king</strong> sera uniquement recherch\00E9 dans la configuration de recherche <strong>Employees</strong>. '),
unistr('        <strong>depts:"new york"</strong>sera recherch\00E9 dans les deux configurations,'),
unistr('        \00E9tant donn\00E9 que le pr\00E9fixe <strong>depts</strong> n''est d\00E9fini nulle part.</dd>'),
'</dl>',
''))
