wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1776874750181057.4002)
,p_name=>'P3120_DEFAULT_ROW_HTML_EXPR'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>170
,p_item_plug_id=>wwv_flow_imp.id(6700676601775302.4002)
,p_item_source_plug_id=>wwv_flow_imp.id(1757925019180889.4002)
,p_prompt=>unistr('Mod\00E8le de ligne de r\00E9sultat par d\00E9faut')
,p_source=>'DEFAULT_ROW_HTML_EXPR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>60
,p_cMaxlength=>4000
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Saisissez une expression HTML permettant d''afficher une ligne de r\00E9sultat de recherche. Utilisez la syntaxe <code>&COLUMN.</code> pour afficher les valeurs de colonne au format HTML. Prend en charge les directives de mod\00E8le. Par ailleurs, les substit')
||'utions suivantes sont disponibles :',
'</p>',
'<dl>',
'<dt>ICON_TYPE</dt>',
unistr('<dd>Repr\00E9sente le type d''ic\00F4ne : <strong>CLASS</strong>, <strong>URL</strong> ou <strong>INITIALS</strong>.</dd>'),
'<dt>ICON_VALUE</dt>',
unistr('<dd>Valeur d''ic\00F4ne r\00E9elle, selon la valeur de <strong>ICON_TYPE</strong></dd>'),
'<dt>RESULT_CSS_CLASSES</dt>',
unistr('<dd>Classes CSS appliqu\00E9es \00E0 chaque r\00E9sultat, en fonction de l''attribut <strong>Classes CSS de r\00E9sultat</strong>.</dd>'),
'<dt>APEX$ORATEXT_SCORE</dt>',
unistr('<dd>Colonne repr\00E9sentant le score Oracle Text pour les types de recherche Oracle Text.</dd>'),
'<dt>APEX$VECTOR_DISTANCE</dt>',
unistr('<dd>Colonne repr\00E9sentant la distance vectorielle pour les types de recherche vectorielle Oracle.</dd>'),
'</dl>',
'<p>Exemple :</p>',
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
'      {when URL/}',
