,p_process_name=>'Determine Searchable Columns Required'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :P3120_SEARCH_TYPE in ( ''APEX_LIST'', ''TEXT_MANUAL'', ''TEXT_DBMS_SEARCH'', ''VECTOR'' ) then',
'        :P3120_SEARCHABLE_COLS_REQUIRED := ''N'';',
'',
'    elsif :P3120_LOCATION in ( wwv_flow_exec_api.c_location_local_db, ',
'                               wwv_flow_exec_api.c_location_remote_db )',
'    then',
'        -- for local and remote SQL, we always display "searchable columns"',
'        :P3120_SEARCHABLE_COLS_REQUIRED := ''Y'';',
'    else',
'        declare',
'            l_is_query_param number := 0;',
'        begin',
'            -- if the REST Source has a parameter "Use For Row Search" defined, then',
'            -- searchable columns are completely determined by the REST API; no need',
'            -- to display the list here.',
'            select 1 ',
'              into l_is_query_param',
'              from wwv_flow_web_src_params',
'             where security_group_id = :FLOW_SECURITY_GROUP_ID',
'               and flow_id           = :FB_FLOW_ID',
'               and web_src_module_id = :P3120_WEB_SRC_MODULE_ID',
'               and is_query_param    = ''Y''',
'               and rownum            = 1;',
'            ',
'            :P3120_SEARCHABLE_COLS_REQUIRED := ''N'';',
'        exception',
'            when no_data_found then',
'                :P3120_SEARCHABLE_COLS_REQUIRED := ''Y'';',
'        end;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>3206598595836706.4002
);
