,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez les instructions initiales ou le contexte pour le service d''IA. Une invite syst\00E8me correctement r\00E9dig\00E9e guide le comportement de l''IA et d\00E9finit le ton de ses r\00E9ponses.'),
unistr('Pour cr\00E9er une invite syst\00E8me efficace, commencez par d\00E9finir clairement le r\00F4le ou l''expertise de l''IA. D\00E9crivez ensuite la t\00E2che sp\00E9cifique ou le type de r\00E9ponse que vous attendez de l''IA.</p>'),
'',
unistr('<p>Remarque : si vous ne savez pas bien comment cr\00E9er une invite syst\00E8me efficace, consultez la documentation du service d''IA afin d''obtenir des instructions d\00E9taill\00E9es. Vous pouvez \00E9galement demander \00E0 un syst\00E8me d''IA g\00E9n\00E9rative de vous aider \00E0 r\00E9di')
||'ger une invite.',
unistr('Par exemple, vous pouvez lui demander <em>"Aide-moi \00E0 \00E9crire une invite syst\00E8me pour un assistant d''IA dont la t\00E2che est d''extraire les balises ou mots-cl\00E9s pertinents \00E0 partir d''un texte fourni"</em>.</p>'),
'',
'<p><strong>Exemples :</strong>',
'<ul>',
unistr('  <li>Tu es expert en marketing. Une description de produit et des mots-cl\00E9s initiaux te sont fournis, et ta t\00E2che consiste \00E0 g\00E9n\00E9rer des noms de produit.</li>'),
unistr('  <li>Tu es traducteur professionnel. Une phrase en anglais t''est fournie et ta t\00E2che consiste \00E0 la traduire en fran\00E7ais.</li>'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
