,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Indique si l''application est disponible en vue de son utilisation. <p>',
'Les options sont les suivantes :<br>',
'<ul>',
'<li><strong>Disponible :</strong> l''application est disponible sans restriction.</li>',
unistr('<li><strong>Disponible avec la barre d''outils de d\00E9veloppeur :</strong> l''application est disponible en vue de son utilisation. Pour les d\00E9veloppeurs, la barre d''outils de d\00E9veloppeur s''affiche sur chaque page. Cette option exige que le d\00E9veloppeur s')
||unistr('oit connect\00E9 \00E0 App Builder dans la m\00EAme session de navigateur.</li>'),
unistr('<li><strong>Disponible aux d\00E9veloppeurs uniquement :</strong> l''application est disponible pour les utilisateurs ayant des privil\00E8ges de d\00E9veloppeur.</li>'),
unistr('<li><strong>Acc\00E8s restreint :</strong> l''application est disponible pour les d\00E9veloppeurs nomm\00E9s dans Restreindre \00E0 la liste d''utilisateurs s\00E9par\00E9s par des virgules.</li>'),
unistr('<li><strong>Non disponible</strong> : l''application ne peut pas \00EAtre ex\00E9cut\00E9e ou modifi\00E9e. Le contenu du message pour application non disponible s''affiche lorsque l''utilisateur tente d''acc\00E9der \00E0 l''application.</li>'),
unistr('<li><strong>Non disponible (statut affich\00E9 avec PL/SQL) :</strong> l''application ne peut pas \00EAtre ex\00E9cut\00E9e ou modifi\00E9e.</li>'),
unistr('<li><strong>Non disponible (r\00E9acheminer vers une URL) :</strong> l''application ne peut pas \00EAtre ex\00E9cut\00E9e. L''utilisateur est redirig\00E9 vers l''URL entr\00E9e dans le message pour application non disponible.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
