wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1378952136513217.4002)
,p_name=>'P4001_ORACLE_TEXT_FUNCTION'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Nom de fonction personnalis\00E9e')
,p_source=>'ORACLE_TEXT_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Indiquez le nom d''une fonction PL/SQL personnalis\00E9e qui convertit l''entr\00E9e de l''utilisateur final en requ\00EAte Oracle Text. '),
unistr('    La fonction prend l''entr\00E9e de l''utilisateur final en tant que type de donn\00E9es VARCHAR2 et renvoie la requ\00EAte Oracle Text comme r\00E9sultat.</p>'),
'<p>',
unistr('    Cet exemple utilise l''<em>assouplissement de requ\00EAte Oracle Text</em>. Il ex\00E9cute d''abord la requ\00EAte exacte,'),
unistr('    puis applique des niveaux croissants de <em>recherche de correspondance partielle</em>, jusqu''\00E0 ce que le nombre de lignes demand\00E9'),
unistr('    soit renvoy\00E9. Ce processus est totalement transparent pour l''utilisateur final.'),
'</p>',
'<pre>',
'create or replace function convert_end_user_search (',
'    p_search in varchar2 )',
'    return varchar2 ',
'is',
'    c_xml constant varchar2(32767) := ',
'        ''&lt;query&gt;&lt;textquery>&lt;progression&gt;''          ||',
'          ''&lt;seq&gt;       #SEARCH#            &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,80, 100,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,50,1000,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,20,3000,W) &lt;/seq&gt;'' ||',
'        ''&lt;/progression>&lt;/textquery>&lt;/query&gt;'';',
'',
'    l_search varchar2(32767) := p_search;',
'begin',
'    --',
'    -- remove special characters; ',
'    -- these are irrelevant for full text search',
'    --',
'    l_search := regexp_replace(',
'        srcstr  => l_search, ',
'        pattern => ''[&lt;&gt;{}/()*%&!$?.:,;\+#]'' );',
'',
'    return replace( ',
'        srcstr  => c_xml, ',
'        oldsub  => ''#SEARCH#'', ',
'        newsub  => ''{'' || l_search || ''}'' );',
'end;',
'</pre>',
'<p>',
unistr('    Pour plus d''informations sur la syntaxe de requ\00EAte Oracle Text et la fonctionnalit\00E9 d''assouplissement de'),
unistr('    requ\00EAte, reportez-vous au <a rel="noopener noreferrer" target="_blank" href="https://docs.oracle.com/en/database/oracle/oracle-database/23/ccapp/index.html">guide des d\00E9veloppeurs d''application Oracle Text</a>.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
