 p_id=>wwv_flow_imp.id(34137624724696512.4002)
,p_plug_name=>'Messages texte'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4002)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.id,',
'       m.name,',
'       m.message_language,',
'       substr(m.message_text,1,1000) message_text,',
'       length(m.message_text) message_length,',
'       m.is_js_message,',
'       nvl(m.last_updated_on,m.created_on) last_updated_on,',
'       m.last_updated_by,',
'       --',
'       case when m.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_messages$ sub',
'          where sub.reference_id      = m.id',
'            and sub.security_group_id = :FLOW_SECURITY_GROUP_ID',
'       ) as subscribers,',
'       case when m.reference_id is not null then',
'           case',
'               when master.version_scn = m.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != m.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,     ',
'       --',
'       null as actions,',
'       case ',
'           when m.metadata is null or sys.dbms_lob.getlength( m.metadata ) = 0 then -- extra check in case of empty_clob()',
'                ''N'' ',
'           else ',
'                ''Y'' ',
'        end metadata,',
'        substr(m.message_comment,1,1000) as comments',
'  from wwv_flow_messages$ m,',
'       wwv_flow_messages$ master',
' where m.flow_id           = :FB_FLOW_ID',
'   and m.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and m.reference_id      = master.id (+)',
'   and m.security_group_id = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
