wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(62894711438211649.4002)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'getAttrDesc'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'  wwv_flow_json.open_object;',
'',
'  for c1 in (',
'    select A01_LABEL,',
'       A02_LABEL,',
'       A03_LABEL,',
'       A04_LABEL,',
'       A05_LABEL,',
'       A06_LABEL,',
'       A07_LABEL,',
'       A08_LABEL,',
'       A09_LABEL,',
'       A10_LABEL',
'  from WWV_FLOW_LIST_TEMPLATES',
' where id = :P4052_LIST_TEMPLATE_ID',
'   and security_group_id in ( :WORKSPACE_ID, 11, 12 ) )',
'',
'  loop',
'    wwv_flow_json.write( ''1'', c1.A01_LABEL );',
'    wwv_flow_json.write( ''2'', c1.A02_LABEL );',
'    wwv_flow_json.write( ''3'', c1.A03_LABEL );',
'    wwv_flow_json.write( ''4'', c1.A04_LABEL );',
'    wwv_flow_json.write( ''5'', c1.A05_LABEL );',
'    wwv_flow_json.write( ''6'', c1.A06_LABEL );',
'    wwv_flow_json.write( ''7'', c1.A07_LABEL );',
'    wwv_flow_json.write( ''8'', c1.A08_LABEL );',
'    wwv_flow_json.write( ''9'', c1.A09_LABEL );',
'    wwv_flow_json.write( ''10'',c1.A10_LABEL );',
'  end loop;',
'  ',
'  wwv_flow_json.close_object;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>62894711438211649.4002
);
end;
