'      and security_group_id = :WORKSPACE_ID',
'    start with id = :P4053_ID',
'    connect by prior id = parent_list_item_id ',
');',
'',
'if :P4053_PARENT_LIST_ITEM_ID=0 then',
'    update wwv_flow_list_items',
'       set parent_list_item_id = NULL',
'     where id = :P4053_ID',
'       and flow_id = :FB_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID;',
'else',
'    update wwv_flow_list_items',
'       set parent_list_item_id = :P4053_PARENT_LIST_ITEM_ID',
'     where id = :P4053_ID',
'       and flow_id = :FB_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Echec de la mise \00E0 jour de la liste parent pour les \00E9l\00E9ments de liste en cours et les \00E9l\00E9ments de sous-liste associ\00E9s.'),
