unistr('<dt>Rechercher tous les employ\00E9s travaillant dans des services.</dt><dd><pre>(e is employees) - [is works_at] -> (d is departments)</pre></dd>'),
unistr('<dt>Rechercher tous les employ\00E9s travaillant dans des services et ayant achet\00E9 des voitures.</dt><dd><pre>(e is employees) - [is works_at] -> (d is departments), (e is employees) - [t is buys] -> (c is car)</pre></dd>'),
