'                                  then :P4080_FUNC_BODY_LANG',
'                                end,',
'    p_web_src_module_id      => :P4080_WEB_SRC_MODULE_ID,',
'    p_remote_server_id       => :P4080_REMOTE_SERVER_ID,',
'    p_document_source_id     => :P4080_DOCUMENT_SOURCE_ID,',
'    p_array_column_id        => :P4080_ARRAY_COLUMN_ID,',
'    p_match_clause           => :P4080_PQL_MATCH_CLAUSE,',
'    p_columns_clause         => :P4080_PQL_COLUMNS_CLAUSE,    ',
'    p_return_column          => :P4081_RETURN_COLUMN,',
'    p_display_column         => :P4081_DISPLAY_COLUMN',
');'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8966537405715516.4002)
,p_internal_uid=>21190462109691831.4002
);
