,p_validation_name=>'Not part of component groups'
,p_validation_sequence=>290
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'not wwv_flow_component_group_dev.is_part_of_comp_grp (',
'    p_component_id   => :F4000_P4111_ID,',
'    p_component_type => wwv_flow_shared_component_api.c_lov,',
'    p_app_id         => :FB_FLOW_ID )'))
,p_validation2=>'PLSQL'
,p_validation_type=>'EXPRESSION'
,p_error_message=>'Impossible de supprimer la liste de valeurs (LOV) car elle fait partie d''un groupe de composants.'
,p_when_button_pressed=>wwv_flow_imp.id(291985826.4002)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
