,p_validation_name=>'Master LOV not based on REST Data Source'
,p_validation_sequence=>300
,p_validation=>'wwv_flow_lov_dev.get_location( p_lov_id => :F4000_P4111_REFERENCE_ID ) != wwv_flow_exec_api.c_location_rest_source'
