,p_validation_type=>'EXPRESSION'
,p_error_message=>unistr('Echec de l''abonnement. La liste de valeurs ma\00EEtre s\00E9lectionn\00E9e repose sur une source de donn\00E9es REST. S\00E9lectionnez une autre liste de valeurs en tant que ma\00EEtre.')
