'    -- session state on load in case the dialog is opened immediately',
'    htmldb_util.set_session_state(''P4111_LOCATION'',                :P4111_LOCATION,                false );',
'    htmldb_util.set_session_state(''P4111_SOURCE_TYPE'',             :P4111_SOURCE_TYPE,             false );',
