'    htmldb_util.set_session_state(''P4111_LOV_QUERY_FUNC_LANG'',     :P4111_LOV_QUERY_FUNC_LANG,     false );',
'    htmldb_util.set_session_state(''P4111_LOV_QUERY_FUNC_BODY'',     :P4111_LOV_QUERY_FUNC_BODY,     false );',
'    htmldb_util.set_session_state(''P4111_REMOTE_SERVER_ID'',        :P4111_REMOTE_SERVER_ID,        false );',
