'if :APEX$ROW_STATUS = ''D'' and :COLUMN_NAME in ( :P4111_RETURN_COLUMN,',
'                      :P4111_DISPLAY_COLUMN,',
'                      :P4111_DEFAULT_SORT_COLUMN,',
'                      :P4111_GROUP_COLUMN,',
'                      :P4111_ICON_COLUMN,',
'                      :P4111_ORACLE_TEXT_COLUMN ) then',
'    wwv_flow_error.add_error(',
'        p_message          => wwv_flow_lang.message( ''LOV.CANT_DELETE_ADDL_COLUMN'', :COLUMN_NAME ),',
'        p_display_location => wwv_flow_error_api.c_inline_in_notification );',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(292985826.4002)
,p_process_when=>':P4111_DEL_COL_COUNT < :P4111_ADDITIONAL_COL_COUNT'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>6000764141547803.4002
,p_process_comment=>'Ideally this should be a validation. But we can''t execute validations for IG deleted rows, ref Bug 28257516. This process should be executed only when some of the rows are getting deleted. When all rows are being deleted, then we should not run this '
||'check.'
);
end;
/
