'       p.process_name,',
'       decode( greatest(sys.dbms_lob.getlength(p.process_sql_clob),200),',
'          150,sys.dbms_lob.substr(p.process_sql_clob,2000,1),',
'          sys.dbms_lob.substr(p.process_sql_clob,200,1)||'' ...'' )',
'          process_sql_clob,',
'       p.id,',
'       ''icon-sc-app-process'' icon,',
'       wwv_flow_page_api.get_url(',
'           p_page        => 4309,',
'           p_clear_cache => 4309,',
'           p_items       => ''F4000_P4309_ID'',',
'           p_values      => p.id ) edit_link,',
'       replace(p.process_name,''_'','' '') icon_image_alt_text,',
'       p.security_scheme,',
'       nvl(p.last_updated_by,p.created_by) last_updated_by,',
'       nvl(p.last_updated_on,p.created_on) last_updated_on,',
'       --',
'       case when p.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_processing sub',
'          where sub.reference_id      = p.id',
'            and sub.security_group_id = :FLOW_SECURITY_GROUP_ID',
'       ) as subscribers,',
'       case when p.reference_id is not null then',
'           case',
'               when master.version_scn = p.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != p.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,',
'       --',
'       null as actions',
' from wwv_flow_processing p,',
'      wwv_flow_processing master',
' where p.flow_id           = :FB_FLOW_ID',
'   and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and p.reference_id      = master.id (+)',
'   and p.security_group_id = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
