,p_field_template=>wwv_flow_imp.id(561549716994252345.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indique le balisage utilis\00E9 pour commencer une nouvelle mise en page. Vous devez inclure au moins #ROWS# dans ce mod\00E8le. Les cha\00EEnes de substitution suivantes sont \00E9galement autoris\00E9es dans le mod\00E8le de conteneur :</p>'),
'<ul>',
unistr('<li><strong>#USED_COLUMNS_NUMBER#</strong> : nombre de colonnes utilis\00E9es. Par exemple : 1, 2, 3...</li>'),
unistr('<li><strong>#USED_COLUMNS_ALPHA#</strong> : lettre repr\00E9sentant le nombre de colonnes utilis\00E9es. Par exemple : a, b, c...</li>'),
unistr('<li><strong>#USED_COLUMNS_ALPHA_MINUS#</strong> : lettre repr\00E9sentant le nombre de colonnes utilis\00E9es, r\00E9duites \00E0 une seule colonne. Par exemple : deux colonnes renvoient "a".</li>'),
unistr('<li><strong>#USED_COLUMNS_WORD#</strong> : mot repr\00E9sentant le nombre de colonnes utilis\00E9es. Par exemple : un, deux, trois...</li>'),
unistr('<li><strong>#USED_COLUMNS_PLURAL#</strong> : \00E9l\00E9ment remplac\00E9 par "s" si le nombre de colonnes est sup\00E9rieur \00E0 un. Utilisez cet \00E9l\00E9ment si la mise en page n\00E9cessite un nom de classe "column" pour une colonne unique et "columns" si plusieurs colonnes ')
||unistr('sont indiqu\00E9es. Par exemple : class="#USED_COLUMNS_WORD# column#USED_COLUMNS_PLURAL#"</li>'),
unistr('<li><strong>#ROWS#</strong> : \00E9l\00E9ment remplac\00E9 par le mod\00E8le de ligne.</li>'),
'</ul>',
'<p>',
'Exemple :',
'<pre>',
'&lt;div class="ui-grid-#USED_COLUMNS_ALPHA_MINUS#"&gt;#ROWS#&lt;/div&gt;',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
