,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indique le balisage utilis\00E9 pour commencer une nouvelle colonne de mise en page. Vous devez inclure au moins #CONTENT# dans ce mod\00E8le. Les cha\00EEnes de substitution suivantes sont autoris\00E9es dans le mod\00E8le de colonne :</p>'),
'<ul>',
unistr('<li><strong>#COLUMN_NUMBER#</strong> : num\00E9ro de la colonne. Par exemple : 1, 2, 3...</li>'),
unistr('<li><strong>#COLUMN_ALPHA#</strong> : lettre repr\00E9sentant la colonne. Par exemple : a, b, c...</li>'),
unistr('<li><strong>#COLUMN_WORD#</strong> : mot repr\00E9sentant la colonne. Par exemple : un, deux, trois...</li>'),
unistr('<li><strong>#COLUMN_PLURAL#</strong> : \00E9l\00E9ment remplac\00E9 par "s" si le num\00E9ro de la colonne est sup\00E9rieur \00E0 un. Utilisez cet \00E9l\00E9ment si la mise en page n\00E9cessite un nom de classe "column" pour la premi\00E8re colonne et "columns" pour les colonnes suivant')
||'es. Par exemple : class="#COLUMN_WORD# column#COLUMN_PLURAL#"</li>',
unistr('<li><strong>#COLUMN_SPAN_NUMBER#</strong> : num\00E9ro d''attribut ColSpan. Par exemple : 1, 2, 3...</li>'),
unistr('<li><strong>#COLUMN_SPAN_ALPHA#</strong> : lettre repr\00E9sentant l''attribut ColSpan. Par exemple : a, b, c...</li>'),
unistr('<li><strong>#COLUMN_SPAN_WORD#</strong> : mot repr\00E9sentant l''attribut ColSpan. Par exemple : un, deux, trois...</li>'),
unistr('<li><strong>#COLUMN_SPAN_PLURAL#</strong> : \00E9l\00E9ment remplac\00E9 par "s" si l''attribut ColSpan est sup\00E9rieur \00E0 un. Utilisez cet \00E9l\00E9ment si la mise en page n\00E9cessite un nom de classe "column" pour un attribut ColSpan unique et "columns" si plusieurs colon')
||unistr('nes sont indiqu\00E9es. Par exemple : class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL#"</li>'),
unistr('<li><strong>#CSS_CLASSES#</strong> : \00E9l\00E9ment remplac\00E9 par la valeur indiqu\00E9e pour Classes CSS de colonne. Cet \00E9l\00E9ment permet de personnaliser davantage une colonne avec des classes CSS.</li>'),
unistr('<li><strong>#ATTRIBUTES#</strong> : \00E9l\00E9ment remplac\00E9 par la valeur indiqu\00E9e pour Attributs de colonne. Cet \00E9l\00E9ment permet de personnaliser davantage une colonne.</li>'),
unistr('<li><strong>#FIRST_LAST_COLUMN_ATTRIBUTES#</strong> : \00E9l\00E9ment remplac\00E9 par la valeur indiqu\00E9e dans Attributs de premi\00E8re colonne et Attributs de derni\00E8re colonne selon qu''il s''agit de la premi\00E8re ou de la derni\00E8re colonne.</li>'),
unistr('<li><strong>#CONTENT#</strong> : \00E9l\00E9ment remplac\00E9 par les r\00E9gions, les \00E9l\00E9ments de page ou les boutons affich\00E9s dans la colonne.</li>'),
'</ul>',
'<p>',
'Exemple :',
'<pre>',
'&lt;div class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL# #CSS_CLASSES#"&gt;#CONTENT#&lt;/div&gt;',
'</pre>',
'</p>'))
