,p_source=>'DISPLAY_CONDITION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CONDITION_LIST'
,p_named_lov=>'STANDARD_CONDITION_TYPES'
,p_lov=>'.'||wwv_flow_imp.id(13602414170805697)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Onglet non conditionnel -'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<P>S\00E9lectionnez l''une des conditions pr\00E9d\00E9finies si vous voulez que l''onglet ne s''affiche que dans certains cas :</P>'),
'',
'<UL>',
'',
unistr('<LI>CURRENT_PAGE_NOT_EQUALS_CONDITION : l''onglet ne s''affiche que si la page en cours n''est pas la page indiqu\00E9e dans le champ Condition d''affichage.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_EQUALS_CONDITION : l''onglet ne s''affiche que si la page en cours est la page indiqu\00E9e dans le champ Condition d''affichage.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_NOT_IN_CONDITION : l''onglet ne s''affiche que si la page en cours ne figure pas dans la liste de pages indiqu\00E9e dans le champ Condition d''affichage (liste de pages s\00E9par\00E9es par des virgules).</LI>'),
'',
unistr('<LI>CURRENT_PAGE_IN_CONDITION : l''onglet ne s''affiche que si la page en cours figure dans la liste de pages indiqu\00E9e dans le champ Condition d''affichage (liste de pages s\00E9par\00E9es par des virgules).</LI>'),
'',
unistr('<LI>USER_IS_NOT_PUBLIC_USER : l''onglet ne s''affiche que si l''utilisateur en cours n''est pas l''utilisateur public. Il n''y a rien \00E0 saisir dans le champ Condition d''affichage.</LI>'),
'',
unistr('<LI>USER_IS_PUBLIC_USER : l''onglet ne s''affiche que si l''utilisateur en cours est l''utilisateur public. Il n''y a rien \00E0 saisir dans le champ Condition d''affichage.</LI>'),
'',
unistr('<LI>EXISTS : l''onglet ne s''affiche que si la requ\00EAte indiqu\00E9e dans le champ Condition d''affichage renvoie au moins une ligne.</LI>'),
'',
unistr('<LI>ITEM_IS_NOT_NULL : l''onglet ne s''affiche que si l''\00E9l\00E9ment identifi\00E9 dans le champ Condition d''affichage n''est pas NULL.</LI>'),
'',
unistr('<LI>ITEM_IS_NULL : l''onglet ne s''affiche que si l''\00E9l\00E9ment identifi\00E9 dans le champ Condition d''affichage est NULL.</LI>'),
'',
unistr('<LI>NOT_EXISTS : l''onglet ne s''affiche que si la requ\00EAte indiqu\00E9e dans le champ Condition d''affichage ne renvoie aucune ligne.</LI>'),
'',
unistr('<LI>PLSQL_EXPRESSION : l''onglet ne s''affiche que si l''\00E9valuation de l''expression PL/SQL indiqu\00E9e dans le champ Condition d''affichage aboutit \00E0 la valeur True.</LI>'),
'',
unistr('<LI>SQL_EXPRESSION : l''onglet ne s''affiche que si l''\00E9valuation de l''expression SQL indiqu\00E9e dans le champ Condition d''affichage aboutit \00E0 la valeur True.</LI></UL>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
