'',
unistr('<p>Le pr\00E9fixe "THEME$" est automatiquement ajout\00E9 au nom interne d''un module d''extension de type Composant de mod\00E8le faisant partie d''un th\00E8me : <code>THEME$COM.MYCOMPANY.BADGE</code>.'),
unistr('Utilisez ce nom interne pour appliquer manuellement un composant de mod\00E8le du th\00E8me en cours au sein d''un composant &PRODUCT_NAME. dans lequel les directives de mod\00E8le c\00F4t\00E9 serveur sont prises en charge :'),
'</p>',
'<pre><code>',
'{with/}',
'MY_ARGUMENT:=foo',
'{apply THEME$COM.MYCOMPANY.BADGE/}    ',
'</code></pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
