wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3053446993523770.4002)
,p_plug_name=>'Aide - Emplacements'
,p_region_template_options=>'#DEFAULT#:js-dialog-size720x480'
,p_plug_template=>wwv_flow_imp.id(557449278618308550.4002)
,p_plug_display_sequence=>220
,p_plug_display_point=>'REGION_POSITION_05'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
unistr('    <li>Si le composant de mod\00E8le est utilis\00E9 dans une r\00E9gion, affich\00E9e sous la forme d''un \00E9tat partiel, &PRODUCT_NAME. affichera uniquement des emplacements dans le mod\00E8le partiel. Les effets secondaires incluent l''impossibilit\00E9 de le r\00E9g\00E9n\00E9rer dyna')
||'miquement et de le charger en mode lazy.</li>',
unistr('    <li>Si le composant de mod\00E8le est utilis\00E9 dans une r\00E9gion, affich\00E9e sous la forme d''un \00E9tat, &PRODUCT_NAME. affichera uniquement des emplacements dans le mod\00E8le de conteneur d''\00E9tat. Ce dernier entoure le mod\00E8le de corps d''\00E9tat.</li>'),
unistr('    <li>Il est impossible d''afficher des emplacements dans les lignes d''\00E9tat ou les colonnes d''\00E9tat interactif. En effet, le contenu d''emplacement n''est pas con\00E7u pour \00EAtre r\00E9p\00E9t\00E9 dans l''affichage de page.</li>'),
unistr('    <li>Il est possible de v\00E9rifier l''existence d''un contenu d''emplacement, de fa\00E7on \00E0 pouvoir afficher un balisage suppl\00E9mentaire uniquement si l''emplacement est utilis\00E9. Exemple :'),
'        <pre><code>',
'            &lt;div class="outer-div"&gt;',
'            {if SLOT_A/}',
'            &lt;div class="inner-div"&gt;#SLOT_A#&lt;/div&gt;',
'            {endif/}',
'            &lt;/div&gt;',
'        </code></pre>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
