,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le nom de la fonction PL/SQL \00E0 appeler pour lib\00E9rer les ressources verrouill\00E9es ou annuler les lignes associ\00E9es dans un contexte de workflow, en particulier lorsque le module d''extension impl\00E9mente un \00E9tat d''attente. '),
unistr('En appelant la fonction d''interruption, le module d''extension peut lib\00E9rer efficacement des ressources si l''instance de workflow associ\00E9e est interrompue.'),
unistr('Il peut r\00E9f\00E9rencer une fonction du bloc de code PL/SQL anonyme, une fonction de package ou une fonction autonome dans la base de donn\00E9es. Exemple :'),
'<pre>',
'terminate_proc',
'</pre></p>',
'',
unistr('<p>S''il fait r\00E9f\00E9rence \00E0 une fonction autonome ou \00E0 une fonction de package PL/SQL de base de donn\00E9es, vous pouvez utiliser la cha\00EEne de substitution <code>#OWNER#</code> pour r\00E9f\00E9rencer le sch\00E9ma d''analyse de l''application en cours. Exemple :'),
'<pre>',
'#OWNER#.terminate_proc',
'</pre></p>',
'',
unistr('<p>Les fonctions d''interruption de module d''extension de type de processus doivent impl\00E9menter l''interface suivante :'),
'',
'<pre>',
'function name_of_function (',
'    p_process in apex_plugin.t_process,',
'    p_plugin  in apex_plugin.t_plugin )',
'    return apex_plugin.t_process_terminate_result',
'',
'</pre>',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
