 p_id=>wwv_flow_imp.id(1606759360479201.4002)
,p_name=>'P4410_REPORT_CONT_TEMPLATE'
,p_item_sequence=>200
,p_item_plug_id=>wwv_flow_imp.id(4004640729629327.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Conteneur d''\00E9tat')
,p_source=>'REPORT_CONTAINER_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le balisage du mod\00E8le de conteneur d''\00E9tat. Les ID statiques des attributs personnalis\00E9s dont la port\00E9e est Etat peuvent \00EAtre r\00E9f\00E9renc\00E9s \00E0 l''aide de la syntaxe <code>#STATIC_ID#</code>.'),
unistr('Vous pouvez synchroniser rapidement toutes les valeurs de r\00E9serve en tant qu''attributs personnalis\00E9s \00E0 l''aide du bouton <strong>Synchroniser les attributs</strong>.'),
'</p>',
'<p>',
unistr('Les valeurs de r\00E9serve de mod\00E8le pr\00E9d\00E9fini suivantes sont prises en charge :'),
'<dl>',
'<dt>APEX$DOM_ID</dt>',
unistr('<dd>ID DOM unique g\00E9n\00E9r\00E9 lors de l''appel du mod\00E8le, utile pour r\00E9f\00E9rencer d''autres \00E9l\00E9ments DOM dans le balisage HTML fourni.</dd>'),
'<dt>APEX$COMPONENT_CSS_CLASSES</dt>',
unistr('<dd>Classes CSS indiqu\00E9es pour la r\00E9gion.</dd>'),
'<dt>APEX$REPORT_BODY</dt>',
unistr('<dd>Sortie du mod\00E8le de corps d''\00E9tat.</dd>'),
'</dl>',
'</p>',
'',
unistr('<p>Vous pouvez \00E9galement utiliser des valeurs de r\00E9serve d''emplacement pour permettre au conteneur d''\00E9tat d''afficher des composants de page (r\00E9gions, \00E9l\00E9ments, boutons). Les emplacements peuvent \00EAtre r\00E9f\00E9renc\00E9s \00E0 l''aide de la syntaxe <code>#SLOT_STAT')
||unistr('IC_ID#</code>. Pour afficher un emplacement conditionnellement en fonction de son utilisation, employez la syntaxe <code>{if SLOT_STATIC_ID/}&lt;div class="inner-div"&gt;#SLOT_STATIC_ID#&lt;/div&gt;{endif/}</code>, qui n''affiche un balisage suppl\00E9men')
||unistr('taire que si l''emplacement est utilis\00E9. Les emplacements du mod\00E8le de conteneur d''\00E9tat ne s''affichent que si la r\00E9gion associ\00E9e utilise <strong>Afficher : Multiple (\00E9tat)</strong>.</p>'),
'',
unistr('<p>Prend en charge les directives de mod\00E8le.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
