'<dt>APEX$MESSAGE</dt>',
unistr('<dd>Texte du message indiquant qu''aucune donn\00E9e n''a \00E9t\00E9 trouv\00E9e.</dd>'),
'<dt>APEX$MESSAGE_ICON</dt>',
unistr('<dd>Classe de l''ic\00F4ne indiquant qu''aucune donn\00E9e n''a \00E9t\00E9 trouv\00E9e.</dd>'),
'<dt>APEX$COMPONENT_CSS_CLASSES</dt>',
unistr('<dd>Classes CSS indiqu\00E9es pour la r\00E9gion.</dd>'),
'<dt>APEX$ROWS</dt>',
