,p_lov=>'.'||wwv_flow_imp.id(8409910097232187)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez comment le module d''extension peut \00EAtre affich\00E9 et o\00F9 il peut \00EAtre utilis\00E9.</p>'),
'<p>',
'<dl>',
'<dt>Unique (partiel)</dt>',
unistr('<dd>Lorsque cette case est coch\00E9e, le composant de mod\00E8le peut \00EAtre utilis\00E9 pour une colonne d''\00E9tat interactif ou pour une r\00E9gion afin d''afficher une seule ligne.</dd>'),
unistr('<dt>Multiple (\00E9tat)</dt>'),
unistr('<dd>Lorsque cette case est coch\00E9e, le composant de mod\00E8le peut \00EAtre utilis\00E9 pour une r\00E9gion afin d''afficher plusieurs lignes avec des options de pagination.</dd>'),
unistr('<dt>R\00E9gion uniquement</dt>'),
unistr('<dd>Lorsque cette case est coch\00E9e, le composant de mod\00E8le peut \00EAtre utilis\00E9 en tant que r\00E9gion affichant des valeurs statiques. Le mod\00E8le HTML fourni est affich\00E9 sans \00EAtre entour\00E9 d''\00E9l\00E9ments HTML d''encapsulation. La r\00E9gion comporte un nombre d''attrib')
||unistr('uts limit\00E9 dans le concepteur de page (Mod\00E8le de r\00E9gion, Texte d''en-t\00EAte et Texte de pied de page sont exclus). Il est recommand\00E9 d''inclure la substitution <code>APEX$DOM_ID</code> en tant qu''attribut d''ID d''un \00E9l\00E9ment dans le mod\00E8le afin de garantir')
||unistr(' le fonctionnement des fonctionnalit\00E9s APEX existantes avec le composant.</dd>'),
'</dl>',
unistr('<p>Les composants de mod\00E8le peuvent toujours \00EAtre utilis\00E9s dans les directives de mod\00E8le c\00F4t\00E9 serveur \00E0 l''aide des syntaxes <code>{with/}</code> et <code>{apply/}</code> sans cocher aucune case.<p>'),
'<p>Exemple :',
'<pre>',
'{with/}',
'PLACEHOLDER1:=Some value',
'PLACEHOLDER2:=Some value',
'{apply INTERNAL_NAME/}',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
