wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(9811750713144402.4002)
,p_name=>'P4410_PARTIAL_TEMPLATE'
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(4004640729629327.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Partiel'
,p_source=>'PARTIAL_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>25
,p_field_template=>wwv_flow_imp.id(561549716994252345.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le balisage du mod\00E8le. Les ID statiques des attributs personnalis\00E9s de port\00E9e "Composant" peuvent \00EAtre r\00E9f\00E9renc\00E9s \00E0 l''aide de la syntaxe <code>#STATIC_ID#</code>.'),
unistr('Vous pouvez synchroniser rapidement toutes les valeurs de r\00E9serve en tant qu''attributs personnalis\00E9s \00E0 l''aide du bouton <strong>Synchroniser \00E0 partir des mod\00E8les</strong> de la r\00E9gion Attributs personnalis\00E9s.'),
'</p>',
'<p>',
unistr('Les valeurs de r\00E9serve de mod\00E8le pr\00E9d\00E9fini suivantes sont prises en charge :'),
'<dl>',
'<dt>APEX$DOM_ID</dt>',
unistr('<dd>ID DOM unique g\00E9n\00E9r\00E9 lors de l''appel du mod\00E8le, utile pour r\00E9f\00E9rencer d''autres \00E9l\00E9ments DOM dans le balisage HTML fourni.</dd>'),
'<dt>APEX$IS_LAZY_LOADING</dt>',
unistr('<dd>D\00E9finie sur <code>T</code> si la r\00E9gion utilise le chargement lazy pour charger ses donn\00E9es et que le balisage squelette doit \00EAtre affich\00E9 \00E0 la place.</dd>'),
'<dt>APEX$HAS_ACTION_BUTTONS</dt>',
unistr('<dd>D\00E9finie sur <code>T</code> si au moins un bouton ou une action de menu de bouton est affich\00E9.</dd>'),
'<dt>APEX$TITLE</dt>',
unistr('<dd>Titre de la r\00E9gion.</dd>'),
'<dt>APEX$COMPONENT_CSS_CLASSES</dt>',
unistr('<dd>Classes CSS indiqu\00E9es pour la r\00E9gion.</dd>'),
'<dt>APEX$SELECTOR</dt>',
unistr('<dd>Pour la prise en charge de la s\00E9lection de ligne. S''affiche sous la forme d''un contr\00F4le de bouton d''option ou de case \00E0 cocher selon le type de s\00E9lection : unique ou multiple. Cette valeur de r\00E9serve est uniquement remplie dans le contexte d''un \00E9')
||unistr('tat de composant de mod\00E8le.</dd>'),
'<dt>APEX$VALUE_IDENTIFIES_ROW</dt>',
unistr('<dd>Contient les valeurs de ligne des colonnes d''\00E9tat qui ont activ\00E9 le param\00E8tre de colonne en lien avec l''accessibilit\00E9 Valeur identifiant la ligne. L''activation de ce param\00E8tre dans plusieurs colonnes d''\00E9tat renvoie les valeurs en les s\00E9parant par')
||unistr(' un espace. Cette valeur de r\00E9serve est uniquement remplie dans le contexte d''un \00E9tat de composant de mod\00E8le.</dd>'),
'</dl>',
'</p>',
unistr('<p>Les ID statiques des positions d''action peuvent \00EAtre r\00E9f\00E9renc\00E9s \00E0 l''aide de la syntaxe <code>#STATIC_ID#</code>.'),
unistr('Si la position d''action est de type Lien, la syntaxe <code>#STATIC_ID_ATTR#</code> peut \00EAtre utilis\00E9e pour r\00E9f\00E9rencer la valeur de l''attribut de lien.</p>'),
unistr('<p>Vous pouvez \00E9galement utiliser des valeurs de r\00E9serve d''emplacement pour permettre \00E0 l''\00E9tat partiel d''afficher des composants de page (r\00E9gions, \00E9l\00E9ments, boutons). Les emplacements peuvent \00EAtre r\00E9f\00E9renc\00E9s \00E0 l''aide de la syntaxe <code>#SLOT_STATIC_')
||unistr('ID#</code>. Pour afficher un emplacement conditionnellement en fonction de son utilisation, employez la syntaxe <code>{if SLOT_STATIC_ID/}&lt;div class="inner-div"&gt;#SLOT_STATIC_ID#&lt;/div&gt;{endif/}</code> qui n''affiche un balisage suppl\00E9mentair')
||unistr('e que si l''emplacement est utilis\00E9. Les emplacements du mod\00E8le partiel ne s''affichent que si la r\00E9gion associ\00E9e utilise <strong>Afficher en tant que : Unique (partiel)</strong>.</p>'),
'',
unistr('<p>Prend en charge les directives de mod\00E8le.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
