,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le nom interne du module d''extension. &PRODUCT_NAME. emploie ce nom en interne pour identifier le module d''extension, mais il n''est pas affich\00E9. Ce nom doit \00EAtre unique dans votre application en cours.</p>'),
'',
unistr('<p>Il est recommand\00E9 d''utiliser le nom de domaine de votre organisation comme pr\00E9fixe pour les noms de module d''extension, afin de cr\00E9er un nom unique global. Par exemple, le nom de domaine "mycompany.com" servant de pr\00E9fixe au module d''extension de ')
||unistr('type d''\00E9l\00E9ment intitul\00E9 ''Slider'' donnera le nom interne suivant : <code>COM.MYCOMPANY.SLIDER</code></p>'),
'',
unistr('<p>Le pr\00E9fixe "THEME$" est toujours ajout\00E9 au nom interne d''un module d''extension de type Composant de mod\00E8le faisant partie d''un th\00E8me : <code>THEME$COM.MYCOMPANY.BADGE</code>.'),
unistr('Utilisez ce nom interne pour appliquer manuellement un composant de mod\00E8le lorsque les directives de mod\00E8le c\00F4t\00E9 serveur sont prises en charge.'),
'<pre><code>',
'{with/}',
'MY_ARGUMENT:=foo',
'{apply THEME$COM.MYCOMPANY.BADGE/}    ',
'</code></pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
