wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(439437108210840247.4002)
,p_name=>'On Region Attributes Change'
,p_event_sequence=>120
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P4410_REGION_ATTRIBUTES'
