'const attributes = apex.items.P4410_DYNAMIC_ACTIN_ATTRIBUTES.value;',
'const dependentAiCheckboxes$ = apex.jQuery( "input[value=AI_SYSTEM_PROMPT],input[value=AI_WELCOME_MESSAGE]", "#P4410_DYNAMIC_ACTIN_ATTRIBUTES" );',
