wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(439466610220411226.4002)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Standard Attributes / Comp Types / API Version '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P4410_STANDARD_ATTRIBUTES :=',
'    case :P4410_PLUGIN_TYPE',
'        when ''ITEM TYPE''           then :P4410_PAGE_ITEM_ATTRIBUTES',
'        when ''REPORT COLUMN TYPE''  then :P4410_PAGE_ITEM_ATTRIBUTES',
'        when ''REGION TYPE''         then :P4410_REGION_ATTRIBUTES',
'        when ''WEB SOURCE TYPE''     then :P4410_WEB_SOURCE_ATTRIBUTES',
'        when ''PROCESS TYPE''        then :P4410_PROCESS_ATTRIBUTES',
'        when ''DYNAMIC ACTION''      then :P4410_DYNAMIC_ACTIN_ATTRIBUTES',
'        when ''AUTHENTICATION TYPE'' then :P4410_AUTHENTCATION_ATTRIBUTES',
'        when ''TEMPLATE COMPONENT''  then :P4410_TEMPLATE_COMP_ATTRIBUTES',
'    end;',
'',
':P4410_DEFAULT_ESCAPE_MODE :=',
'    case :P4410_PLUGIN_TYPE',
'        when ''TEMPLATE COMPONENT''  then :P4410_DEFAULT_ESCAPE_MODE',
'    end;',
'',
':P4410_SUPPORTED_COMP_TYPES :=',
'    case :P4410_PLUGIN_TYPE',
'        when ''ITEM TYPE''           then :P4410_ITEM_COMPONENT_TYPES',
'        when ''PROCESS TYPE''        then :P4410_PROCESS_COMPONENT_TYPES',
'        when ''TEMPLATE COMPONENT''  then :P4410_TMPL_COMPONENT_TYPES',
'    end;',
'',
':P4410_API_VERSION :=',
'    case :P4410_PLUGIN_TYPE',
'        when ''ITEM TYPE''           then :P4410_API_VERSION_ITEM',
'        when ''REGION TYPE''         then :P4410_API_VERSION_REGION',
'        else ''1''',
'    end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>439466610220411226.4002
);
