'    then',
'        delete wwv_flow_plugin_attributes',
'         where plugin_id         = :P4410_ID',
'           and security_group_id = :WORKSPACE_ID',
'           and attribute_scope   in ( ''REPORT'', ''REPORT_GROUP'' );',
