 p_id=>wwv_flow_imp.id(20561242234507529.4002)
,p_name=>'P4446_REFERENCE_ID'
,p_source_data_type=>'NUMBER'
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(20555148356507447.4002)
,p_item_source_plug_id=>wwv_flow_imp.id(14905826791797203.4002)
,p_prompt=>unistr('Abonnement \00E0 partir de')
,p_source=>'REFERENCE_ID'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.flow_id ||'' ''||f.name||'' - ''|| b.display_name d,',
'       b.id r',
'  from wwv_flow_plugin_settings_dev b,',
'       wwv_flows f',
' where b.flow_id          != nvl(:FB_FLOW_ID,0)',
'   and b.flow_id           = f.id',
'   and f.build_status      not in (''RUN_ONLY'',''RUN_AND_HIDDEN'')',
'   and b.security_group_id = :WORKSPACE_ID',
'   and f.security_group_id = :WORKSPACE_ID',
'   -- limit to current plugin and plugin type',
'   and ((    b.plugin      = :P4446_PLUGIN',
'         and b.plugin_type = :P4446_PLUGIN_TYPE )',
'         -- always show selected master record',
'          or b.id = :P4446_REFERENCE_ID_INIT )',
'order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Aucun abonnement -'
,p_lov_cascade_parent_items=>'P4446_PLUGIN,P4446_PLUGIN_TYPE,P4446_REFERENCE_ID_INIT'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>50
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('S\00E9lectionnez le composant ma\00EEtre \00E0 partir duquel effectuer l''abonnement. Lorsque vous s\00E9lectionnez un composant ma\00EEtre et que vous cliquez sur le bouton <strong>Appliquer les modifications</strong>, les param\00E8tres de composant sont automatiquement r\00E9')
||unistr('g\00E9n\00E9r\00E9s \00E0 partir du ma\00EEtre s\00E9lectionn\00E9.<br /><br />Si les param\00E8tres de composant sont d\00E9j\00E0 abonn\00E9s, cliquez sur le bouton <strong>R\00E9g\00E9n\00E9rer les param\00E8tres de composant</strong> pour r\00E9g\00E9n\00E9rer les param\00E8tres de composant \00E0 partir du composant ma\00EEtre.')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
