,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_05'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>L''authentification est le processus consistant \00E0 \00E9tablir l''identit\00E9 de chaque utilisateur avant que celui-ci puisse acc\00E9der \00E0 votre application. Cette op\00E9ration peut exiger que l''utilisateur entre un nom utilisateur et un mot de passe, et peut imp')
||unistr('liquer l''utilisation de certificats num\00E9riques ou d''une cl\00E9 s\00E9curis\00E9e.</p>'),
'',
unistr('<p>Utilisez cette page pour cr\00E9er ou modifier des mod\00E8les d''authentification et d\00E9finir celui utilis\00E9 par votre application. Le mod\00E8le d''authentification en cours d\00E9termine la mani\00E8re dont votre application identifie et v\00E9rifie l''utilisateur final. E')
||unistr('n fonction du type de mod\00E8le d''authentification s\00E9lectionn\00E9, vous pouvez utiliser plusieurs param\00E8tres et points d''ancrage pour affiner l''authentification de votre application.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
