wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346057922272119929.4002)
,p_name=>'P4495_POST_AUTH_PROCESS'
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(345924009281078364.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Nom de proc\00E9dure de postauthentification')
,p_source=>'POST_AUTH_PROCESS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez le nom de la proc\00E9dure que doit ex\00E9cuter la proc\00E9dure de connexion &PRODUCT_NAME. (API de connexion) apr\00E8s'),
unistr('l''\00E9tape d''authentification (v\00E9rification des informations d''identification). La proc\00E9dure de connexion ex\00E9cutera ce code apr\00E8s'),
unistr('la v\00E9rification des informations d''identification de l''utilisateur, mais avant l''inscription de l''utilisateur dans la session et le r\00E9acheminement vers la'),
unistr('page d''application voulue. La proc\00E9dure peut \00EAtre d\00E9finie dans l''attribut de code PL/SQL ou'),
unistr('dans la base de donn\00E9es.</p>'),
'',
unistr('<p>Par exemple, pour transformer le nom utilisateur authentifi\00E9 <code>JOHNDOE@EXAMPLE.COM</code> en'),
unistr(' <code>JOHNDOE</code>, d\00E9finissez la proc\00E9dure <code>my_post_auth</code> dans l''attribut de code PL/SQL :</p>'),
'<pre>',
'procedure my_post_auth',
'is',
'begin',
'  apex_custom_auth.set_user (',
'    p_user => regexp_replace(:APP_USER, ''@.*'', null) );',
'end my_post_auth;',
'</pre>',
'',
unistr('<p>Ensuite, r\00E9f\00E9rencez cette proc\00E9dure dans l''attribut Nom de proc\00E9dure de postauthentification :</p>'),
'<pre>',
'my_post_auth',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346898909384210784.4002)
,p_name=>'P4495_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(345889721617072434.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Type de mod\00E8le')
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHENTICATION_SCHEME_TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHENTICATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHENTICATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHENTICATION TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>S\00E9lectionnez la mani\00E8re dont ce mod\00E8le d''authentification sera appliqu\00E9. Les types int\00E9gr\00E9s suivants sont pris en charge (ils peuvent \00EAtre \00E9tendus via des modules d''extension) :</p>'),
'<ul>',
unistr('    <li><strong>Connexion \00E0 l''extension de Builder :</strong> permet d''int\00E9grer cette application \00E0 l''environnement de d\00E9veloppement APEX.</li>'),
unistr('    <li><strong>Personnalis\00E9 :</strong> permet de cr\00E9er un mod\00E8le d''authentification personnalis\00E9 \00E0 partir de z\00E9ro, pour b\00E9n\00E9ficier d''un contr\00F4le total sur l''interface d''authentification.</li>'),
unistr('    <li><strong>Comptes de base de donn\00E9es :</strong> ce mod\00E8le d''authentification exige qu''un utilisateur de base de donn\00E9es (sch\00E9ma) existe dans la base de donn\00E9es locale. Lorsque vous utilisez cette m\00E9thode, le nom utilisateur et le mot de passe d')
||unistr('u compte de base de donn\00E9es servent \00E0 authentifier l''utilisateur.</li>'),
unistr('    <li><strong>Variable d''en-t\00EAte HTTP :</strong> authentification externe, avec le nom utilisateur stock\00E9 dans une variable d''en-t\00EAte HTTP d\00E9finie par le serveur Web.</li>'),
unistr('    <li><strong>Extension d''application interne :</strong> utilisez ce mod\00E8le pour les extensions des applications internes.</li>'),
