,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('S\00E9lectionnez <strong>Activ\00E9</strong> pour activer le basculement entre le mod\00E8le d''authentification par d\00E9faut et ce mod\00E8le dans la session &PRODUCT_NAME. en cours. S\00E9lectionnez <strong>D\00E9sactiv\00E9</strong> si le mod\00E8le d''authentification ne doit pas \00EA')
||unistr('tre activ\00E9 au moment de l''ex\00E9cution.'),
'</p><p>',
unistr('S''il est activ\00E9, le mod\00E8le d''authentification de la session en cours peut \00EAtre modifi\00E9 en transmettant <strong>APEX_AUTHENTICATION=nom du mod\00E8le</strong> dans le param\00E8tre de demande d''une URL.'),
'</p>',
'<h3>Exemple</h3>',
'<p>',
unistr('Le d\00E9veloppeur ajoute un bouton libell\00E9 "Connexion avec OAuth2" \00E0 la page de connexion de l''application, qui redirige vers'),
'<pre>',
'f?p=&amp;APP_ID.:1:&amp;APP_SESSION.:APEX_AUTHENTICATION=OAuth2-Scheme',
'</pre>',
unistr('o\00F9 "OAuth2-Scheme" est le nom du mod\00E8le d''authentification. Lors du traitement de la demande (en supposant que l''option Basculer dans la session est activ\00E9e), &PRODUCT_NAME. inscrit le mod\00E8le dans la session et l''utilisera pour toutes les demandes fu')
||'tures.',
'</p>',
'<p>',
'<strong>Remarque :</strong>',
unistr('Si l''application contient une <em>proc\00E9dure de configuration d''authentification</em>,'),
'la modification de l''authentification via l''URL n''est pas prise en charge.',
unistr('Cependant, vous devez tout de m\00EAme d\00E9finir cet attribut.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
