wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(6902842551389926.4002)
,p_name=>'P4653_DEFAULT_LANDMARK_TYPE'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(6902767343389925.4002)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Type de point de rep\00E8re par d\00E9faut')
,p_source=>'DEFAULT_LANDMARK_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>'STATIC:Banner;banner,Complementary;complementary,Content Info;contentinfo,Form;form,Main;main,Navigation;navigation,Region;region,Search;search'
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Aucun point de rep\00E8re par d\00E9faut -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>D\00E9finissez le type de point de rep\00E8re par d\00E9faut \00E0 utiliser pour ce mod\00E8le de r\00E9gion. Lorsque ce mod\00E8le de r\00E9gion est utilis\00E9 par une r\00E9gion, il s''agira du type de point de rep\00E8re visible pour les utilisateurs du lecteur d''\00E9cran, sauf s''il a \00E9t\00E9 r')
||unistr('emplac\00E9 au niveau de la r\00E9gion.</p>'),
unistr('<p>Remarque : afin que cette fonctionnalit\00E9 marche, l''attribut de mod\00E8le doit inclure la cha\00EEne de substitution <code>#REGION_LANDMARK_ATTRIBUTES#</code>. Celui-ci doit \00EAtre d\00E9fini sur l''\00E9l\00E9ment de conteneur principal du mod\00E8le.</p>'),
unistr('<p>Les points de rep\00E8re fournissent un moyen efficace d''identifier l''organisation et la structure d''une page Web. Les informations de structure transmises visuellement aux utilisateurs doivent \00EAtre repr\00E9sent\00E9es par programmation dans le balisage \00E0 l''')
||unistr('aide de r\00F4les de point de rep\00E8re. Les r\00F4les de point de rep\00E8re prennent en charge la navigation par clavier vers la structure d''une page Web pour les utilisateurs du lecteur d''\00E9cran et peuvent \00EAtre utilis\00E9s comme cibles pour les extensions de navigat')
||unistr('eur permettant la navigation par clavier avanc\00E9e.</p>'),
unistr('<p>Le <a rel="noopener noreferrer" target="_blank" href="https://www.w3.org/WAI/ARIA/apg/example-index/landmarks/index.html">site des points de rep\00E8re ARIA de W3C</a> fournit des informations utiles, notamment une impl\00E9mentation de r\00E9f\00E9rence correcte')
