,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>unistr('Les mod\00E8les d''\00E9tat fournissent un contr\00F4le de mod\00E8le sur les r\00E9sultats d''une ligne \00E0 partir d''une requ\00EAte SQL. Ils permettent de formater une ligne enti\00E8re ou d''indiquer une colonne particuli\00E8re. Les mod\00E8les d''\00E9tat qui d\00E9finissent une cellule sont pl')
||unistr('us petits, car ils ne d\00E9finissent que chacune des cellules, m\00EAme si toutes les cellules sont identiques. Utilisez des substitutions de nom de colonne, par exemple #ENAME# #JOB#, ou les substitutions de position de ligne #1# #2# pour remplacer les val')
||unistr('eurs de colonne. Les conditions de mod\00E8le d''\00E9tat vous permettent d''utiliser un mod\00E8le de ligne particulier fond\00E9 sur les valeurs de colonne de ligne ou le statut de session d''application. Par exemple : "#SAL# > 1000" ou "''#ENAME#'' = ''SMITH''" (A noter')
||unistr(' que les cha\00EEnes de texte sont entre guillemets). R\00E9f\00E9rencez le num\00E9ro de colonne au moyen de #ROWNUM#.')
,p_plug_query_num_rows=>150
,p_plug_query_num_rows_type=>'ROWS_X_TO_Y_OF_Z'
