'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_email_templates sub',
'          where sub.reference_id      = e.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when e.reference_id is not null then',
'           case',
'               when master.version_scn = e.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != e.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,',
'       --',
'       null as actions   ',
'  from wwv_flow_email_templates e,',
'       wwv_flow_email_templates master',
' where e.flow_id           = :FB_FLOW_ID',
'   and e.security_group_id = :WORKSPACE_ID',
'   and e.reference_id      = master.id (+)',
'   and e.security_group_id = master.security_group_id (+)'))
