 p_id=>wwv_flow_imp.id(299056867.4002)
,p_plug_name=>'A propos de'
,p_region_template_options=>'#DEFAULT#:a-Region--sideRegion:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Les options de construction permettent aux d\00E9veloppeurs d''activer et de d\00E9sactiver sous conditions des fonctionnalit\00E9s et des composants d''application lors de l''installation de l''application ou lors de l''ex\00E9cution \00E0 l''aide des API <code>GET_BUILD_')
||'OPTION_STATUS</code> et <code>SET_BUILD_OPTION_STATUS</code>.</p>',
unistr('<p>Vous pouvez appliquer des options de construction \00E0 la plupart des composants (pages, r\00E9gions, \00E9l\00E9ments, validations, etc.) pour les inclure ou les exclure dans l''application d''ex\00E9cution :</p>'),
unistr('<p><strong>Inclure :</strong> les composants sont activ\00E9s et font partie de l''application.</p>'),
unistr('<p><strong>Exclure :</strong> les composants sont d\00E9sactiv\00E9s et ne font pas partie de l''application.</p>'),
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a></p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3738622552051132.4002)
,p_plug_name=>'Options de construction'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4002)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'   b.flow_id,',
'   b.patch_name,',
'   replace(b.patch_name,''_'','' '') build_option_name,',
'   wwv_flow_lang.system_message(b.patch_status) as patch_status,',
'   b.on_upgrade_keep_status,',
'   substr(b.patch_comment,1,500) patch_comment,',
'   b.id,',
'   decode(b.patch_status,',
'          ''EXCLUDE'', ''u-danger-text'',',
'          ''u-success-text'') as patch_class,',
'   decode (b.patch_status,',
'      ''EXCLUDE'',''icon-sc-build-option-off u-danger-text'',',
'      ''icon-sc-build-option-on u-success-text'') img,',
'   replace(b.patch_name,''_'', '' '') alt,',
'   wwv_flow_page_api.get_url(',
'       p_page        => 4911,',
'       p_clear_cache => 4911,',
'       p_items       => ''F4000_P4911_ID'',',
'       p_values      => b.id ) link,',
'   b.last_updated_by updated_by,',
'   b.last_updated_on updated,',
'   b.created_by,',
'   b.created_on created,',
'   (select count(*)',
'       from wwv_flow_steps s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) pages,',
'   (select count(*)',
'       from wwv_flow_step_items s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) page_items,',
'   (select count(*)',
'       from wwv_flow_step_buttons s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) page_buttons,',
'   (select count(*)',
'       from WWV_FLOW_STEP_BRANCHES s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) page_branches,',
'   (select count(*)',
'       from WWV_FLOW_STEP_COMPUTATIONS s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) page_computations,',
'   (select count(*)',
'       from WWV_FLOW_STEP_PROCESSING s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) page_processes,',
'   (select count(*)',
'       from WWV_FLOW_STEP_VALIDATIONS s',
'       where s.flow_id = :fb_flow_id and',
'             s.security_group_id = :flow_security_group_id and',
'             b.id = s.REQUIRED_PATCH) page_validations,',
'   (select count(*)',
'      from wwv_flow_page_da_events s',
'     where s.flow_id = :fb_flow_id and',
'           s.security_group_id = :flow_security_group_id and',
'           b.id = s.REQUIRED_PATCH) page_dynamic_actions,',
'   (select count(*)',
'      from wwv_flow_page_da_actions s',
'     where s.flow_id = :fb_flow_id and',
'           s.security_group_id = :flow_security_group_id and',
'           b.id = s.build_option_id) page_dynamic_action_actions,',
'   (select count(*)',
'       from wwv_flow_card_actions a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) page_card_actions,',
'   (select count(*)',
'       from wwv_flow_pwa_shortcuts a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) pwa_shortcuts,',
'   (select count(*)',
'       from wwv_flow_pwa_screenshots a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) pwa_screenshots,',
'   (select count(*)',
'       from wwv_flow_page_meta_tags a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) page_meta_tags,',
'   (select count(*)',
'       from wwv_flow_component_actions a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) page_component_actions,',
'   (select count(*)',
'       from wwv_flow_comp_menu_entries a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) page_action_menus,',
'   (select count(*)',
'       from wwv_flow_ai_config_rag_sources a',
'      where a.flow_id = :fb_flow_id and',
'            a.security_group_id = :flow_security_group_id and',
'            b.id = a.build_option_id) ai_config_rag_sources,',
'   wwv_flow_lang.system_message(nvl(b.default_on_export,b.patch_status)) DEFAULT_ON_EXPORT,',
'   b.FEATURE_IDENTIFIER,',
'   --',
'   case when b.reference_id is not null then',
'       coalesce ( to_char( master.flow_id ),',
'                   wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'   end as subscribed_from,',
'   ( select case when count(*) > 0 then count(*) end',
'       from wwv_flow_patches sub',
'      where sub.reference_id      = b.id',
'        and sub.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   ) as subscribers,',
'   case when b.reference_id is not null then',
'       case',
'           when master.version_scn = b.version_scn then',
'               wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'           when master.version_scn != b.version_scn then',
'               wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'           else',
'               wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'       end',
'   end subscription_status,',
'   --',
'   null as actions',
' from wwv_flow_patches b,',
'      wwv_flow_patches master',
'where b.flow_id                = :FB_FLOW_ID',
'  and b.security_group_id      = :FLOW_SECURITY_GROUP_ID',
'  and b.reference_id           = master.id (+)',
'  and b.security_group_id      = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
