wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3152898246834713.4002)
,p_plug_name=>unistr('Aper\00E7u des diff\00E9rences')
,p_region_name=>'DIFF_OVERVIEW'
,p_parent_plug_id=>wwv_flow_imp.id(3372976219152815.4002)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743.4002)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_lang_dev.builder_message(''APEXDEV.DIFF.CHANGED'', count(*)) as status_count,',
'       ''CHANGED'' as status',
'  from wwv_flow_diff_export_left_dev l,',
'       wwv_flow_diff_export_right_dev r',
' where l.offset_component_id = r.offset_component_id',
'   and l.component_type      = r.component_type',
'   and l.diff_checksum      != r.diff_checksum',
'union all',
'select wwv_flow_lang_dev.builder_message(''APEXDEV.DIFF.ADDED'', count(*)) as status_count,',
'       ''ADDED'' as status',
'  from wwv_flow_diff_export_right_dev r,',
'       wwv_flow_diff_export_left_dev l',
' where l.component_type      (+) = r.component_type ',
'   and l.offset_component_id (+) = r.offset_component_id ',
'   and l.component_type is null',
'   and l.offset_component_id is null',
'   and not exists (',
'       /* ignore list items when the list is being created/new */',
'       select null',
'         from wwv_flow_list_items',
'        where list_id in (select ir.component_id ',
'                            from wwv_flow_diff_export_right_dev ir',
'                           where ir.component_type = ''LIST''',
'                            and not exists',
'                                   ( select null ',
'                                       from wwv_flow_diff_export_left_dev il',
'                                      where il.component_type      = ir.component_type',
'                                        and il.offset_component_id = ir.offset_component_id',
'                                   )                         ',
'                        )',
'          and id                = r.component_id',
'          and security_group_id = :WORKSPACE_ID',
'   )',
'union all',
'select wwv_flow_lang_dev.builder_message(''APEXDEV.DIFF.MISSING'', count(*)) as status_count,',
'       ''MISSING'' as status',
'  from wwv_flow_diff_export_left_dev l,',
'       wwv_flow_diff_export_right_dev r ',
' where l.component_type         = r.component_type (+)',
'   and l.offset_component_id    = r.offset_component_id (+)',
'   and nvl(:P5300_REVERSE, ''N'') = ''N''   ',
'   and r.component_type is null',
'   and r.offset_component_id is null',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P5300_REVERSE'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
);
