wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3185079872144510.4002)
,p_plug_name=>'A propos des copies de travail'
,p_region_css_classes=>'padding-left-md padding-right-md'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3>Conseils</h3>',
'<ul>',
unistr('    <li>Les d\00E9veloppeurs peuvent utiliser des copies de travail distinctes. Afin d''\00E9viter les \00E9crasements ou les erreurs lors de la fusion :'),
'        <ul>',
'            <li>Verrouillez la page dans l''application principale avant de la modifier dans une copie de travail,</li>',
unistr('            <li>r\00E9servez des plages de pages pour les pages que chaque d\00E9veloppeur cr\00E9era,</li>'),
unistr('            <li>mettez-vous d''accord sur les noms de composant partag\00E9 que chacun ajoutera.</li>'),
'        </ul>',
'    </li>',
'    <li>Exportez une copie de travail selon les besoins en utilisant les <em>ID d''origine</em> pour maintenir son lien avec l''application principale.</li>',
unistr('    <li><em>Supprimez le lien</em> entre une copie de travail et l''application principale \00E0 l''aide de la t\00E2che <em>Copier une application</em>.</li>'),
'    <li>Supprimez les copies de travail <em>avant</em> de supprimer l''application.</li>',
'    </ul>',
'<h3>Types de composant non pris en charge</h3>',
'<p>Ces types de composant ne sont pas encore pris en charge pour la fusion <em>automatique</em> :',
unistr('   Traductions, th\00E8mes, mod\00E8les de th\00E8me, objets de prise en charge, propri\00E9t\00E9s d''application, onglets (h\00E9rit\00E9s) et'),
'   composants de niveau d''espace de travail comme les groupes d''applications, les informations d''identification ou les serveurs distants. Vous pouvez fusionner la copie de travail.',
unistr('   Vous devrez ensuite appliquer manuellement les ajouts ou les modifications apport\00E9s \00E0 ces types de composant.'),
'</p>',
'<h3>Limites</h3>',
unistr('<p>Les copies de travail pr\00E9sentent les limites suivantes :</p>'),
'<ul>',
unistr('    <li>Vous ne pouvez pas cr\00E9er une copie de travail d''une copie de travail.</li>'),
unistr('    <li>Les composants partag\00E9s ou les pages de copie de travail supprim\00E9s doivent \00EAtre supprim\00E9s <em>manuellement</em> dans l''application principale.</li>'),
unistr('    <li>Les composants <em>manquants</em> peuvent avoir \00EAtre enlev\00E9s dans la copie de travail ou peuvent exister uniquement dans l''application principale.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
