 p_id=>wwv_flow_imp.id(1419418494012532.4002)
,p_plug_name=>'Aide'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743.4002)
,p_plug_display_sequence=>20
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
unistr('    <li><strong>Ajouter :</strong> un nouveau composant sera ajout\00E9 \00E0 l''application cible et affect\00E9 au groupe de composants.</li>'),
unistr('    <li><strong>R\00E9g\00E9n\00E9rer :</strong> un composant existant sera r\00E9g\00E9n\00E9r\00E9.</li>'),
unistr('    <li><strong>R\00E9g\00E9n\00E9rer et affecter :</strong> un composant existant sera r\00E9g\00E9n\00E9r\00E9 et affect\00E9 au groupe de composants.</li>    '),
unistr('    <li><strong>Remplacer :</strong> un composant existant sera remplac\00E9 par le composant ma\00EEtre et affect\00E9 au groupe de composants.</li>'),
unistr('    <li><strong>R\00E9utiliser :</strong> un composant existant sera affect\00E9 au groupe de composants.</li>'),
