wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4800456594119504.4002)
,p_plug_name=>'Automatisations'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>70
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Les <strong>automatisations</strong> lancent un ensemble s\00E9quentiel de processus. Elles sont utilis\00E9es pour surveiller les donn\00E9es et effectuer ensuite l''action appropri\00E9e. Exemples : approbation automatique de demandes sp\00E9cifiques et envoi d''alertes')
||' par courriel.',
'</p>',
'<p>',
unistr('Les <strong>actions d''automatisation</strong> sont d\00E9clench\00E9es une fois pour chaque ligne renvoy\00E9e par la source d''automatisation. Une action peut r\00E9f\00E9rencer les valeurs de chaque colonne pour chaque ligne avec la syntaxe de variable attach\00E9e.</p>'),
'<p>',
unistr('Une fois l''application <em>import\00E9e</em>, les automatisations sont <em>d\00E9sactiv\00E9es</em> pour emp\00EAcher l''ex\00E9cution simultan\00E9e de plusieurs automatisations. L''automatisation doit \00EAtre explicitement activ\00E9e, soit sur cette page soit \00E0 l''aide du package ')
||'<strong>APEX_AUTOMATION</strong>.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a></p>',
'',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
