,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Exemple 1 : envoi d''un courriel. Il est suppos\00E9 qu''un mod\00E8le de courriel nomm\00E9 <strong>ORDER</strong> existe, avec les valeurs de r\00E9serve utilis\00E9es dans le '),
unistr('    param\00E8tre <strong>p_placeholders</strong>.'),
'</p>',
'<pre>',
'begin',
'    apex_mail.send (',
'        p_template_static_id => ''ORDER'',',
'        p_placeholders       => ''{ "ORDER_NUMBER": '' || :ORDER_NUMBER ||',
'                                  ''"ORDER_DATE":"''   || to_char( :ORDER_DATE, ''YYYY-MM-DD'' ) || ''", ''',
'                                  ''"ORDER_TOTAL":''   || :ORDER_TOTAL || ',
'                                ''}'',',
'        p_to                 => ''some_user@somewhere.com'' );',
'end;',
'</pre>',
'<p>',
unistr('    Exemple 2 : insertion d''une ligne dans une autre table. Si la valeur :SAL est NULL, un message d''avertissement est \00E9crit dans le journal d''automatisation.'),
'</p>',
'<pre>',
'begin',
'    insert into other_table( empno, ename, sal )',
'                     values( :EMPNO, :ENAME, :SAL );',
'    if :SAL is null then',
'        apex_automation.log_warn( ''EMPNO '' || :EMPNO ||'' has a NULL Salary'');',
'    end if;',
'end;',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
