wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409356763910720.4002)
,p_name=>'P7022_ACTION_TYPE'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1410170163910728.4002)
,p_item_source_plug_id=>wwv_flow_imp.id(1410170163910728.4002)
,p_item_default=>'NATIVE_PLSQL'
,p_prompt=>'Type'
,p_source=>'ACTION_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''PROCESS.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'           and ( ( select wwv_flow_f4000_util.is_cloud',
'                     from sys.dual ) = ''Y''',
'                  or name != ''GEOCODING'' )',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id                   = to_number(:FB_FLOW_ID)',
'           and security_group_id         = to_number(:WORKSPACE_ID)',
'           and plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('S\00E9lectionnez le type d''action.')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409543908910722.4002)
,p_name=>'P7022_REMOTE_PLSQL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(90116067165448609.4002)
,p_prompt=>unistr('Code PL/SQL (ex\00E9cut\00E9 sur le service SQL compatible REST)')
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Fournissez le code PL/SQL \00E0 ex\00E9cuter. Les valeurs de colonne de la requ\00EAte d''automatisation sont disponibles en tant que variables attach\00E9es et par nom de colonne, par exemple <strong>:EMPNO</strong>, <strong>:ENAME</strong>, etc. Par ailleurs, A')
||unistr('PEX fournit les variables attach\00E9es g\00E9n\00E9riques suivantes :'),
'</p>',
'<ul>',
unistr('    <li><strong>APEX$AUTOMATION_ROW_PK :</strong> si une colonne de cl\00E9 primaire a \00E9t\00E9 d\00E9finie, cette variable attach\00E9e contient la valeur de cl\00E9 primaire.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ROW_NUM :</strong> pour les automatisations bas\00E9es sur une requ\00EAte, cette variable attach\00E9e contient le nombre de lignes en cours.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ERROR_ROWS :</strong> pour les automatisations bas\00E9es sur une requ\00EAte, cette variable attach\00E9e contient le nombre de lignes dans lesquelles les actions ont g\00E9n\00E9r\00E9 des erreurs.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_LASTRUN_ISO :</strong> contient l''horodatage de l''ex\00E9cution d''automatisation <em>pr\00E9c\00E9dente</em>, au format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
'</ul>',
'<p style="padding-top: 10px">',
unistr('    Le package <strong>APEX_AUTOMATION</strong> peut ne pas \00EAtre disponible sur le service SQL compatible REST. Pour ajouter des messages au journal d''ex\00E9cution (<strong>LOG_WARN</strong>, <strong>LOG_INFO</strong>, <strong>LOG_ERROR</strong>), cr\00E9ez')
||unistr(' <em>une autre</em> action ex\00E9cut\00E9e sur la <em>base de donn\00E9es locale</em>.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_05', 'P7022_REMOTE_SERVER_ID',
  'attribute_07', 'N')).to_clob
);
