,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Fournissez le code PL/SQL \00E0 ex\00E9cuter. Les valeurs de colonne de la requ\00EAte d''automatisation sont disponibles en tant que variables attach\00E9es et par nom de colonne, par exemple <strong>:EMPNO</strong>, <strong>:ENAME</strong>, etc. Par ailleurs, &')
||unistr('PRODUCT_NAME. fournit les variables attach\00E9es g\00E9n\00E9riques suivantes :'),
'</p>',
'<ul>',
unistr('    <li><strong>APEX$AUTOMATION_ROW_PK :</strong> si une colonne de cl\00E9 primaire a \00E9t\00E9 d\00E9finie, cette variable attach\00E9e contient la valeur de cl\00E9 primaire.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ROW_NUM :</strong> pour les automatisations bas\00E9es sur une requ\00EAte, cette variable attach\00E9e contient le nombre de lignes en cours.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ERROR_ROWS :</strong> pour les automatisations bas\00E9es sur une requ\00EAte, cette variable attach\00E9e contient le nombre de lignes dans lesquelles les actions ont g\00E9n\00E9r\00E9 des erreurs.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_LASTRUN_ISO :</strong> contient l''horodatage de l''ex\00E9cution d''automatisation <em>pr\00E9c\00E9dente</em>, au format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
'</ul>',
'<p>',
'    ',
'</p>',
'<p>',
unistr('    Pour consigner des messages dans le journal d''ex\00E9cution, utilisez les proc\00E9dures <strong>LOG_INFO</strong>, <strong>LOG_WARN</strong> et <strong>LOG_ERROR</strong> dans le package <strong>APEX_AUTOMATION</strong>.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
