wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1401497341619801.4002)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Automation'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    c_item_prefix         constant varchar2(15) := ''P7031_''',
'                                                || case when :P7031_LOCATION = ''REMOTE'' then ''REMOTE_'' end;',
'',
'    l_automation_id       number;',
'',
'    l_query_type          wwv_flow_automations.query_type%type;',
'    l_query_owner         wwv_flow_automations.query_owner%type;',
'    l_query_table         wwv_flow_automations.query_table%type;',
'    l_query_source        wwv_flow_automations.query_source%type;',
'    l_result_type         wwv_flow_automations.result_type%type;',
'    l_query_match         wwv_flow_automations.query_match%type;',
'    l_query_columns       wwv_flow_automations.query_match%type;',
'',
'    l_remote_server_id    wwv_flow_automations.remote_server_id%type;',
'    l_source_id           wwv_flow_automations.document_source_id%type;',
'    l_web_src_module_id   wwv_flow_automations.web_src_module_id%type;',
'    l_array_column_id     wwv_flow_automations.array_column_id%type;',
'',
'    l_polling_interval    varchar2(32767);',
'begin',
'    case :P7030_POLLING_PREDEFINED',
'        when ''15M''      then l_polling_interval := ''FREQ=MINUTELY;INTERVAL=15'';',
'        when ''T1H''      then l_polling_interval := ''FREQ=HOURLY;INTERVAL=1;BYMINUTE=0'';',
'        when ''MIDNIGHT'' then l_polling_interval := ''FREQ=DAILY;INTERVAL=1;BYHOUR=0;BYMINUTE=0'';',
'        when ''CUSTOM''   then',
'            l_polling_interval := ''FREQ=''      || :P7030_POLLING_INTERVAL_TYPE || '';'' ||',
'                                  ''INTERVAL=''  || :P7030_POLLING_INTERVAL || '';'' ||',
'                                  case :P7030_POLLING_INTERVAL_TYPE',
'                                      when ''DAILY'' then',
'                                          ''BYHOUR=''   || to_char( to_date ( :P7030_POLLING_STARTAT_DAILY, ''HH24:MI'' ), ''FMHH24'' ) ||',
'                                          '';'' ||',
'                                          ''BYMINUTE='' || to_char( to_date ( :P7030_POLLING_STARTAT_DAILY, ''HH24:MI'' ), ''FMMI'' )',
'                                      when ''HOURLY'' then',
'                                          ''BYMINUTE='' || :P7030_POLLING_STARTAT_HOURLY',
'                                  end;',
'    end case;',
'',
'    if :P7031_LOCATION in ( ''LOCAL'', ''REMOTE'' ) then',
'        l_query_type  := v( c_item_prefix || ''SOURCE_TYPE'' );',
'        l_result_type := v( c_item_prefix || ''RESULT_TYPE'' );',
'',
'        case l_query_type',
'        when ''TABLE'' then',
'            l_query_owner := v( c_item_prefix || ''TABLE_OWNER'' );',
'            l_query_table := v( c_item_prefix || ''TABLE_NAME'' );',
'        when ''QUERY'' then',
'            l_query_source := v( c_item_prefix || ''SQL'' );',
'            l_query_type   := ''SQL'';',
'        when ''GRAPH'' then',
'            l_query_owner   := v( c_item_prefix || ''TABLE_OWNER'' );',
'            l_query_table   := v( c_item_prefix || ''GRAPH_NAME'' );',
'            l_query_match   := v( c_item_prefix || ''PQL_MATCH_CLAUSE'' );',
'            l_query_columns := v( c_item_prefix || ''PQL_COLUMNS_CLAUSE'' );',
'        end case;',
'',
'        l_remote_server_id := case when :P7031_LOCATION = ''REMOTE'' then :P7031_REMOTE_SERVER_ID end;',
'    elsif :P7031_LOCATION = ''WEB_SOURCE'' then',
'        l_result_type       := :P7031_WEB_SRC_RESULT_TYPE;',
'        l_web_src_module_id := :P7031_WEB_SRC_MODULE_ID;',
'        l_array_column_id   := :P7031_WEB_SRC_ARRAY_COL_ID;',
'    elsif :P7031_LOCATION = ''DUALITY_VIEW'' then',
'        l_result_type       := :P7031_DUALITY_VIEW_RESULT_TYPE;',
'        l_source_id         := :P7031_DUALITY_VIEW_ID;',
'        l_array_column_id   := :P7031_DV_ARRAY_COL_ID;',
'    elsif :P7031_LOCATION = ''JSON_COLLECTION'' then',
'        l_result_type       := :P7031_JSON_SOURCE_RESULT_TYPE;',
'        l_source_id         := :P7031_JSON_SOURCE_ID;',
'        l_array_column_id   := :P7031_JSON_SOURCE_ARRAY_COL_ID;',
'    end if;',
'',
'    :P7031_NEW_AUTOMATION_ID := wwv_flow_automation_dev.create_wizard (',
'                                    p_flow_id              => :FB_FLOW_ID,',
'                                    --',
'                                    p_name                 => :P7030_AUTOMATION_NAME,',
'                                    p_trigger_type         => :P7030_AUTOMATION_TYPE,',
'                                    p_polling_interval     => rtrim(l_polling_interval,'';'' ),',
'                                    --',
'                                    p_result_type          => l_result_type,',
'                                    p_location             => :P7031_LOCATION,',
'                                    p_remote_server_id     => l_remote_server_id,',
'                                    p_web_src_module_id    => l_web_src_module_id,',
'                                    p_array_column_id      => l_array_column_id,',
'                                    p_document_source_id   => l_source_id,',
'                                    p_query_type           => l_query_type,',
'                                    p_query_source         => l_query_source,',
'                                    p_query_owner          => l_query_owner,',
'                                    p_query_match          => l_query_match,',
'                                    p_query_columns        => l_query_columns,',
'                                    p_query_table          => l_query_table,',
'                                    --',
'                                    p_pk_column_name       => null );',
'end;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>unistr('L''automatisation a \00E9t\00E9 cr\00E9\00E9e et son \00E9tat est D\00E9sactiv\00E9. Cr\00E9ez \00E0 pr\00E9sent les <em>actions</em> \00E0 ex\00E9cuter en m\00EAme temps que l''automatisation.')
,p_internal_uid=>1401497341619801.4002
);
end;
