wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6707661430580950.4002)
,p_plug_name=>'A propos des sources JSON'
,p_title=>'A propos de'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--sideRegion:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>60
,p_plug_display_point=>'REGION_POSITION_03'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Les <strong>sources JSON</strong> dans &PRODUCT_NAME. comportent des informations sur le propri\00E9taire et le nom '),
unistr('    d''une table de base de donn\00E9es, qui peut \00EAtre une <em>table de collection JSON</em> ou une table brute avec des colonnes contenant'),
unistr('    des donn\00E9es JSON. Les <em>tables de collection JSON</em> sont disponibles dans Oracle Database 23ai ou version sup\00E9rieure. De plus,'),
unistr('    un <strong>profil de donn\00E9es</strong> est conserv\00E9 : il met en correspondance les attributs JSON'),
unistr('    avec les <em>colonnes</em> \00E0 des fins d''utilisation par les composants &PRODUCT_NAME..'),
'</p>',
'<p> ',
unistr('    Vous pouvez d\00E9finir une source JSON en utilisant la base de donn\00E9es locale ainsi qu''un service SQL compatible REST.'),
unistr('    Apr\00E8s avoir choisi la table et la colonne \00E0 utiliser, &PRODUCT_NAME. d\00E9termine le profil de donn\00E9es'),
unistr('    \00E0 partir des donn\00E9es r\00E9elles ou d''un fichier de <em>sch\00E9ma JSON</em> t\00E9l\00E9charg\00E9.'),
'</p>',
'<p>',
unistr('    Une fois cr\00E9\00E9e, la source JSON est disponible pour les composants de page tels que les <em>\00E9tats</em>, les <em>graphiques</em>, '),
unistr('    les <em>panneaux</em> ou autres, ainsi que pour les composants partag\00E9s tels que les <em>listes de valeurs</em>, les <em>automatisations</em>'),
unistr('    ou autres. Le package PL/SQL APEX_EXEC permet un acc\00E8s par programmation.'),
'</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a></p>'))
