,p_item_source_plug_id=>wwv_flow_imp.id(1433797531258727.4002)
,p_prompt=>'Mise en cache SQL distante'
,p_source=>'REMOTE_SQL_CACHING'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CACHING_MODE'
,p_lov=>'.'||wwv_flow_imp.id(225840272947805161)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Pas de mise en cache'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    S\00E9lectionnez la fa\00E7on dont le moteur &PRODUCT_NAME. peut mettre en cache des r\00E9ponses de source REST c\00F4t\00E9 serveur. Si la mise en cache est possible, le rendu du composant d\00E9pend des r\00E9sultats mis en cache plut\00F4t que d''une nouvelle extraction \00E0 pa')
||unistr('rtir du service Web. Seules les demandes HTTP GET seront mises en cache, pour r\00E9duire les demandes HTTP co\00FBteuses. Cette fonctionnalit\00E9 n''est pas li\00E9e aux capacit\00E9s de mise en cache du navigateur.</p>'),
'<p>',
'    Options disponibles :',
'</p>',
'<ul>',
unistr('    <li><strong>D\00E9sactiv\00E9 :</strong> le contenu n''est ni mis en cache, ni extrait de la source REST pour chaque demande.</li>'),
unistr('    <li><strong>Pour tous les utilisateurs :</strong> le contenu est mis en cache et utilis\00E9 par tous les utilisateurs.</li>'),
unistr('    <li><strong>Par utilisateur :</strong> le contenu est mis en cache sp\00E9cifiquement pour chaque utilisateur.</li>'),
unistr('    <li><strong>Par session :</strong> le contenu est mis en cache sp\00E9cifiquement pour chaque session.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
