,p_name=>'P8101_ERROR_CHECKS'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(1289319229814864296.4002)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result varchar2(2000);',
'begin',
'    for l_check in (',
'        select code',
'          from wwv_flow_advisor_checks',
'         where is_default = ''Y'' )',
'    loop',
'        l_result := case when l_result is not null then l_result||'':'' end||',
'                    l_check.code;',
'    end loop;',
'    --',
'    return l_result;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Erreurs :'
,p_source=>'ADVISOR_CHECKS'
,p_source_type=>'PREFERENCE'
,p_display_as=>'NATIVE_CHECKBOX'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_escape.html(description) as d,',
'       code as r',
'  from ( select nvl(chk.description, wwv_flow_lang.system_message(''ADVISOR.CHECK.DESC_''||chk.code)) as description,',
'                chk.code,',
'                chk.order_seq',
'           from wwv_flow_advisor_categories cat,',
'                wwv_flow_advisor_checks chk',
'          where cat.code        = ''ERROR''',
'            and chk.category_id = cat.id',
'            and chk.code       <> ''VERIFY_CLOB_PROPERTY''',
'            and chk.is_custom   = ''N''',
'            and (  chk.flow_id is null',
'                or chk.flow_id = :FB_FLOW_ID )',
'       )',
' order by order_seq'))
,p_label_alignment=>'ABOVE'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
unistr('    <dt>R\00E9f\00E9rences avec syntaxe de substitution</dt>'),
unistr('    <dd>L''\00E9l\00E9ment ou la colonne de panneau tabulaire r\00E9f\00E9renc\00E9 par ''&amp;P999_NAME.'' existe-t-il ?</dd>'),
unistr('    <dt>R\00E9f\00E9rences avec syntaxe de colonne</dt>'),
unistr('    <dd>La colonne d''\00E9tat r\00E9f\00E9renc\00E9e par #NAME# existe-t-elle ?</dd>'),
unistr('    <dt>R\00E9f\00E9rences avec syntaxe de variable attach\00E9e</dt>'),
unistr('    <dd>L''\00E9l\00E9ment ou la colonne r\00E9f\00E9renc\00E9 par '':P999_NAME'' existe-t-il ?</dd>'),
unistr('    <dt>R\00E9f\00E9rences d\00E9claratives d''\00E9l\00E9ments d''application, d''\00E9l\00E9ments de page, de colonnes ou de filtres d''\00E9tat interactif</dt>'),
unistr('    <dd>Les \00E9l\00E9ments et alias de colonne sp\00E9cifi\00E9s existent-ils ?</dd>'),
unistr('    <dt>Le num\00E9ro de page r\00E9f\00E9renc\00E9 existe</dt>'),
unistr('    <dd>Le num\00E9ro de page r\00E9f\00E9renc\00E9 existe-t-il ?</dd>'),
'    <dt>Est un code SQL ou PL/SQL valide</dt>',
unistr('    <dd>V\00E9rifie si l''instruction SQL ou le code PL/SQL est valide.</dd>'),
'    <dt>Les processus d''extraction, DML et MR* sont valides</dt>',
unistr('    <dd>V\00E9rifie si la table, les colonnes et la clause WHERE d''ex\00E9cution sont valides.</dd>'),
'    <dt>Branchement inconditionnel avant les autres branchements</dt>',
unistr('    <dd>Existe-t-il un branchement inconditionnel avant un autre branchement ? Si c''est le cas, l''autre ne sera jamais ex\00E9cut\00E9.</dd>'),
unistr('    <dt>Le bouton r\00E9f\00E9renc\00E9 dans l''op\00E9ration Lors de l''activation du bouton existe</dt>'),
unistr('    <dd>Le bouton r\00E9f\00E9renc\00E9 dans l''op\00E9ration "Lors de l''activation du bouton" d''un processus ou d''une validation existe-t-il ?</dd>'),
'    <dt>Le bouton n''est pas compatible avec les actions dynamiques</dt>',
unistr('    <dd>Les boutons poss\00E9dant un ID d\00E9fini dans les attributs de bouton, ou les boutons bas\00E9s sur des mod\00E8les qui r\00E9f\00E9rencent un mod\00E8le de bouton dans lequel le mod\00E8le ne contient pas la cha\00EEne de substitution #BUTTON_ID# ne sont pas compatibles avec')
||' les actions dynamiques.</dd>',
'</dl>'))
,p_encrypt_session_state_yn=>'N'
