,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Indique si la protection de statut de session est activ\00E9e ou d\00E9sactiv\00E9e. Lorsqu''elle est activ\00E9e, cette fonctionnalit\00E9 utilise les attributs de page <i>Protection d''acc\00E8s de page</i> et les attributs d''\00E9l\00E9ment <i>Protection de statut de session</i> c')
||unistr('onjointement avec les checksums situ\00E9s dans les URL "f?p=". Elle pr\00E9vient la fraude d''URL et les acc\00E8s non autoris\00E9s, ainsi que la modification du statut de session. '),
'<p />',
unistr('Lorsque cette fonctionnalit\00E9 est d\00E9sactiv\00E9e, les attributs de page et d''\00E9l\00E9ment associ\00E9s \00E0 la protection de statut de session ne sont pas pris en compte et les checksums ne sont pas inclus dans les URL "f?p=" g\00E9n\00E9r\00E9es.')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
