wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3201962690436619.4002)
,p_plug_name=>unistr('D\00E9finitions de t\00E2che')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Les <strong>d\00E9finitions de t\00E2che</strong> d\00E9finissent les propri\00E9t\00E9s d''une t\00E2che humaine.'),
unistr('    Elles servent \00E0 cr\00E9er des instances de t\00E2che, puis \00E0 effectuer l''action appropri\00E9e'),
unistr('    (par exemple, approbation ou rejet d''instances de t\00E2che). Les t\00E2ches peuvent \00E9galement \00EAtre'),
unistr('    demand\00E9es, lib\00E9r\00E9es, d\00E9l\00E9gu\00E9es ou annul\00E9es.'),
'</p>',
'<p>',
unistr('    Les <strong>participants de d\00E9finition de t\00E2che</strong> d\00E9finissent les participants'),
unistr('    d''une t\00E2che humaine qui peuvent agir sur cette t\00E2che. Ils peuvent \00EAtre de type'),
unistr('    <strong>Propri\00E9taire potentiel</strong> ou <strong>Administrateur m\00E9tier'),
'    </strong>.',
'</p>',
'<p>',
unistr('    Les <strong>param\00E8tres de d\00E9finition de t\00E2che</strong> d\00E9finissent les param\00E8tres d''une'),
unistr('     t\00E2che humaine. Il s''agit g\00E9n\00E9ralement d''attributs d''un syst\00E8me d''enregistrements'),
unistr('    pour lequel la t\00E2che a \00E9t\00E9 d\00E9finie. Ils constituent la charge utile de la t\00E2che.'),
'</p>',
'<p>',
unistr('    Les <strong>actions de d\00E9finition de t\00E2che</strong> se d\00E9clenchent une fois pour un \00E9v\00E9nement effectu\00E9'),
unistr('    sur la t\00E2che. Voici la liste des \00E9v\00E9nements possibles :'),
'</p>',
'<ul>',
'    <li><strong>Demander</strong></li>',
'    <li><strong>Terminer</strong></li>',
unistr('    <li><strong>D\00E9l\00E9guer</strong></li>'),
unistr('    <li><strong>Mettre \00E0 jour le commentaire</strong></li>'),
unistr('    <li><strong>Mettre \00E0 jour la priorit\00E9</strong></li>'),
unistr('    <li><strong>Mettre \00E0 jour le param\00E8tre</strong></li>'),
unistr('    <li><strong>Lib\00E9rer</strong></li>'),
'    <li><strong>Annuler</strong></li>',
unistr('    <li><strong>Cr\00E9er</strong></li>'),
'    <li><strong>Demander des informations</strong></li>',
'    <li><strong>Soumettre les informations</strong></li>',
'    <li><strong>Avant l''expiration</strong></li>',
'    <li><strong>Expiration</strong></li>',
'</ul>',
'<p>',
'    <a target="_blank" href="&SYSTEM_HELP_URL.">En savoir plus...</a>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
