wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2001246523304308.4002)
,p_name=>'P9502_VACATION_RULE_PROC'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(7705803391510760.4002)
,p_item_source_plug_id=>wwv_flow_imp.id(5402471995904376.4002)
,p_prompt=>unistr('Proc\00E9dure de r\00E8gle de cong\00E9s')
,p_source=>'VACATION_RULE_PROCEDURE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>100
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez le nom d''une proc\00E9dure PL/SQL au format <strong>[schemaName.[packageName.]]procedureName</strong>. '),
unistr('La proc\00E9dure doit renvoyer des participants de remplacement suppl\00E9mentaires pour les d\00E9finitions de cette t\00E2che.'),
unistr('La proc\00E9dure de r\00E8gle de cong\00E9s doit impl\00E9menter l''interface suivante.</p>'),
'<pre>',
'    procedure my_vacation_rule (',
'        p_param    in apex_approval.t_vacation_rule_input,',
'        p_result  out apex_approval.t_vacation_rule_output );',
'</pre>',
unistr('<p>L''entr\00E9e de proc\00E9dure est de type <strong>apex_approval.t_vacation_rule_input</strong> et la sortie de r\00E9sultat de type <strong>apex_approval.t_vacation_rule_output</strong>. </p>'),
'<p>',
unistr('L''exemple ci-apr\00E8s montre une impl\00E9mentation de proc\00E9dure de r\00E8gle de cong\00E9s selon laquelle SCOTT est ajout\00E9 en tant que participant de remplacement lorsque JANE '),
unistr('est en cong\00E9 maternit\00E9.</p>'),
'<pre>',
'',
'    procedure alternate_job_approvers(',
'                p_param    in apex_approval.t_vacation_rule_input,',
'                p_result  out apex_approval.t_vacation_rule_result)',
'    is ',
'        l_result            apex_approval.t_vacation_rule_result;',
'        l_changes           apex_approval.t_task_participant_changes;',
'        l_participants      apex_approval.t_task_participants;',
'        l_new_participant   apex_approval.t_task_participant;',
'        l_old_participant   apex_approval.t_task_participant;',
'        l_has_changed       boolean                             := false;',
'        l_index             pls_integer                         := 1;',
'    begin',
'        l_participants := p_param.original_participants;',
'        for i in 1..l_participants.count loop',
'            if l_participants(i).value = ''JANE'' then',
'                l_old_participant               :=  l_participants(i);',
'                l_new_participant.value         := ''SCOTT'';',
'                l_new_participant.type          := ''POTENTIAL_OWNER'';',
'                l_new_participant.identity      := ''USER'';',
'                l_has_changed                   := true;',
'            end if;',
'        end loop;',
'        if l_has_changed then',
'            l_participants(l_participants.count + 1) := l_new_participant;',
'        ',
'            l_changes(l_index).old_participant   := l_old_participant;',
'            l_changes(l_index).new_participant   := l_new_participant;',
'            l_changes(l_index).change_reason     := ''Jane is out on maternity leave'';',
'        end if;',
'        l_result.participant_changes            := l_changes;',
'        l_result.has_participant_changes        := l_has_changed;',
'        p_result                                := l_result;',
'    end;',
'</pre>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
