 p_id=>wwv_flow_imp.id(31864742114684957.4002)
,p_plug_name=>' Exemples'
,p_parent_plug_id=>wwv_flow_imp.id(3379050589607834.4002)
,p_region_template_options=>'#DEFAULT#:is-collapsed:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(689970285456172024.4002)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Exemple 1 : envoi d''un courriel. Il est suppos\00E9 qu''un mod\00E8le de courriel nomm\00E9 <strong>ORDER</strong> existe, avec les valeurs de r\00E9serve utilis\00E9es dans le '),
unistr('    param\00E8tre <strong>p_placeholders</strong>.'),
'</p>',
'<pre>',
'begin',
'    apex_mail.send (',
'        p_template_static_id => ''ORDER'',',
'        p_placeholders       => ''{ "ORDER_NUMBER": '' || :ORDER_NUMBER ||',
'                                  ''"ORDER_DATE":"''   || to_char( :ORDER_DATE, ''YYYY-MM-DD'' ) || ''", ''',
'                                  ''"ORDER_TOTAL":''   || :ORDER_TOTAL || ',
'                                ''}'',',
'        p_to                 => ''some_user@somewhere.com'' );',
'end;',
'</pre>',
'<p>',
unistr('    Exemple 2 : insertion d''une ligne dans une autre table. Si la valeur :SAL est NULL, un message est \00E9crit dans le journal de l''historique de la t\00E2che.'),
'</p>',
'<pre>',
'begin',
'    insert into other_table( empno, ename, sal )',
'                     values( :EMPNO, :ENAME, :SAL );',
'    if :SAL is null then',
'        apex_approval.add_to_history( ''EMPNO '' || :APEX$TASK_PK ||'' has a NULL Salary'');',
'    end if;',
'end;',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
