wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1924412464455025.4002)
,p_name=>'P9506_ON_EVENT'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(3379750715607841.4002)
,p_item_source_plug_id=>wwv_flow_imp.id(3379750715607841.4002)
,p_prompt=>unistr('En cas d''\00E9v\00E9nement')
,p_source=>'ON_EVENT'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'TASK_ACTION_ON_EVENTS'
,p_lov=>'.'||wwv_flow_imp.id(2058881135907033)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4002)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Ev\00E9nement pour lequel l''action sera ex\00E9cut\00E9e. Les actions peuvent \00EAtre ex\00E9cut\00E9es pour les \00E9v\00E9nements suivants sur la t\00E2che'),
'<dl>',
'    <dt>Demander</dt>',
unistr('    <dd>Lorsque la t\00E2che est demand\00E9e par un propri\00E9taire potentiel. Demander une t\00E2che la fait passer de l''\00E9tat Non affect\00E9 \00E0 Affect\00E9.</dd>'),
'    <dt>Terminer</dt>',
unistr('    <dd>Lorsque la t\00E2che est en fin d''ex\00E9cution. De plus, pour une t\00E2che d''approbation, vous pouvez choisir si l''action survient uniquement en cas de r\00E9sultat Approuv\00E9 ou Rejet\00E9.</dd>'),
unistr('    <dt>D\00E9l\00E9guer</dt>'),
unistr('    <dd>Lorsque la t\00E2che est en cours de d\00E9l\00E9gation \00E0 un autre propri\00E9taire potentiel de la t\00E2che.</dd>'),
unistr('    <dt>Mettre \00E0 jour le commentaire</dt>'),
unistr('    <dd>Lorsqu''un commentaire est ajout\00E9 \00E0 la t\00E2che.</dd>'),
unistr('    <dt>Mettre \00E0 jour la priorit\00E9</dt>'),
unistr('    <dd>Lorsque la priorit\00E9 de la t\00E2che est en cours de mise \00E0 jour.</dd>'),
unistr('    <dt>Mettre \00E0 jour le param\00E8tre</dt>'),
unistr('    <dd>Lorsque les param\00E8tres de la t\00E2che sont en cours de mise \00E0 jour.</dd>'),
unistr('    <dt>Lib\00E9rer</dt>'),
unistr('    <dd>Lorsque la t\00E2che est en cours de lib\00E9ration. Cette op\00E9ration fait passer la t\00E2che de l''\00E9tat Affect\00E9 \00E0 Non affect\00E9.</dd>'),
'    <dt>Annuler</dt>',
unistr('    <dd>Lorsque la t\00E2che est en cours d''annulation, ne montrant ainsi plus d''int\00E9r\00EAt pour la t\00E2che.</dd>'),
unistr('    <dt>Cr\00E9er</dt>'),
unistr('    <dd>Lorsque la t\00E2che est en cours de cr\00E9ation.</dd>'),
'    <dt>Demander des informations</dt>',
unistr('    <dd>Lorsque des informations sont demand\00E9es \00E0 l''initiateur de la t\00E2che.</dd>'),
'    <dt>Soumettre les informations</dt>',
'    <dd>Lorsque des informations sont soumises par l''initiateur au demandeur.</dd>',
'    <dt>Avant expiration</dt>',
unistr('    <dd>Avant la date d''\00E9ch\00E9ance de la t\00E2che et lorsque la t\00E2che est sur le point d''expirer. Un intervalle ISO/SQL doit \00EAtre indiqu\00E9.</dd>'),
'    <dt>Expiration</dt>',
unistr('    <dd>Lorsque la date d''\00E9ch\00E9ance de la t\00E2che est atteinte et que la t\00E2che expire.</dd>'),
' </dl>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
