wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1974380900697179.4002)
,p_name=>'P9506_LOCAL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(92085503084145721.4002)
,p_prompt=>'Code'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4002)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Fournissez le code PL/SQL \00E0 ex\00E9cuter. Les valeurs de colonne de la requ\00EAte d''action de d\00E9finition de t\00E2che sont disponibles en tant que variables attach\00E9es et par nom de colonne, par exemple <strong>:EMPNO</strong>, <strong>:ENAME</strong>, etc. ')
||unistr('Par ailleurs, APEX fournit les variables attach\00E9es g\00E9n\00E9riques suivantes :'),
'</p>',
'<ul>',
unistr('    <li><strong>APEX$TASK_PK :</strong> si une colonne de cl\00E9 primaire a \00E9t\00E9 d\00E9finie, cette variable attach\00E9e contient la valeur de cl\00E9 primaire.</li>'),
unistr('    <li><strong>APEX$TASK_ID :</strong> cette variable attach\00E9e contient l''ID de la t\00E2che pour laquelle l''action est d\00E9finie.</li>'),
unistr('    <li><strong>APEX$TASK_SUBJECT :</strong> cette variable attach\00E9e contient l''objet de la t\00E2che pour laquelle l''action est d\00E9finie.</li>'),
unistr('    <li><strong>APEX$TASK_STATE :</strong> cette variable attach\00E9e contient l''\00E9tat en cours de la t\00E2che pour laquelle l''action est d\00E9finie.</li>'),
unistr('    <li><strong>APEX$TASK_OUTCOME :</strong> cette variable attach\00E9e contient le r\00E9sultat de la t\00E2che pour laquelle l''action est d\00E9finie. Elle est remplie uniquement pour les t\00E2ches pr\00E9sentant l''\00E9tat <strong>Termin\00E9</strong>.</li>'),
unistr('    <li><strong>APEX$TASK_CREATED_ON :</strong> contient l''horodatage de la cr\00E9ation de t\00E2che, au format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_INITIATOR :</strong> contient le nom de l''utilisateur qui a lanc\00E9 la t\00E2che. Cette valeur est d\00E9finie par d\00E9faut sur l''utilisateur connect\00E9 si elle n''est pas explicitement indiqu\00E9e dans le type de processus de page <strong>T\00E2')
||unistr('che humaine - Cr\00E9er</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_DUE_ON :</strong> contient l''horodatage de la date d''\00E9ch\00E9ance de la t\00E2che, au format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_OWNER :</strong> contient le nom de l''utilisateur auquel la t\00E2che est affect\00E9e actuellement.</li>'),
unistr('    <li> Les param\00E8tres de la d\00E9finition de t\00E2che sont \00E9galement disponibles en tant que variables attach\00E9es.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
