wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1497633323762208.4002)
,p_validation_name=>'Before Expiration Interval is valid'
,p_validation_sequence=>90
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_due_on timestamp := null;',
'begin',
'    if :P9506_BEFORE_EXPIRE_INTERVAL is null then',
'        if :P9506_ON_EVENT = ''BEFORE_EXPIRE'' then    ',
'            return false;',
'        end if;',
'        return true;',
'    else',
'        -- check for negative intervals',
'        if :P9506_BEFORE_EXPIRE_INTERVAL like ''-%'' then     ',
'            return false;',
'        end if;',
'        select systimestamp + to_dsinterval(:P9506_BEFORE_EXPIRE_INTERVAL) ',
'          into l_due_on ',
'          from sys.dual;',
'    end if; ',
'    return true;',
'exception',
'    when others then',
'    return false;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('L''<strong>intervalle avant expiration</strong> doit avoir une expression d''intervalle ISO ou SQL positive si <strong>En cas d''\00E9v\00E9nement</strong> a la valeur <strong>Avant expiration</strong>')
,p_associated_item=>wwv_flow_imp.id(1505449566422315.4002)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(3600123052108601.4002)
,p_validation_name=>'Check for Expire actions'
,p_validation_sequence=>100
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_is_valid          boolean;',
'    l_due_on_type       varchar2(30);',
'    l_expiration_policy varchar2(30);',
'begin',
'    select due_on_type ,expiration_policy',
'      into l_due_on_type,l_expiration_policy',
'      from wwv_flow_task_defs',
'     where id = :P9506_TASK_DEF_ID',
'       and security_group_id = :WORKSPACE_ID;',
'',
'     if (l_due_on_type is null or l_expiration_policy = ''NONE'')',
'        and :P9506_ON_EVENT in (''BEFORE_EXPIRE'', ''EXPIRE'') then',
'        return false;',
'     end if;',
'',
'     return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('La d\00E9finition de t\00E2che doit d\00E9finir un <strong>type de date d''\00E9ch\00E9ance</strong> et une <strong>strat\00E9gie d''expiration</strong> pour utiliser les \00E9v\00E9nements <strong>Avant expiration</strong> et <strong>Expiration</strong>.')
,p_associated_item=>wwv_flow_imp.id(1924412464455025.4002)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
