,p_plug_template=>wwv_flow_imp.id(646287526247383209.4002)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select w.id,',
'       w.flow_id,',
'       w.name,',
'       wwv_flow_utilities.prepare_url(''f?p=4000:9600:''||:flow_session||''::NO:1:FB_FLOW_ID,F4000_P1_FLOW:''||:FB_FLOW_ID||'',''||:FB_FLOW_ID||''#8800:''||w.id )',
'       as workflow_url,',
'       w.static_id,',
'       w.title,',
'       w.workflow_comment,',
'       w.last_updated_by,',
'       w.last_updated_on,',
'       (select count(v.ID) ',
'          from wwv_flow_workflow_versions v ',
'         where v.workflow_id=w.id',
'           and v.security_group_id = w.security_group_id',
'           and v.state = ''ACTIVE'') active_version_count,',
'       (select count(v.id) ',
'          from wwv_flow_workflow_versions v ',
'         where v.workflow_id=w.id',
'           and v.security_group_id = w.security_group_id',
'           and v.state = ''DEVELOPMENT'') dev_version_count,',
'       (select count(v.id) ',
'          from wwv_flow_workflow_versions v ',
'         where v.workflow_id=w.id',
'           and v.security_group_id = w.security_group_id',
'           and v.state = ''INACTIVE'') inactive_version_count,',
'       (select count(p.id) ',
'          from wwv_flow_workflow_variables p',
'         where p.workflow_id=w.id ',
'           and p.security_group_id = w.security_group_id',
'           and p.direction != ''VARIABLE'') params_count',
' from wwv_flow_workflows w ',
'where w.flow_id = :FB_FLOW_ID ',
'  and w.security_group_id = :WORKSPACE_ID'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Etat sur les automatisations '
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
