 p_id=>wwv_flow_imp.id(228259524730656176.4002)
,p_plug_name=>unistr('Services d''intelligence artificielle g\00E9n\00E9rative')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4002)
,p_plug_display_sequence=>30
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Les informations des services d''intelligence artificielle g\00E9n\00E9rative sont stock\00E9es en tant qu''objet <strong>Intelligence artificielle g\00E9n\00E9rative</strong>. Les services d''intelligence artificielle g\00E9n\00E9rative offrent une abstraction des solutions d''')
||unistr('intelligence artificielle g\00E9n\00E9ratives '),
unistr(' les plus connues du march\00E9, comme Open AI, Cohere et d''autres. L''API publique <code>APEX_AI</code> r\00E9f\00E9rence les services d''intelligence artificielle g\00E9n\00E9rative configur\00E9s ici.</p>'),
unistr('<p>Les services d''intelligence artificielle g\00E9n\00E9rative sont stock\00E9s au niveau de l''espace de travail et sont donc visibles dans toutes les applications. Lorsque vous exportez une application, les services d''intelligence artificielle g\00E9n\00E9rative utilis')
||unistr('\00E9s sont ajout\00E9s au fichier d''export. Lorsque vous importez l''application dans un autre espace de travail, &PRODUCT_NAME. v\00E9rifie si l''espace de travail cible contient d\00E9j\00E0 des services d''intelligence artificielle g\00E9n\00E9rative avec le m\00EAme <strong>ID st')
||unistr('atique</strong>. S''il existe d\00E9j\00E0 un service d''intelligence artificielle g\00E9n\00E9rative, l''application l''utilise. Dans le cas contraire, les services d''intelligence artificielle g\00E9n\00E9rative du fichier d''import sont cr\00E9\00E9s dans l''espace de travail cible.</p')
||'>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
