wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1875728754116052.4002)
,p_validation_name=>'Cannot delete used Vector Provider'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id',
'  from wwv_remote_servers s ',
' where s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and s.id                 = :P9811_ID',
'   and s.server_type        = ''VECTOR''',
'   and exists ( select 1',
'                  from wwv_flow_search_configs sc',
'                 where sc.emb_ai_provider_id = s.id',
'                   and sc.security_group_id  = s.security_group_id )'))
